module mem_ctrl (
    input logic clk,
    input logic [1:0] cmd,
    input logic [1:0] burst,
    output logic ack,
    output logic err
);
    always_ff @(posedge clk) begin
        ack <= 0;
        err <= 0;
        case (cmd)
            2'b00: begin // READ
                case (burst)
                    2'b00, 2'b01: ack <= 1;
                    default: err <= 1;
                endcase
            end

            2'b01: begin // WRITE
                case (burst)
                    2'b00, 2'b10: ack <= 1;
                    default: err <= 1;
                endcase
            end

            default: err <= 1;
        endcase
    end
endmodule

module mealy_101_detector (
    input  logic clk,
    input  logic rst_n,
    input  logic data_in,
    output logic detected
);

    // State encoding
    typedef enum logic [1:0] {
        S0,  // No bits matched
        S1,  // Matched '1'
        S2   // Matched '10'
    } state_t;

    state_t current_state, next_state;

    // Sequential block: state update
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    // Combinational block: next state logic
    always_comb begin
        case (current_state)
            S0: next_state = (data_in == 1'b1) ? S1 : S0;
            S1: next_state = (data_in == 1'b0) ? S2 : S1;
            S2: next_state = (data_in == 1'b1) ? S1 : S0;
            default: next_state = S0;
        endcase
    end

    // Combinational block: output logic (Mealy)
    always_comb begin
        detected = 1'b0;  // Default
        case (current_state)
            S2: if (data_in == 1'b1) detected = 1'b1;
            default: detected = 1'b0;
        endcase
    end

endmodule

