    case(voltage)
      3'b000: voltage <= up ? 3'b001 : 3'b000;
      3'b001: voltage <= up ? 3'b010 : (dn ? 3'b000 : 3'b001);
      3'b010: voltage <= up ? 3'b011 : (dn ? 3'b001 : 3'b010);
      3'b011: voltage <= up ? 3'b100 : (dn ? 3'b010 : 3'b011);
      3'b100: voltage <= up ? 3'b101 : (dn ? 3'b011 : 3'b100);
      3'b101: voltage <= up ? 3'b110 : (dn ? 3'b100 : 3'b101);
      3'b110: voltage <= dn ? 3'b101 : 3'b110;
      3'b111: voltage <= 3'b011;
    endcase
  end
end
