      [3:7]: begin
        if (inc && hist_bin < 4'd12) hist_bin <= hist_bin + 1;
        if (dec && hist_bin > 4'd0) hist_bin <= hist_bin - 1;
      end
      [8:12]: hist_bin <= dec ? hist_bin - 1 : hist_bin;
      [13:15]: hist_bin <= 4'd7;
    endcase
  end
end
endmodule

