module case_saturation(input logic clk, rst, add, sub, output logic [3:0] sat_val);
always_ff @(posedge clk or posedge rst) begin
  if (rst) sat_val <= 4'b1000;
  else begin
    case(sat_val)
      4'b0000: sat_val <= add ? 4'b0001 : 4'b0000;
      4'b1111: sat_val <= sub ? 4'b1110 : 4'b1111;
      default: begin
        if (add && sat_val != 4'b1111) sat_val <= sat_val + 1;
        if (sub && sat_val != 4'b0000) sat_val <= sat_val - 1;
      end
    endcase
  end
end
endmodule

module case_noise_shape(input logic clk, rst, dither, output logic [2:0] noise);
always_ff @(posedge clk or posedge rst) begin
  if (rst) noise <= 3'b000;
  else begin
    case(noise)
      3'b000: noise <= dither ? 3'b001 : 3'b111;
      3'b001: noise <= 3'b011;
      3'b010: noise <= 3'b101;
      3'b011: noise <= 3'b010;
      3'b100: noise <= 3'b110;
      3'b101: noise <= 3'b100;
      3'b110: noise <= 3'b001;
      3'b111: noise <= 3'b000;
    endcase
  end
end
endmodule

module case_bias_adj(input logic clk, rst, inc, dec, output logic [3:0] bias);
always_ff @(posedge clk or posedge rst) begin
  if (rst) bias <= 4'b1000;
  else begin
    case(bias) inside
      [0:3]: begin
        if (inc) bias <= bias + 2;
        if (dec) bias <= (bias == 0) ? 0 : bias - 1;
      end
      [4:11]: begin
        if (inc && bias < 4'b1111) bias <= bias + 1;
        if (dec && bias > 4'b0000) bias <= bias - 1;
      end
      [12:15]: begin
        if (inc) bias <= 4'b1111;
        if (dec) bias <= bias - 2;
      end
    endcase
  end
end
endmodule

module case_sync_pattern(input logic clk, rst, detect, output logic [4:0] sync);
always_ff @(posedge clk or posedge rst) begin
  if (rst) sync <= 5'b00001;
  else begin
    casez(sync)
      5'b00001: sync <= detect ? 5'b00010 : 5'b10000;
      5'b0001?: sync <= sync << 1;
      5'b001??: sync <= 5'b01000;
      5'b01???: sync <= 5'b10000;
      5'b1????: sync <= 5'b00001;
      default: sync <= 5'b00001;
    endcase
  end
end
endmodule

module case_quantizer(input logic clk, rst, step, output logic [3:0] q_level);
always_ff @(posedge clk or posedge rst) begin
  if (rst) q_level <= 4'b1000;
  else begin
    case(q_level) inside
      [0:1]: q_level <= step ? 4'b0010 : 4'b0001;
      [2:5]: begin
        if (step) q_level <= (q_level == 5) ? 4'b1000 : q_level + 1;
        else q_level <= (q_level == 2) ? 4'b0001 : q_level - 1;
      end
      [6:9]: q_level <= step ? 4'b1010 : 4'b0101;
      [10:13]: q_level <= step ? 4'b1110 : 4'b1011;
      [14:15]: q_level <= 4'b1000;
    endcase
  end
end
endmodule

module case_delay_chain(input logic clk, rst, propagate, output logic [3:0] delay_out);
always_ff @(posedge clk or posedge rst) begin
  if (rst) delay_out <= 4'b0001;
  else begin
    case(delay_out)
      4'b0000: delay_out <= 4'b0001;
      4'b0001: delay_out <= propagate ? 4'b0010 : 4'b0001;
      4'b0010: delay_out <= 4'b0100;
      4'b0100: delay_out <= 4'b1000;
      4'b1000: delay_out <= 4'b0001;
      default: delay_out <= 4'b0001;
    endcase
  end
end
endmodule

module case_freq_hop(input logic clk, rst, hop_en, output logic [4:0] freq_code);
always_ff @(posedge clk or posedge rst) begin
  if (rst) freq_code <= 5'b00001;
  else begin
    case(freq_code)
      5'b00001: freq_code <= hop_en ? 5'b00011 : 5'b00001;
      5'b00011: freq_code <= 5'b00101;
      5'b00101: freq_code <= 5'b00111;
      5'b00111: freq_code <= 5'b01011;
      5'b01011: freq_code <= 5'b01101;
      5'b01101: freq_code <= 5'b01111;
      5'b01111: freq_code <= 5'b10001;
      5'b10001: freq_code <= 5'b10011;
      5'b10011: freq_code <= 5'b10101;
      5'b10101: freq_code <= 5'b10111;
      5'b10111: freq_code <= 5'b11001;
      5'b11001: freq_code <= 5'b11011;
      5'b11011: freq_code <= 5'b11101;
      5'b11101: freq_code <= 5'b11111;
      5'b11111: freq_code <= 5'b00001;
      default: freq_code <= 5'b00001;
    endcase
  end
end
endmodule

module case_crc_update(input logic clk, rst, data_bit, output logic [3:0] crc);
always_ff @(posedge clk or posedge rst) begin
  if (rst) crc <= 4'b0000;
  else begin
    case(crc[3])
      1'b0: crc <= {crc[2:0], data_bit} ^ 4'b0000;
      1'b1: crc <= {crc[2:0], data_bit} ^ 4'b1001;
    endcase
  end
end
endmodule

module case_brightness(input logic clk, rst, inc, dec, output logic [5:0] brightness);
always_ff @(posedge clk or posedge rst) begin
  if (rst) brightness <= 6'd32;
  else begin
    case(brightness) inside
      [0:15]: brightness <= inc ? brightness + 4 : brightness;
      [16:31]: begin
        if (inc) brightness <= brightness + 2;
        if (dec) brightness <= brightness - 1;
      end
      [32:47]: begin
        if (inc) brightness <= brightness + 1;
        if (dec) brightness <= brightness - 2;
      end
      [48:63]: brightness <= dec ? brightness - 4 : brightness;
    endcase
  end
end
endmodule

module case_scramble(input logic clk, rst, scramble_en, output logic [3:0] scrambler);
always_ff @(posedge clk or posedge rst) begin
  if (rst) scrambler <= 4'b1111;
  else begin
    case(scrambler)
      4'b0000: scrambler <= scramble_en ? 4'b0011 : 4'b0000;
      4'b0001: scrambler <= 4'b0110;
      4'b0010: scrambler <= 4'b1100;
      4'b0011: scrambler <= 4'b1001;
      4'b0100: scrambler <= 4'b0011;
      4'b0101: scrambler <= 4'b0110;
      4'b0110: scrambler <= 4'b1100;
      4'b0111: scrambler <= 4'b1001;
      4'b1000: scrambler <= 4'b0011;
      4'b1001: scrambler <= 4'b0110;
      4'b1010: scrambler <= 4'b1100;
      4'b1011: scrambler <= 4'b1001;
      4'b1100: scrambler <= scramble_en ? 4'b0001 : 4'b1100;
      4'b1101: scrambler <= 4'b0110;
      4'b1110: scrambler <= 4'b1100;
      4'b1111: scrambler <= 4'b1001;
    endcase
  end
end
endmodule

module case_phase_shift(input logic clk, rst, advance, output logic [2:0] phase);
always_ff @(posedge clk or posedge rst) begin
  if (rst) phase <= 3'b000;
  else begin
    case(phase)
      3'b000: phase <= advance ? 3'b001 : 3'b111;
      3'b001: phase <= advance ? 3'b010 : 3'b000;
      3'b010: phase <= advance ? 3'b011 : 3'b001;
      3'b011: phase <= advance ? 3'b100 : 3'b010;
      3'b100: phase <= advance ? 3'b101 : 3'b011;
      3'b101: phase <= advance ? 3'b110 : 3'b100;
      3'b110: phase <= advance ? 3'b111 : 3'b101;
      3'b111: phase <= advance ? 3'b000 : 3'b110;
    endcase
  end
end
endmodule

module case_gain_ctrl(input logic clk, rst, boost, cut, output logic [4:0] gain);
always_ff @(posedge clk or posedge rst) begin
  if (rst) gain <= 5'd12;
  else begin
    case(gain) inside
      [0:3]: gain <= boost ? gain + 3 : gain;
      [4:7]: begin
        if (boost) gain <= gain + 2;
        if (cut) gain <= gain - 1;
      end
      [8:11]: begin
        if (boost) gain <= gain + 1;
        if (cut) gain <= gain - 1;
      end
      [12:15]: begin
        if (boost) gain <= gain + 1;
        if (cut) gain <= gain - 2;
      end
      [16:19]: gain <= cut ? gain - 3 : gain;
      [20:31]: gain <= 5'd12;
    endcase
  end
end
endmodule

module case_pulse_pos(input logic clk, rst, shift_left, shift_right, output logic [3:0] pulse_pos);
always_ff @(posedge clk or posedge rst) begin
  if (rst) pulse_pos <= 4'b0001;
  else begin
    case(pulse_pos)
      4'b0000: pulse_pos <= 4'b0001;
      4'b0001: pulse_pos <= shift_right ? 4'b0010 : (shift_left ? 4'b1000 : 4'b0001);
      4'b0010: pulse_pos <= shift_right ? 4'b0100 : (shift_left ? 4'b0001 : 4'b0010);
      4'b0100: pulse_pos <= shift_right ? 4'b1000 : (shift_left ? 4'b0010 : 4'b0100);
      4'b1000: pulse_pos <= shift_right ? 4'b0001 : (shift_left ? 4'b0100 : 4'b1000);
      default: pulse_pos <= 4'b0001;
    endcase
  end
end
endmodule

module case_error_corr(input logic clk, rst, error, correct, output logic [2:0] error_state);
always_ff @(posedge clk or posedge rst) begin
  if (rst) error_state <= 3'b000;
  else begin
    case(error_state)
      3'b000: error_state <= error ? 3'b001 : 3'b000;
      3'b001: error_state <= correct ? 3'b010 : 3'b001;
      3'b010: error_state <= 3'b011;
      3'b011: error_state <= 3'b100;
      3'b100: error_state <= 3'b101;
      3'b101: error_state <= 3'b110;
      3'b110: error_state <= 3'b111;
      3'b111: error_state <= 3'b000;
    endcase
  end
end
endmodule

module case_comp_thresh(input logic clk, rst, sample, output logic [3:0] threshold);
always_ff @(posedge clk or posedge rst) begin
  if (rst) threshold <= 4'b1000;
  else begin
    case(threshold) inside
      [0:3]: threshold <= sample ? threshold + 2 : threshold;
      [4:7]: threshold <= sample ? threshold + 1 : threshold - 1;
      [8:11]: threshold <= sample ? threshold : threshold - 2;
      [12:15]: threshold <= 4'b1000;
    endcase
  end
end
endmodule

module case_wave_shape(input logic clk, rst, mode, output logic [3:0] wave);
always_ff @(posedge clk or posedge rst) begin
  if (rst) wave <= 4'b0000;
  else begin
    case(wave)
      4'b0000: wave <= mode ? 4'b0001 : 4'b1111;
      4'b0001: wave <= 4'b0011;
      4'b0010: wave <= 4'b0111;
      4'b0011: wave <= mode ? 4'b0111 : 4'b0001;
      4'b0100: wave <= 4'b1000;
      4'b0101: wave <= 4'b1010;
      4'b0110: wave <= 4'b1100;
      4'b0111: wave <= mode ? 4'b1111 : 4'b0110;
      4'b1000: wave <= 4'b1001;
      4'b1001: wave <= 4'b1011;
      4'b1010: wave <= 4'b1101;
      4'b1011: wave <= 4'b1110;
      4'b1100: wave <= 4'b1101;
      4'b1101: wave <= 4'b1110;
      4'b1110: wave <= 4'b1111;
      4'b1111: wave <= mode ? 4'b0000 : 4'b1110;
    endcase
  end
end
endmodule

module case_refresh_ctrl(input logic clk, rst, refresh, output logic [4:0] refresh_cnt);
always_ff @(posedge clk or posedge rst) begin
  if (rst) refresh_cnt <= 5'd0;
  else begin
    case(refresh_cnt) inside
      [0:7]: refresh_cnt <= refresh ? refresh_cnt + 1 : refresh_cnt;
      [8:15]: refresh_cnt <= refresh_cnt - 1;
      [16:23]: refresh_cnt <= 5'd24;
      [24:31]: refresh_cnt <= 5'd0;
    endcase
  end
end
endmodule

module case_dither_seq(input logic clk, rst, enable, output logic [2:0] dither);
always_ff @(posedge clk or posedge rst) begin
  if (rst) dither <= 3'b000;
  else begin
    case(dither)
      3'b000: dither <= enable ? 3'b001 : 3'b000;
      3'b001: dither <= 3'b010;
      3'b010: dither <= 3'b100;
      3'b011: dither <= 3'b101;
      3'b100: dither <= 3'b110;
      3'b101: dither <= 3'b111;
      3'b110: dither <= 3'b011;
      3'b111: dither <= 3'b000;
    endcase
  end
end
endmodule

module case_gear_shift(input logic clk, rst, up, down, output logic [2:0] gear);
always_ff @(posedge clk or posedge rst) begin
  if (rst) gear <= 3'b001;
  else begin
    case(gear)
      3'b001: gear <= up ? 3'b010 : (down ? 3'b001 : 3'b001);
      3'b010: gear <= up ? 3'b011 : (down ? 3'b001 : 3'b010);
      3'b011: gear <= up ? 3'b100 : (down ? 3'b010 : 3'b011);
      3'b100: gear <= up ? 3'b101 : (down ? 3'b011 : 3'b100);
      3'b101: gear <= up ? 3'b101 : (down ? 3'b100 : 3'b101);
      default: gear <= 3'b001;
    endcase
  end
end
endmodule

module case_adc_range(input logic clk, rst, ovf, unf, output logic [1:0] range);
always_ff @(posedge clk or posedge rst) begin
  if (rst) range <= 2'b01;
  else begin
    case(range)
      2'b00: range <= ovf ? 2'b01 : 2'b00;
      2'b01: begin
        if (ovf) range <= 2'b10;
        if (unf) range <= 2'b00;
      end
      2'b10: begin
        if (ovf) range <= 2'b11;
        if (unf) range <= 2'b01;
      end
      2'b11: range <= unf ? 2'b10 : 2'b11;
    endcase
  end
end
endmodule

module case_pipe_stage(input logic clk, rst, valid, output logic [3:0] pipeline);
always_ff @(posedge clk or posedge rst) begin
  if (rst) pipeline <= 4'b0001;
  else begin
    case(pipeline)
      4'b0000: pipeline <= 4'b0001;
      4'b0001: pipeline <= valid ? 4'b0010 : 4'b0001;
      4'b0010: pipeline <= 4'b0100;
      4'b0100: pipeline <= 4'b1000;
      4'b1000: pipeline <= 4'b0001;
      default: pipeline <= 4'b0001;
    endcase
  end
end
endmodule

module case_mux_sel(input logic clk, rst, next, output logic [2:0] mux_select);
always_ff @(posedge clk or posedge rst) begin
  if (rst) mux_select <= 3'b000;
  else begin
    case(mux_select)
      3'b000: mux_select <= next ? 3'b001 : 3'b000;
      3'b001: mux_select <= 3'b010;
      3'b010: mux_select <= 3'b011;
      3'b011: mux_select <= 3'b100;
      3'b100: mux_select <= 3'b101;
      3'b101: mux_select <= 3'b110;
      3'b110: mux_select <= 3'b111;
      3'b111: mux_select <= 3'b000;
    endcase
  end
end
endmodule

module case_fade_rate(input logic clk, rst, fast, slow, output logic [3:0] rate);
always_ff @(posedge clk or posedge rst) begin
  if (rst) rate <= 4'b0100;
  else begin
    case(rate)
      4'b0000: rate <= fast ? 4'b0001 : 4'b0000;
      4'b0001: rate <= fast ? 4'b0010 : (slow ? 4'b0000 : 4'b0001);
      4'b0010: rate <= fast ? 4'b0011 : (slow ? 4'b0001 : 4'b0010);
      4'b0011: rate <= fast ? 4'b0100 : (slow ? 4'b0010 : 4'b0011);
      4'b0100: rate <= fast ? 4'b0101 : (slow ? 4'b0011 : 4'b0100);
      4'b0101: rate <= fast ? 4'b0110 : (slow ? 4'b0100 : 4'b0101);
      4'b0110: rate <= fast ? 4'b0111 : (slow ? 4'b0101 : 4'b0110);
      4'b0111: rate <= fast ? 4'b1000 : (slow ? 4'b0110 : 4'b0111);
      4'b1000: rate <= slow ? 4'b0111 : 4'b1000;
      default: rate <= 4'b0100;
    endcase
  end
end
endmodule

module case_sensor_cal(input logic clk, rst, cal_step, output logic [2:0] cal_state);
always_ff @(posedge clk or posedge rst) begin
  if (rst) cal_state <= 3'b000;
  else begin
    case(cal_state)
      3'b000: cal_state <= cal_step ? 3'b001 : 3'b000;
      3'b001: cal_state <= cal_step ? 3'b010 : 3'b001;
      3'b010: cal_state <= 3'b011;
      3'b011: cal_state <= 3'b100;
      3'b100: cal_state <= cal_step ? 3'b101 : 3'b100;
      3'b101: cal_state <= 3'b110;
      3'b110: cal_state <= 3'b111;
      3'b111: cal_state <= 3'b000;
    endcase
  end
end
endmodule

module case_burst_len(input logic clk, rst, inc, dec, output logic [3:0] burst);
always_ff @(posedge clk or posedge rst) begin
  if (rst) burst <= 4'b0010;
  else begin
    case(burst) inside
      [1:2]: burst <= inc ? burst + 1 : burst;
      [3:6]: begin
        if (inc && burst < 4'd8) burst <= burst + 1;
        if (dec && burst > 4'd1) burst <= burst - 1;
      end
      [7:8]: burst <= dec ? burst - 1 : burst;
      [9:15]: burst <= 4'b0010;
      0: burst <= 4'b0010;
    endcase
  end
end
endmodule

module case_trim_val(input logic clk, rst, trim_up, trim_dn, output logic [3:0] trim);
always_ff @(posedge clk or posedge rst) begin
  if (rst) trim <= 4'b1000;
  else begin
    case(trim)
      4'b0000: trim <= trim_up ? 4'b0001 : 4'b0000;
      4'b0001: trim <= trim_up ? 4'b0010 : (trim_dn ? 4'b0000 : 4'b0001);
      4'b0010: trim <= trim_up ? 4'b0011 : (trim_dn ? 4'b0001 : 4'b0010);
      4'b0011: trim <= trim_up ? 4'b0100 : (trim_dn ? 4'b0010 : 4'b0011);
      4'b0100: trim <= trim_up ? 4'b0101 : (trim_dn ? 4'b0011 : 4'b0100);
      4'b0101: trim <= trim_up ? 4'b0110 : (trim_dn ? 4'b0100 : 4'b0101);
      4'b0110: trim <= trim_up ? 4'b0111 : (trim_dn ? 4'b0101 : 4'b0110);
      4'b0111: trim <= trim_up ? 4'b1000 : (trim_dn ? 4'b0110 : 4'b0111);
      4'b1000: trim <= trim_up ? 4'b1001 : (trim_dn ? 4'b0111 : 4'b1000);
      4'b1001: trim <= trim_up ? 4'b1010 : (trim_dn ? 4'b1000 : 4'b1001);
      4'b1010: trim <= trim_up ? 4'b1011 : (trim_dn ? 4'b1001 : 4'b1010);
      4'b1011: trim <= trim_up ? 4'b1100 : (trim_dn ? 4'b1010 : 4'b1011);
      4'b1100: trim <= trim_up ? 4'b1101 : (trim_dn ? 4'b1011 : 4'b1100);
      4'b1101: trim <= trim_up ? 4'b1110 : (trim_dn ? 4'b1100 : 4'b1101);
      4'b1110: trim <= trim_up ? 4'b1111 : (trim_dn ? 4'b1101 : 4'b1110);
      4'b1111: trim <= trim_dn ? 4'b1110 : 4'b1111;
    endcase
  end
end
endmodule

module case_pattern_seq(input logic clk, rst, advance, output logic [3:0] pattern);
always_ff @(posedge clk or posedge rst) begin
  if (rst) pattern <= 4'b0000;
  else begin
    case(pattern)
      4'b0000: pattern <= advance ? 4'b0001 : 4'b0000;
      4'b0001: pattern <= 4'b0011;
      4'b0010: pattern <= 4'b0110;
      4'b0011: pattern <= 4'b0111;
      4'b0100: pattern <= 4'b1100;
      4'b0101: pattern <= 4'b1101;
      4'b0110: pattern <= 4'b1110;
      4'b0111: pattern <= 4'b1111;
      4'b1000: pattern <= 4'b1001;
      4'b1001: pattern <= 4'b1011;
      4'b1010: pattern <= 4'b1011;
      4'b1011: pattern <= 4'b1111;
      4'b1100: pattern <= 4'b1101;
      4'b1101: pattern <= 4'b1111;
      4'b1110: pattern <= 4'b1111;
      4'b1111: pattern <= advance ? 4'b0000 : 4'b1111;
    endcase
  end
end
endmodule

module case_filter_mode(input logic clk, rst, mode_sel, output logic [1:0] filter_mode);
always_ff @(posedge clk or posedge rst) begin
  if (rst) filter_mode <= 2'b00;
  else begin
    case(filter_mode)
      2'b00: filter_mode <= mode_sel ? 2'b01 : 2'b11;
      2'b01: filter_mode <= 2'b10;
      2'b10: filter_mode <= mode_sel ? 2'b11 : 2'b00;
      2'b11: filter_mode <= 2'b00;
    endcase
  end
end
endmodule

module case_power_state(input logic clk, rst, wake, sleep, output logic [2:0] pwr_state);
always_ff @(posedge clk or posedge rst) begin
  if (rst) pwr_state <= 3'b001;
  else begin
    case(pwr_state)
      3'b000: pwr_state <= wake ? 3'b001 : 3'b000;
      3'b001: pwr_state <= sleep ? 3'b010 : (wake ? 3'b011 : 3'b001);
      3'b010: pwr_state <= wake ? 3'b001 : 3'b010;
      3'b011: pwr_state <= 3'b100;
      3'b100: pwr_state <= sleep ? 3'b010 : 3'b100;
      3'b101: pwr_state <= 3'b001;
      3'b110: pwr_state <= 3'b001;
      3'b111: pwr_state <= 3'b001;
    endcase
  end
end
endmodule

module traffic_light_mealy (
    input logic clk,
    input logic rst_n,
    input logic pedestrian_req,
    output logic [1:0] lights,  // 00: Green, 01: Yellow, 10: Red
    output logic walk_signal
);

typedef enum logic [1:0] {GREEN, YELLOW, RED} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= GREEN;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    lights = {2{1'b0}};
    walk_signal = 1'b0;

    case (state)
        GREEN: begin
            lights = 2'b00;  // Green
            if (pedestrian_req) begin
                next_state = YELLOW;
                walk_signal = 1'b1;  // Walk signal triggered immediately
            end
        end

        YELLOW: begin
            lights = 2'b01;  // Yellow
            // Count 3 cycles then change to red
            // (simplified - normally would have counter)
            next_state = RED;
        end

        RED: begin
            lights = 2'b10;  // Red
            // After pedestrian crossing time
            next_state = GREEN;
        end
    endcase
end

endmodule

module serial_adder_mealy (
    input logic clk,
    input logic rst_n,
    input logic a_bit,
    input logic b_bit,
    input logic valid,
    output logic sum_bit,
    output logic carry_out
);

typedef enum logic {C0, C1} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= C0;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    sum_bit = 1'b0;
    carry_out = 1'b0;

    if (valid) begin
        case (state)
            C0: begin  // Carry = 0
                case ({a_bit, b_bit})
                    2'b00: begin
                        sum_bit = 1'b0;
                        next_state = C0;
                    end
                    2'b01, 2'b10: begin
                        sum_bit = 1'b1;
                        next_state = C0;
                    end
                    2'b11: begin
                        sum_bit = 1'b0;
                        next_state = C1;
                    end
                endcase
            end

            C1: begin  // Carry = 1
                case ({a_bit, b_bit})
                    2'b00: begin
                        sum_bit = 1'b1;
                        next_state = C0;
                    end
                    2'b01, 2'b10: begin
                        sum_bit = 1'b0;
                        next_state = C1;
                    end
                    2'b11: begin
                        sum_bit = 1'b1;
                        next_state = C1;
                    end
                endcase
            end
        endcase

        // Final carry out
        if (state == C1 && {a_bit, b_bit} != 2'b00)
            carry_out = 1'b1;
    end
end

endmodule

module mealy_pulse_generator (
    input  logic clk,
    input  logic rst_n,
    input  logic button,
    output logic pulse
);

    // State encoding - only 2 states needed
    typedef enum logic {
        IDLE,   // Waiting for button press
        PRESS   // Button is currently pressed
    } state_t;

    state_t current_state, next_state;

    // Sequential block: state update
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // Combinational block: next state and output logic
    always_comb begin
        next_state = current_state;  // Default to stay in current state
        pulse = 1'b0;                // Default output

        case (current_state)
            IDLE: begin
                if (button == 1'b1) begin
                    next_state = PRESS;
                    pulse = 1'b1;    // Mealy output: pulse immediately on press
                end
            end

            PRESS: begin
                if (button == 1'b0) begin
                    next_state = IDLE;  // Wait for button release
                end
                // No pulse while in PRESS state
            end
        endcase
    end

endmodule

module mealy_vending_machine (
    input  logic clk,
    input  logic rst_n,
    input  logic nickel,      // 5 cents
    input  logic dime,        // 10 cents
    input  logic quarter,     // 25 cents
    input  logic dispense_btn,
    output logic product_out,
    output logic [1:0] change  // 00: no change, 01: nickel, 10: dime
);

    // State encoding - represents accumulated value
    typedef enum logic [2:0] {
        S0,    // $0.00
        S5,    // $0.05
        S10,   // $0.10
        S15,   // $0.15
        S20,   // $0.20
        S25,   // $0.25
        S30,   // $0.30
        S35    // $0.35
    } state_t;

    state_t current_state, next_state;

    // Product price is $0.25
    localparam PRICE = 3'b100; // 25 cents in binary

    // Sequential block: state update
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    // Combinational block: next state logic using case
    always_comb begin
        next_state = current_state;

        case (current_state)
            S0: begin
                case (1'b1)
                    nickel:  next_state = S5;
                    dime:    next_state = S10;
                    quarter: next_state = S25;
                endcase
            end

            S5: begin
                case (1'b1)
                    nickel:  next_state = S10;
                    dime:    next_state = S15;
                    quarter: next_state = S30;
                endcase
            end

            S10: begin
                case (1'b1)
                    nickel:  next_state = S15;
                    dime:    next_state = S20;
                    quarter: next_state = S35;
                endcase
            end

            S15: begin
                case (1'b1)
                    nickel:  next_state = S20;
                    dime:    next_state = S25;
                    quarter: next_state = S35;
                endcase
            end

            S20: begin
                case (1'b1)
                    nickel:  next_state = S25;
                    dime:    next_state = S30;
                    quarter: next_state = S35;
                endcase
            end

            S25: begin
                case (1'b1)
                    nickel:  next_state = S30;
                    dime:    next_state = S35;
                    quarter: next_state = S35;
                endcase
            end

            S30: begin
                case (1'b1)
                    nickel:  next_state = S35;
                    dime:    next_state = S35;
                    quarter: next_state = S35;
                endcase
            end

            S35: begin
                // Max value, ignore additional coins
                next_state = S35;
            end
        endcase
    end

    // Combinational block: Mealy outputs
    always_comb begin
        product_out = 1'b0;
        change = 2'b00;

        case (current_state)
            S25: begin
                if (dispense_btn) begin
                    product_out = 1'b1;  // Exact change, no refund
                end
            end

            S30: begin
                if (dispense_btn) begin
                    product_out = 1'b1;
                    change = 2'b01;      // Return nickel ($0.05)
                end
            end

            S35: begin
                if (dispense_btn) begin
                    product_out = 1'b1;
                    change = 2'b10;      // Return dime ($0.10)
                end
            end

            default: begin
                product_out = 1'b0;
                change = 2'b00;
            end
        endcase
    end

endmodule

module counter_2bit_mealy (
    input logic clk,
    input logic rst_n,
    input logic enable,
    output logic [1:0] count,
    output logic overflow
);

typedef enum logic [1:0] {C0, C1, C2, C3} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= C0;
    else
        state <= next_state;
end

// Output logic for current count
assign count = state;

// Next state and overflow detection
always_comb begin
    next_state = state;
    overflow = 1'b0;

    if (enable) begin
        case (state)
            C0: next_state = C1;
            C1: next_state = C2;
            C2: next_state = C3;
            C3: begin
                next_state = C0;
                overflow = 1'b1;  // Overflow on transition
            end
        endcase
    end
end

endmodule

module parity_checker_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    input logic valid,
    output logic error
);

typedef enum logic {EVEN, ODD} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= EVEN;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    error = 1'b0;

    if (valid) begin
        case (state)
            EVEN: begin
                if (din) begin
                    next_state = ODD;
                end
                // Error detection on final valid
                error = 1'b0;  // Even parity with even bits is OK
            end

            ODD: begin
                if (!din) begin
                    next_state = EVEN;
                end
                // Error detection on final valid
                error = 1'b1;  // Odd parity with odd bits is error
            end
        endcase
    end
end

endmodule

module binary_to_bcd_mealy (
    input logic clk,
    input logic rst_n,
    input logic [7:0] binary_in,
    input logic convert,
    output logic [3:0] bcd_out,
    output logic bcd_valid
);

typedef enum logic [2:0] {IDLE, SHIFT, ADD3, DONE} state_t;
state_t state, next_state;
logic [7:0] binary_reg;
logic [11:0] bcd_reg;
logic [2:0] bit_count;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        binary_reg <= 8'b0;
        bcd_reg <= 12'b0;
        bit_count <= 3'b0;
    end else begin
        state <= next_state;
        if (state == SHIFT) begin
            binary_reg <= {binary_reg[6:0], 1'b0};
            bcd_reg <= {bcd_reg[10:0], binary_reg[7]};
            bit_count <= bit_count + 1;
        end
        if (state == ADD3)
            // Add 3 to each BCD digit > 4
            bcd_reg <= bcd_reg;
    end
end

always_comb begin
    next_state = state;
    bcd_out = 4'b0;
    bcd_valid = 1'b0;

    case (state)
        IDLE: begin
            if (convert) begin
                next_state = SHIFT;
                binary_reg = binary_in;
                bcd_reg = 12'b0;
                bit_count = 3'b0;
            end
        end

        SHIFT: begin
            if (bit_count == 3'b111) begin
                next_state = DONE;
                // Output on last shift
                bcd_out = bcd_reg[11:8];  // MSB digit
                bcd_valid = 1'b1;
            end else begin
                // Check if any BCD digit > 4
                if (bcd_reg[11:8] > 4 || bcd_reg[7:4] > 4 || bcd_reg[3:0] > 4)
                    next_state = ADD3;
            end
        end

        ADD3: begin
            // Immediate addition of 3 to digits > 4
            next_state = SHIFT;
        end

        DONE: begin
            bcd_out = bcd_reg[11:8];
            bcd_valid = 1'b1;
            next_state = IDLE;
        end
    endcase
end

endmodule

module mealy_elevator_controller (
    input  logic clk,
    input  logic rst_n,
    input  logic req_floor1,
    input  logic req_floor2,
    input  logic req_floor3,
    input  logic floor_sensor1,
    input  logic floor_sensor2,
    input  logic floor_sensor3,
    output logic motor_up,
    output logic motor_down,
    output logic door_open
);

    // State encoding - current floor position
    typedef enum logic [1:0] {
        FLOOR1,   // Elevator at floor 1
        FLOOR2,   // Elevator at floor 2
        FLOOR3    // Elevator at floor 3
    } state_t;

    state_t current_state, next_state;

    // Sequential block: state update
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            current_state <= FLOOR1;
        else
            current_state <= next_state;
    end

    // Combinational block: next state logic
    always_comb begin
        next_state = current_state;

        case (current_state)
            FLOOR1: begin
                case (1'b1)
                    req_floor2: next_state = FLOOR2;
                    req_floor3: next_state = FLOOR3;
                endcase
            end

            FLOOR2: begin
                case (1'b1)
                    req_floor1: next_state = FLOOR1;
                    req_floor3: next_state = FLOOR3;
                endcase
            end

            FLOOR3: begin
                case (1'b1)
                    req_floor1: next_state = FLOOR1;
                    req_floor2: next_state = FLOOR2;
                endcase
            end
        endcase
    end

    // Combinational block: Mealy outputs
    always_comb begin
        motor_up = 1'b0;
        motor_down = 1'b0;
        door_open = 1'b0;

        case (current_state)
            FLOOR1: begin
                case (1'b1)
                    req_floor2: begin
                        motor_up = 1'b1;           // Mealy: immediate response
                        door_open = floor_sensor1;  // Open if already at floor
                    end
                    req_floor3: begin
                        motor_up = 1'b1;
                        door_open = floor_sensor1;
                    end
                    default: begin
                        door_open = floor_sensor1;   // Open doors if at floor
                    end
                endcase
            end

            FLOOR2: begin
                case (1'b1)
                    req_floor1: begin
                        motor_down = 1'b1;
                        door_open = floor_sensor2;
                    end
                    req_floor3: begin
                        motor_up = 1'b1;
                        door_open = floor_sensor2;
                    end
                    default: begin
                        door_open = floor_sensor2;
                    end
                endcase
            end

            FLOOR3: begin
                case (1'b1)
                    req_floor1: begin
                        motor_down = 1'b1;
                        door_open = floor_sensor3;
                    end
                    req_floor2: begin
                        motor_down = 1'b1;
                        door_open = floor_sensor3;
                    end
                    default: begin
                        door_open = floor_sensor3;
                    end
                endcase
            end
        endcase
    end

endmodule

module runt_pulse_detector (
    input logic clk,
    input logic rst_n,
    input logic signal_in,
    input logic [3:0] min_width,
    output logic runt_detected
);

typedef enum logic [2:0] {IDLE, PULSE_LOW, PULSE_HIGH, CHECK} state_t;
state_t state, next_state;
logic [3:0] pulse_width;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        pulse_width <= 4'b0;
    end else begin
        state <= next_state;
        if (state == PULSE_LOW || state == PULSE_HIGH)
            pulse_width <= pulse_width + 1;
        else
            pulse_width <= 4'b0;
    end
end

always_comb begin
    next_state = state;
    runt_detected = 1'b0;

    case (state)
        IDLE: begin
            if (signal_in)
                next_state = PULSE_HIGH;
            else
                next_state = PULSE_LOW;
        end

        PULSE_HIGH: begin
            if (!signal_in) begin
                next_state = CHECK;
                // Check if pulse was too short
                if (pulse_width < min_width)
                    runt_detected = 1'b1;  // Immediate detection
            end
        end

        PULSE_LOW: begin
            if (signal_in) begin
                next_state = CHECK;
                // Check if pulse was too short
                if (pulse_width < min_width)
                    runt_detected = 1'b1;  // Immediate detection
            end
        end

        CHECK: begin
            // Return to IDLE after one cycle
            next_state = IDLE;
        end
    endcase
end

endmodule

module tcp_congestion_control (
    input logic clk,
    input logic rst_n,
    input logic ack_received,
    input logic timeout_event,
    input logic [15:0] rtt_measurement,
    input logic [2:0] duplicate_acks,
    output logic [15:0] congestion_window,
    output logic [15:0] slow_start_threshold,
    output logic [1:0] phase  // 00: SLOW_START, 01: CONG_AVOID, 10: FAST_RECOVERY
);

typedef enum logic [2:0] {
    SLOW_START,
    CONGESTION_AVOIDANCE,
    FAST_RECOVERY,
    FAST_RETRANSMIT,
    TIMEOUT_WAIT,
    PROBE
} state_t;

state_t state, next_state;
logic [15:0] cwnd;  // Congestion window
logic [15:0] ssthresh;  // Slow start threshold
logic [15:0] flight_size;
logic [3:0] ack_counter;
logic [31:0] rto_counter;
logic [15:0] min_rtt;
logic [15:0] avg_rtt;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= SLOW_START;
        cwnd <= 16'd1;
        ssthresh <= 16'd65535;
        ack_counter <= 4'b0;
        min_rtt <= 16'hFFFF;
        avg_rtt <= 16'd100;
    end else begin
        state <= next_state;

        // Update RTT measurements
        if (rtt_measurement < min_rtt)
            min_rtt <= rtt_measurement;

        avg_rtt <= (avg_rtt * 7 + rtt_measurement) >> 3;

        // Update window based on state
        unique case (state)
            SLOW_START: begin
                if (ack_received) begin
                    cwnd <= cwnd + 1;  // Exponential growth
                    ack_counter <= ack_counter + 1;

                    if (cwnd >= ssthresh)
                        next_state = CONGESTION_AVOIDANCE;
                end
            end

            CONGESTION_AVOIDANCE: begin
                if (ack_received) begin
                    ack_counter <= ack_counter + 1;
                    if (ack_counter == cwnd) begin
                        cwnd <= cwnd + 1;  // Linear growth
                        ack_counter <= 4'b0;
                    end
                end
            end

            FAST_RECOVERY: begin
                if (duplicate_acks == 3'd3) begin
                    next_state = FAST_RETRANSMIT;
                    ssthresh <= cwnd >> 1;
                    cwnd <= ssthresh + 3;
                end
            end
        endcase

        // Timeout handling
        if (timeout_event) begin
            ssthresh <= cwnd >> 1;
            cwnd <= 16'd1;
            next_state = TIMEOUT_WAIT;
            rto_counter <= 32'b0;
        end
    end
end

always_comb begin
    next_state = state;
    congestion_window = cwnd;
    slow_start_threshold = ssthresh;
    phase = 2'b00;

    // Flight size estimation
    flight_size = congestion_window >> 1;

    case (state)
        SLOW_START: begin
            phase = 2'b00;

            // Check for packet loss
            if (duplicate_acks >= 3'd3) begin
                next_state = FAST_RECOVERY;
                ssthresh = cwnd >> 1;
            end

            // RTT-based adaptation
            if (rtt_measurement > (avg_rtt + (avg_rtt >> 2))) begin
                // RTT increasing, prepare for congestion
                ssthresh = cwnd;
                next_state = CONGESTION_AVOIDANCE;
            end
        end

        CONGESTION_AVOIDANCE: begin
            phase = 2'b01;

            if (duplicate_acks == 3'd3) begin
                next_state = FAST_RETRANSMIT;
                ssthresh = cwnd >> 1;
                cwnd = ssthresh + 3;
            end

            // AIMD (Additive Increase Multiplicative Decrease)
            if (timeout_event) begin
                ssthresh = cwnd >> 1;
                cwnd = 16'd1;
                next_state = TIMEOUT_WAIT;
            end
        end

        FAST_RECOVERY: begin
            phase = 2'b10;

            if (ack_received) begin
                cwnd = ssthresh;
                next_state = CONGESTION_AVOIDANCE;
            end
        end

        FAST_RETRANSMIT: begin
            phase = 2'b10;

            // Retransmit lost packet
            if (ack_received) begin
                next_state = FAST_RECOVERY;
            end
        end

        TIMEOUT_WAIT: begin
            phase = 2'b00;

            rto_counter = rto_counter + 1;
            if (rto_counter > (min_rtt * 2)) begin
                if (ack_received)
                    next_state = SLOW_START;
                else
                    next_state = PROBE;
            end
        end

        PROBE: begin
            phase = 2'b00;

            // Send probe packets
            cwnd = 16'd1;
            if (ack_received)
                next_state = SLOW_START;
        end
    endcase
end

endmodule

module spi_master_mealy (
    input logic clk,
    input logic rst_n,
    input logic start,
    input logic [7:0] tx_data,
    output logic sclk,
    output logic mosi,
    input logic miso,
    output logic [7:0] rx_data,
    output logic busy,
    output logic done
);

typedef enum logic [2:0] {IDLE, ASSERT_CS, CLK_LOW, CLK_HIGH, DONE_ST} state_t;
state_t state, next_state;
logic [2:0] bit_count;
logic [7:0] shift_reg;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        bit_count <= 3'b0;
        shift_reg <= 8'b0;
    end else begin
        state <= next_state;
        if (state == CLK_LOW) begin
            shift_reg <= {shift_reg[6:0], miso};  // Sample on rising edge
            bit_count <= bit_count + 1;
        end
    end
end

always_comb begin
    next_state = state;
    sclk = 1'b0;
    mosi = 1'b0;
    busy = 1'b1;
    done = 1'b0;
    rx_data = shift_reg;

    case (state)
        IDLE: begin
            busy = 1'b0;
            if (start) begin
                next_state = ASSERT_CS;
                shift_reg = tx_data;
                bit_count = 3'b0;
            end
        end

        ASSERT_CS: begin
            next_state = CLK_LOW;  // Immediate transition
        end

        CLK_LOW: begin
            sclk = 1'b0;
            mosi = shift_reg[7];  // Output MSB first
            if (bit_count == 3'b111)  // Last bit
                next_state = DONE_ST;
            else
                next_state = CLK_HIGH;
        end

        CLK_HIGH: begin
            sclk = 1'b1;
            mosi = shift_reg[7];
            next_state = CLK_LOW;  // Immediate transition back
        end

        DONE_ST: begin
            done = 1'b1;  // Done signal
            next_state = IDLE;
        end
    endcase
end

endmodule

module fifo_monitor_mealy (
    input logic clk,
    input logic rst_n,
    input logic write_en,
    input logic read_en,
    input logic [3:0] fifo_depth,
    output logic almost_full,
    output logic almost_empty,
    output logic [3:0] fill_level
);

typedef enum logic [1:0] {NORMAL, WARN_FULL, WARN_EMPTY} state_t;
state_t state, next_state;
logic [3:0] count;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= NORMAL;
        count <= 4'b0;
    end else begin
        state <= next_state;
        // Update count
        case ({write_en, read_en})
            2'b10: if (count < fifo_depth) count <= count + 1;
            2'b01: if (count > 0) count <= count - 1;
            default: count <= count;
        endcase
    end
end

assign fill_level = count;

always_comb begin
    next_state = state;
    almost_full = 1'b0;
    almost_empty = 1'b0;

    case (state)
        NORMAL: begin
            if (count >= fifo_depth - 2 && write_en) begin
                next_state = WARN_FULL;
                almost_full = 1'b1;  // Immediate warning on write
            end
            else if (count <= 2 && read_en) begin
                next_state = WARN_EMPTY;
                almost_empty = 1'b1;  // Immediate warning on read
            end
        end

        WARN_FULL: begin
            almost_full = 1'b1;
            if (count <= fifo_depth - 4 || (read_en && !write_en))
                next_state = NORMAL;
            else if (write_en && count == fifo_depth)
                almost_full = 1'b1;  // Stay in warning
        end

        WARN_EMPTY: begin
            almost_empty = 1'b1;
            if (count >= 4 || (write_en && !read_en))
                next_state = NORMAL;
            else if (read_en && count == 0)
                almost_empty = 1'b1;  // Stay in warning
        end
    endcase
end

endmodule

module mealy_traffic_controller (
    input  logic clk,
    input  logic rst_n,
    input  logic timer_expired,
    input  logic pedestrian_req,
    output logic main_green,
    output logic main_yellow,
    output logic main_red,
    output logic walk,
    output logic dont_walk
);

    // State encoding
    typedef enum logic [1:0] {
        GREEN,      // Main road green
        YELLOW,     // Main road yellow
        RED,        // Main road red
        PED_WALK    // Pedestrian walking
    } state_t;

    state_t current_state, next_state;

    // Sequential block: state update
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            current_state <= GREEN;
        else
            current_state <= next_state;
    end

    // Combinational block: next state logic with timing conditions
    always_comb begin
        next_state = current_state;

        case (current_state)
            GREEN: begin
                // Go to yellow when timer expires OR pedestrian request
                if (timer_expired || pedestrian_req)
                    next_state = YELLOW;
            end

            YELLOW: begin
                // Always go to red after yellow timer expires
                if (timer_expired)
                    next_state = RED;
            end

            RED: begin
                // Go to pedestrian walk if request pending
                if (pedestrian_req)
                    next_state = PED_WALK;
                else if (timer_expired)
                    next_state = GREEN;
            end

            PED_WALK: begin
                // Return to green after walk timer expires
                if (timer_expired)
                    next_state = GREEN;
            end
        endcase
    end

    // Combinational block: Mealy outputs based on state and inputs
    always_comb begin
        // Default outputs (all inactive)
        {main_green, main_yellow, main_red} = 3'b000;
        {walk, dont_walk} = 2'b00;

        case (current_state)
            GREEN: begin
                main_green = 1'b1;
                dont_walk = 1'b1;  // Don't walk during main traffic
                // Mealy: Flash don't walk when pedestrian waiting
                if (pedestrian_req)
                    dont_walk = ~dont_walk;  // Flashing indication
            end

            YELLOW: begin
                main_yellow = 1'b1;
                dont_walk = 1'b1;
            end

            RED: begin
                main_red = 1'b1;
                // Mealy: Pre-walk indication when pedestrian waiting
                if (pedestrian_req)
                    dont_walk = ~dont_walk;  // Flashing before walk
                else
                    dont_walk = 1'b1;
            end

            PED_WALK: begin
                main_red = 1'b1;
                walk = 1'b1;        // Walk signal active
            end
        endcase
    end

endmodule

// AXI4-Lite Slave Interface - Register File Example
// Uses only case statements (no if/else)
// Demonstrates separate combinational and sequential logic blocks

module axi_lite_slave (
    // Clock and Reset
    input  logic        aclk,
    input  logic        aresetn,

    // AXI4-Lite Write Address Channel
    input  logic [31:0] s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    // AXI4-Lite Write Data Channel
    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    // AXI4-Lite Write Response Channel
    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    // AXI4-Lite Read Address Channel
    input  logic [31:0] s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    // AXI4-Lite Read Data Channel
    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready,

    // User interface to registers
    output logic [31:0] reg0,  // Read/Write register
    output logic [31:0] reg1,  // Read/Write register
    output logic [31:0] reg2,  // Read/Write register
    output logic [31:0] reg3,  // Read/Write register
    input  logic [31:0] reg4   // Read-only register
);

    //=========================================================
    // Internal State Definitions
    //=========================================================
    typedef enum logic [1:0] {
        IDLE,
        WRITE_RESP,
        READ_DATA
    } state_t;

    state_t write_state, read_state;
    state_t write_state_next, read_state_next;

    //=========================================================
    // Register Storage
    //=========================================================
    logic [31:0] reg0_q, reg1_q, reg2_q, reg3_q;
    logic [31:0] reg0_next, reg1_next, reg2_next, reg3_next;

    //=========================================================
    // AXI Interface Registers
    //=========================================================
    logic        awready_q, awready_next;
    logic        wready_q, wready_next;
    logic        bvalid_q, bvalid_next;
    logic [1:0]  bresp_q, bresp_next;

    logic        arready_q, arready_next;
    logic        rvalid_q, rvalid_next;
    logic [1:0]  rresp_q, rresp_next;
    logic [31:0] rdata_q, rdata_next;

    // Address and data storage for transactions
    logic [31:0] awaddr_q, awaddr_next;
    logic [31:0] wdata_q, wdata_next;
    logic [3:0]  wstrb_q, wstrb_next;
    logic [31:0] araddr_q, araddr_next;

    //=========================================================
    // Combinational Logic: Write Channel FSM
    //=========================================================
    always_comb begin
        // Default assignments
        write_state_next = write_state;
        awready_next = 1'b0;
        wready_next  = 1'b0;
        bvalid_next  = bvalid_q;
        bresp_next   = bresp_q;
        awaddr_next  = awaddr_q;
        wdata_next   = wdata_q;
        wstrb_next   = wstrb_q;
        reg0_next = reg0_q;
        reg1_next = reg1_q;
        reg2_next = reg2_q;
        reg3_next = reg3_q;

        case (write_state)
            IDLE: begin
                awready_next = 1'b1;
                wready_next  = 1'b1;

                // Capture address and data when valid
                case ({s_axi_awvalid, s_axi_wvalid})
                    2'b11: begin
                        awaddr_next = s_axi_awaddr;
                        wdata_next  = s_axi_wdata;
                        wstrb_next  = s_axi_wstrb;
                        write_state_next = WRITE_RESP;
                    end
                    default: begin
                        write_state_next = IDLE;
                    end
                endcase
            end

            WRITE_RESP: begin
                bvalid_next = 1'b1;
                bresp_next  = 2'b00;  // OKAY response

                // Perform register write based on address
                case (awaddr_q[7:2])  // 4-byte aligned addresses
                    6'b000000: begin  // Address 0x00
                        reg0_next = wdata_q;
                    end
                    6'b000001: begin  // Address 0x04
                        reg1_next = wdata_q;
                    end
                    6'b000010: begin  // Address 0x08
                        reg2_next = wdata_q;
                    end
                    6'b000011: begin  // Address 0x0C
                        reg3_next = wdata_q;
                    end
                    default: begin
                        // Invalid address - no write
                        bresp_next = 2'b11;  // SLVERR
                    end
                endcase

                case ({bvalid_q, s_axi_bready})
                    2'b11: begin
                        bvalid_next = 1'b0;
                        write_state_next = IDLE;
                    end
                    default: begin
                        write_state_next = WRITE_RESP;
                    end
                endcase
            end
        endcase
    end

    //=========================================================
    // Combinational Logic: Read Channel FSM
    //=========================================================
    always_comb begin
        // Default assignments
        read_state_next = read_state;
        arready_next = 1'b0;
        rvalid_next  = rvalid_q;
        rresp_next   = rresp_q;
        rdata_next   = rdata_q;
        araddr_next  = araddr_q;

        case (read_state)
            IDLE: begin
                arready_next = 1'b1;

                case (s_axi_arvalid)
                    1'b1: begin
                        araddr_next = s_axi_araddr;
                        read_state_next = READ_DATA;
                    end
                    default: begin
                        read_state_next = IDLE;
                    end
                endcase
            end

            READ_DATA: begin
                rvalid_next = 1'b1;
                rresp_next  = 2'b00;  // OKAY response

                // Read data based on address
                case (araddr_q[7:2])  // 4-byte aligned addresses
                    6'b000000: begin  // Address 0x00
                        rdata_next = reg0_q;
                    end
                    6'b000001: begin  // Address 0x04
                        rdata_next = reg1_q;
                    end
                    6'b000010: begin  // Address 0x08
                        rdata_next = reg2_q;
                    end
                    6'b000011: begin  // Address 0x0C
                        rdata_next = reg3_q;
                    end
                    6'b000100: begin  // Address 0x10
                        rdata_next = reg4;  // Read-only register
                    end
                    default: begin
                        rdata_next = 32'hDEADBEEF;
                        rresp_next = 2'b11;  // SLVERR
                    end
                endcase

                case ({rvalid_q, s_axi_rready})
                    2'b11: begin
                        rvalid_next = 1'b0;
                        read_state_next = IDLE;
                    end
                    default: begin
                        read_state_next = READ_DATA;
                    end
                endcase
            end
        endcase
    end

    //=========================================================
    // Output Assignments
    //=========================================================
    assign s_axi_awready = awready_q;
    assign s_axi_wready  = wready_q;
    assign s_axi_bvalid  = bvalid_q;
    assign s_axi_bresp   = bresp_q;

    assign s_axi_arready = arready_q;
    assign s_axi_rvalid  = rvalid_q;
    assign s_axi_rresp   = rresp_q;
    assign s_axi_rdata   = rdata_q;

    assign reg0 = reg0_q;
    assign reg1 = reg1_q;
    assign reg2 = reg2_q;
    assign reg3 = reg3_q;

endmodule

module baud_rate_gen_mealy (
    input logic clk,
    input logic rst_n,
    input logic [7:0] divisor,
    input logic [3:0] fraction,
    output logic baud_tick
);

typedef enum logic [1:0] {IDLE, COUNT, ADJUST} state_t;
state_t state, next_state;
logic [7:0] counter;
logic [3:0] frac_acc;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        counter <= 8'b0;
        frac_acc <= 4'b0;
    end else begin
        state <= next_state;
        if (state == COUNT) begin
            counter <= counter + 1;
            if (counter == divisor - 1)
                counter <= 8'b0;
        end
        if (state == ADJUST)
            frac_acc <= frac_acc + fraction;
    end
end

always_comb begin
    next_state = state;
    baud_tick = 1'b0;

    case (state)
        IDLE: if (divisor != 0)
            next_state = COUNT;

        COUNT: begin
            if (counter == divisor - 1) begin
                if (frac_acc + fraction >= 16) begin
                    next_state = ADJUST;
                    baud_tick = 1'b1;  // Generate tick with fraction adjust
                end else begin
                    next_state = IDLE;
                    baud_tick = 1'b1;
                end
            end
        end

        ADJUST: begin
            next_state = IDLE;
            baud_tick = 1'b1;  // Extra tick for fractional adjustment
        end
    endcase
end

endmodule

module seq_detector_101_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic detected
);

typedef enum logic [1:0] {S0, S1, S2} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S0;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    detected = 1'b0;

    case (state)
        S0: if (din) begin
            next_state = S1;
        end else begin
            next_state = S0;
        end

        S1: if (din) begin
            next_state = S1;
        end else begin
            next_state = S2;
        end

        S2: if (din) begin
            next_state = S1;
            detected = 1'b1;  // Sequence "101" detected
        end else begin
            next_state = S0;
        end
    endcase
end

endmodule

module pattern_detector_1101 (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic match
);

typedef enum logic [2:0] {S0, S1, S11, S110} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S0;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    match = 1'b0;

    case (state)
        S0: next_state = din ? S1 : S0;

        S1: begin
            if (din) next_state = S11;
            else next_state = S0;
        end

        S11: begin
            if (din) next_state = S11;  // Overlap case
            else next_state = S110;
        end

        S110: begin
            if (din) begin
                next_state = S1;  // Last '1' can start new sequence
                match = 1'b1;     // Pattern "1101" detected
            end
            else next_state = S0;
        end
    endcase
end

endmodule

// OBI Protocol Controller - Case-Statements-Only Implementation
// Implements a simplified OBI master interface with request/response handling
// No if/else statements, no loops - only case statements and combinational/sequential blocks

module obi_protocol_controller (
    // Clock and reset
    input  logic clk,
    input  logic rst_n,

    // OBI Master Interface (to interconnect)
    output logic        obi_cmd_valid,
    input  logic        obi_cmd_ready,
    output logic [31:0] obi_cmd_addr,
    output logic [2:0]  obi_cmd_opc,    // 000: read, 001: write, 010: atomic
    output logic [31:0] obi_cmd_wdata,
    output logic [3:0]  obi_cmd_be,

    input  logic        obi_rsp_valid,
    output logic        obi_rsp_ready,
    input  logic [31:0] obi_rsp_rdata,
    input  logic [2:0]  obi_rsp_err,    // 000: ok, 001: decode error, 010: slave error

    // Local control interface
    input  logic        req_valid,
    output logic        req_ready,
    input  logic [31:0] req_addr,
    input  logic [2:0]  req_opc,
    input  logic [31:0] req_wdata,
    input  logic [3:0]  req_be,

    output logic        rsp_valid,
    input  logic        rsp_ready,
    output logic [31:0] rsp_rdata,
    output logic [2:0]  rsp_err,

    // Status outputs
    output logic [2:0]  state_out,
    output logic        pending_transaction
);

    // State encoding
    typedef enum logic [2:0] {
        IDLE         = 3'b000,
        WAIT_CMD_ACK = 3'b001,
        WAIT_RSP     = 3'b010,
        WAIT_RSP_ACK = 3'b011,
        ERROR_RECOV  = 3'b100
    } state_t;

    state_t current_state, next_state;

    // Transaction storage registers
    logic [31:0] stored_addr;
    logic [2:0]  stored_opc;
    logic [31:0] stored_wdata;
    logic [3:0]  stored_be;

    // Response storage
    logic [31:0] stored_rdata;
    logic [2:0]  stored_err;

    // Counter for error recovery (3-cycle timeout)
    logic [1:0] error_counter;

    // -----------------------------------------------------------------
    // BLOCK 1: Sequential State Register (Clock/Reset)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                current_state <= IDLE;
                error_counter <= 2'b00;
            end
            1'b1: begin
                current_state <= next_state;
                case (current_state)
                    ERROR_RECOV: begin
                        // Increment counter during error recovery
                        case (error_counter)
                            2'b11: error_counter <= 2'b11;
                            default: error_counter <= error_counter + 2'b01;
                        endcase
                    end
                    default: begin
                        error_counter <= 2'b00;
                    end
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 2: Next State Logic (Combinational)
    // -----------------------------------------------------------------
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case (req_valid)
                    1'b1: next_state = WAIT_CMD_ACK;
                    1'b0: next_state = IDLE;
                endcase
            end

            WAIT_CMD_ACK: begin
                case (obi_cmd_ready)
                    1'b1: begin
                        case (obi_cmd_opc)
                            3'b010: begin  // Atomic operation requires response
                                next_state = WAIT_RSP;
                            end
                            default: begin  // Read/Write operations
                                case (obi_cmd_opc)
                                    3'b000: next_state = WAIT_RSP;  // Read needs response
                                    3'b001: next_state = WAIT_RSP_ACK; // Write needs response
                                    default: next_state = WAIT_RSP;
                                endcase
                            end
                        endcase
                    end
                    1'b0: next_state = WAIT_CMD_ACK;
                endcase
            end

            WAIT_RSP: begin
                case (obi_rsp_valid)
                    1'b1: begin
                        case (rsp_ready)
                            1'b1: next_state = IDLE;
                            1'b0: next_state = WAIT_RSP_ACK;
                        endcase
                    end
                    1'b0: next_state = WAIT_RSP;
                endcase
            end

            WAIT_RSP_ACK: begin
                case (rsp_ready)
                    1'b1: begin
                        case (obi_rsp_err)
                            3'b000: next_state = IDLE;
                            default: next_state = ERROR_RECOV;
                        endcase
                    end
                    1'b0: next_state = WAIT_RSP_ACK;
                endcase
            end

            ERROR_RECOV: begin
                case (error_counter)
                    2'b11: next_state = IDLE;
                    default: next_state = ERROR_RECOV;
                endcase
            end

            default: next_state = IDLE;
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 3: Transaction Capture & OBI Command Generation (Combinational)
    // -----------------------------------------------------------------
    always_comb begin
        // Default assignments
        obi_cmd_valid = 1'b0;
        obi_cmd_addr = 32'b0;
        obi_cmd_opc = 3'b000;
        obi_cmd_wdata = 32'b0;
        obi_cmd_be = 4'b0000;
        req_ready = 1'b0;

        case (current_state)
            IDLE: begin
                case (req_valid)
                    1'b1: begin
                        req_ready = 1'b1;
                        obi_cmd_valid = 1'b1;
                        obi_cmd_addr = req_addr;
                        obi_cmd_opc = req_opc;
                        obi_cmd_wdata = req_wdata;
                        obi_cmd_be = req_be;
                    end
                    default: begin
                        req_ready = 1'b0;
                    end
                endcase
            end

            WAIT_CMD_ACK: begin
                // Keep driving same command until accepted
                obi_cmd_valid = 1'b1;
                obi_cmd_addr = stored_addr;
                obi_cmd_opc = stored_opc;
                obi_cmd_wdata = stored_wdata;
                obi_cmd_be = stored_be;
                req_ready = 1'b0;
            end

            default: begin
                obi_cmd_valid = 1'b0;
                req_ready = 1'b0;
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 4: Transaction Storage Registers (Sequential)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                stored_addr <= 32'b0;
                stored_opc <= 3'b000;
                stored_wdata <= 32'b0;
                stored_be <= 4'b0000;
            end
            1'b1: begin
                case (current_state)
                    IDLE: begin
                        case (req_valid & req_ready)
                            1'b1: begin
                                stored_addr <= req_addr;
                                stored_opc <= req_opc;
                                stored_wdata <= req_wdata;
                                stored_be <= req_be;
                            end
                            default: begin
                                stored_addr <= stored_addr;
                                stored_opc <= stored_opc;
                                stored_wdata <= stored_wdata;
                                stored_be <= stored_be;
                            end
                        endcase
                    end
                    default: begin
                        stored_addr <= stored_addr;
                        stored_opc <= stored_opc;
                        stored_wdata <= stored_wdata;
                        stored_be <= stored_be;
                    end
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 5: Response Capture & OBI Response Handshake (Combinational)
    // -----------------------------------------------------------------
    always_comb begin
        // Default assignments
        obi_rsp_ready = 1'b0;
        rsp_valid = 1'b0;
        rsp_rdata = 32'b0;
        rsp_err = 3'b000;

        case (current_state)
            WAIT_RSP: begin
                case (obi_rsp_valid)
                    1'b1: begin
                        obi_rsp_ready = 1'b1;
                        rsp_valid = 1'b1;
                        rsp_rdata = obi_rsp_rdata;
                        rsp_err = obi_rsp_err;
                    end
                    default: begin
                        obi_rsp_ready = 1'b0;
                        rsp_valid = 1'b0;
                    end
                endcase
            end

            WAIT_RSP_ACK: begin
                // Keep response valid until consumed
                obi_rsp_ready = 1'b0;
                rsp_valid = 1'b1;
                rsp_rdata = stored_rdata;
                rsp_err = stored_err;
            end

            default: begin
                obi_rsp_ready = 1'b0;
                rsp_valid = 1'b0;
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 6: Response Storage Registers (Sequential)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                stored_rdata <= 32'b0;
                stored_err <= 3'b000;
            end
            1'b1: begin
                case (current_state)
                    WAIT_RSP: begin
                        case (obi_rsp_valid)
                            1'b1: begin
                                stored_rdata <= obi_rsp_rdata;
                                stored_err <= obi_rsp_err;
                            end
                            default: begin
                                stored_rdata <= stored_rdata;
                                stored_err <= stored_err;
                            end
                        endcase
                    end
                    default: begin
                        stored_rdata <= stored_rdata;
                        stored_err <= stored_err;
                    end
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 7: Status Outputs (Combinational)
    // -----------------------------------------------------------------
    always_comb begin
        state_out = current_state;

        case (current_state)
            IDLE: begin
                pending_transaction = 1'b0;
            end
            default: begin
                pending_transaction = 1'b1;
            end
        endcase
    end

endmodule

module pwm_generator_mealy (
    input logic clk,
    input logic rst_n,
    input logic [7:0] period,
    input logic [7:0] duty_cycle,
    input logic update_duty,
    output logic pwm_out
);

typedef enum logic [1:0] {HIGH, LOW, UPDATE} state_t;
state_t state, next_state;
logic [7:0] counter;
logic [7:0] current_duty;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= LOW;
        counter <= 8'b0;
        current_duty <= 8'b0;
    end else begin
        state <= next_state;
        counter <= counter + 1;
        if (update_duty)
            current_duty <= duty_cycle;
    end
end

always_comb begin
    next_state = state;
    pwm_out = 1'b0;

    case (state)
        HIGH: begin
            pwm_out = 1'b1;
            if (counter == current_duty - 1) begin
                next_state = LOW;
                pwm_out = 1'b0;  // Immediate transition
            end
            if (update_duty && counter < duty_cycle)
                pwm_out = 1'b1;  // Immediate duty cycle update
        end

        LOW: begin
            pwm_out = 1'b0;
            if (counter == period - 1) begin
                next_state = HIGH;
                counter = 8'b0;
                pwm_out = 1'b1;  // Immediate transition
            end
            if (update_duty && duty_cycle > 0)
                next_state = UPDATE;  // Special update state
        end

        UPDATE: begin
            pwm_out = 1'b1;  // Immediate response to new duty cycle
            next_state = HIGH;
            counter = 8'b0;
        end
    endcase
end

endmodule

// Mealy FSM: Weapons System Controller
// Tracks: Safe Mode -> Armed -> Fire
// Outputs depend on both state and input (Mealy)
// All conditional logic implemented with case statements only
module weapons_system (
    input  logic clk,
    input  logic rst_n,
    input  logic arm_switch,    // 1: arm command
    input  logic trigger,       // 1: fire command
    input  logic safety_bypass, // 1: override safety
    output logic fire_enable,   // 1: weapon can fire
    output logic armed_led,     // 1: armed indicator
    output logic fault          // 1: illegal condition
);

    // State encoding
    typedef enum logic [1:0] {
        SAFE   = 2'b00,
        ARMED  = 2'b01,
        FAULT  = 2'b10
    } state_t;

    state_t curr_state, next_state;

    // --------------------------------------------------
    // Sequential block: State register (synchronous)
    // --------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            curr_state <= SAFE;
        else
            curr_state <= next_state;
    end

    // --------------------------------------------------
    // Combinational block 1: Next state logic
    // All conditional logic via case statements
    // --------------------------------------------------
    always_comb begin
        next_state = curr_state;  // default: stay

        case (curr_state)
            SAFE: begin
                case ({arm_switch, safety_bypass})
                    2'b10: next_state = ARMED;   // arm without bypass
                    2'b11: next_state = FAULT;   // arm with bypass = unsafe
                    default: next_state = SAFE;
                endcase
            end
            ARMED: begin
                case ({trigger, arm_switch})
                    2'b10: next_state = SAFE;    // trigger fired
                    2'b00: next_state = SAFE;    // arm_switch turned off
                    default: next_state = ARMED;
                endcase
            end
            FAULT: begin
                next_state = FAULT;   // latch fault until reset
            end
        endcase
    end

    // --------------------------------------------------
    // Combinational block 2: Mealy + Moore outputs
    // All conditional logic via case statements
    // --------------------------------------------------
    always_comb begin
        // Defaults
        fire_enable = 1'b0;
        armed_led   = 1'b0;
        fault       = 1'b0;

        case (curr_state)
            SAFE: begin
                armed_led = 1'b0;
                // Mealy: trigger with safety_bypass causes fault
                case ({trigger, safety_bypass})
                    2'b11: fault = 1'b1;
                    default: fault = 1'b0;
                endcase
                // No fire in SAFE state
                fire_enable = 1'b0;
            end

            ARMED: begin
                armed_led = 1'b1;
                // Mealy: fire_enable active when trigger pressed
                case (trigger)
                    1'b1: fire_enable = 1'b1;
                    default: fire_enable = 1'b0;
                endcase
                // Armed LED turns off if arm_switch deasserted
                case (arm_switch)
                    1'b0: armed_led = 1'b0;
                    default: armed_led = 1'b1;
                endcase
            end

            FAULT: begin
                fault = 1'b1;
                armed_led = 1'b0;
                fire_enable = 1'b0;
            end
        endcase
    end

endmodule

module seq_detector_1001_nonoverlap (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic detected
);

typedef enum logic [2:0] {S0, S1, S10, S100} state_t;
state_t state, next_state;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S0;
    else
        state <= next_state;
end

always_comb begin
    next_state = state;
    detected = 1'b0;

    case (state)
        S0: next_state = din ? S1 : S0;

        S1: next_state = din ? S1 : S10;

        S10: next_state = din ? S1 : S100;

        S100: begin
            if (din) begin
                next_state = S1;  // Start new sequence from last '1'
                detected = 1'b1;  // Pattern "1001" detected
            end else begin
                next_state = S0;   // Reset if next bit is 0
            end
        end
    endcase
end

endmodule

module uart_sampler_mealy (
    input logic clk,
    input logic rst_n,
    input logic rx_line,
    input logic sample_enable,
    output logic bit_value,
    output logic bit_ready
);

typedef enum logic [2:0] {IDLE, START, MIDDLE, SAMPLE} state_t;
state_t state, next_state;
logic [2:0] oversample_count;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        oversample_count <= 3'b0;
    end else begin
        state <= next_state;
        if (sample_enable)
            oversample_count <= oversample_count + 1;
    end
end

always_comb begin
    next_state = state;
    bit_value = 1'b0;
    bit_ready = 1'b0;

    case (state)
        IDLE: begin
            if (!rx_line && sample_enable)  // Start bit detected
                next_state = START;
        end

        START: begin
            if (sample_enable) begin
                if (oversample_count == 3'b100) begin  // Middle of start bit
                    next_state = MIDDLE;
                end
            end
        end

        MIDDLE: begin
            if (sample_enable) begin
                if (oversample_count == 3'b111) begin  // Sample point
                    next_state = SAMPLE;
                    bit_value = rx_line;  // Sample the bit
                    bit_ready = 1'b1;     // Bit ready immediately
                end
            end
        end

        SAMPLE: begin
            if (sample_enable) begin
                if (oversample_count == 3'b111)
                    next_state = IDLE;
                else
                    next_state = MIDDLE;
            end
        end
    endcase
end

endmodule

//=============================================================================
// Defense Protocol Stream Cipher Core
// - Uses ONLY case statements (no if/else, no loops)
// - 4 procedural blocks: 2 combinational, 2 sequential
// - Implements a key stream generator with mode control and integrity check
//=============================================================================

module stream_cipher_core (
    input  logic        clk,
    input  logic        rst_n,

    // Control interface
    input  logic [1:0]  mode,          // 00: IDLE, 01: INIT, 10: ENCRYPT, 11: AUTH
    input  logic        start,

    // Data interface
    input  logic [7:0]  key_in,        // Key byte input
    input  logic [7:0]  data_in,       // Plaintext/Ciphertext byte
    output logic [7:0]  data_out,      // Ciphertext/Plaintext byte
    output logic [15:0] auth_tag,      // Authentication tag output
    output logic        ready,
    output logic        valid
);

    //-------------------------------------------------------------------------
    // Internal state variables
    //-------------------------------------------------------------------------
    logic [1:0]  state, next_state;
    logic [7:0]  lfsr [0:3];          // 4-byte LFSR array (32-bit Galois LFSR)
    logic [7:0]  sbox [0:255];        // S-Box for substitution layer
    logic [15:0] accum;               // Authentication accumulator
    logic [3:0]  byte_cnt;            // Byte counter for key setup
    logic [7:0]  key_stream;

    //-------------------------------------------------------------------------
    // Block 1: Combinational - Next state logic (pure case)
    //-------------------------------------------------------------------------
    always_comb begin
        next_state = state;
        case (state)
            2'b00: begin  // IDLE
                case (start)
                    1'b1: next_state = mode;  // Jump directly to requested mode
                    default: next_state = 2'b00;
                endcase
            end

            2'b01: begin  // INIT (key setup)
                case (byte_cnt)
                    4'b1111: next_state = 2'b00;  // 16 bytes loaded, return to IDLE
                    default:  next_state = 2'b01;
                endcase
            end

            2'b10: begin  // ENCRYPT mode
                case (start)
                    1'b0: next_state = 2'b00;     // Operation complete
                    default: next_state = 2'b10;
                endcase
            end

            2'b11: begin  // AUTH mode (authentication only)
                case (start)
                    1'b0: next_state = 2'b00;
                    default: next_state = 2'b11;
                endcase
            end

            default: next_state = 2'b00;
        endcase
    end

    //-------------------------------------------------------------------------
    // Block 2: Sequential - State and counter update (if/else removed)
    //-------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                state    <= 2'b00;
                byte_cnt <= 4'b0000;
            end
            1'b1: begin
                state <= next_state;
                case (state)
                    2'b01: begin  // During INIT, increment counter
                        byte_cnt <= byte_cnt + 1'b1;
                    end
                    2'b10, 2'b11: begin
                        // Reset counter when starting encryption/authentication
                        case (start)
                            1'b1: byte_cnt <= 4'b0000;
                            default: byte_cnt <= byte_cnt + 1'b1;
                        endcase
                    end
                    default: begin
                        case (state)
                            2'b00: byte_cnt <= 4'b0000;
                            default: byte_cnt <= byte_cnt;
                        endcase
                    end
                endcase
            end
        endcase
    end

    //-------------------------------------------------------------------------
    // Block 3: Sequential - LFSR array, S-Box, and accumulator (if/else removed)
    //-------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                lfsr[0] <= 8'h00;
                lfsr[1] <= 8'h00;
                lfsr[2] <= 8'h00;
                lfsr[3] <= 8'h00;
                accum   <= 16'h0000;
                sbox[0] <= 8'h00;
            end
            1'b1: begin
                case (state)
                    2'b01: begin  // INIT: load key into LFSR and generate S-Box
                        case (byte_cnt)
                            4'b0000: lfsr[0] <= key_in;
                            4'b0001: lfsr[1] <= key_in;
                            4'b0010: lfsr[2] <= key_in;
                            4'b0011: lfsr[3] <= key_in;
                            4'b0100: sbox[0]  <= key_in ^ 8'hA5;
                            4'b0101: sbox[1]  <= key_in ^ 8'h5A;
                            4'b0110: sbox[2]  <= key_in ^ 8'hFF;
                            4'b0111: sbox[3]  <= key_in ^ 8'h00;
                            default: begin
                                // Simple S-Box initialization for remaining entries
                                case (byte_cnt[3:2])
                                    2'b10: sbox[{byte_cnt[3:0]}] <= key_in ^ {byte_cnt[3:0], 4'h0};
                                    2'b11: sbox[{byte_cnt[3:0]}] <= key_in ^ {4'h0, byte_cnt[3:0]};
                                    default: sbox[{byte_cnt[3:0]}] <= key_in ^ byte_cnt[3:0];
                                endcase
                            end
                        endcase
                    end

                    2'b10, 2'b11: begin  // ENCRYPT or AUTH: update LFSR and accumulator
                        // Galois LFSR update: polynomial x^32 + x^22 + x^2 + x + 1
                        // Shift and feedback using byte-wise operations
                        case (byte_cnt[1:0])  // Rotate through bytes each clock
                            2'b00: begin
                                lfsr[0] <= lfsr[1];
                                lfsr[1] <= lfsr[2];
                                lfsr[2] <= lfsr[3];
                                lfsr[3] <= sbox[lfsr[0] ^ {lfsr[3][6:0], lfsr[3][7]}];
                            end
                            2'b01: begin
                                lfsr[0] <= lfsr[1];
                                lfsr[1] <= lfsr[2];
                                lfsr[2] <= lfsr[3];
                                lfsr[3] <= sbox[lfsr[0] ^ (lfsr[3] << 1)];
                            end
                            2'b10: begin
                                lfsr[0] <= lfsr[1];
                                lfsr[1] <= lfsr[2];
                                lfsr[2] <= lfsr[3];
                                lfsr[3] <= sbox[lfsr[0] ^ (lfsr[3] >> 1)];
                            end
                            2'b11: begin
                                lfsr[0] <= lfsr[1];
                                lfsr[1] <= lfsr[2];
                                lfsr[2] <= lfsr[3];
                                lfsr[3] <= sbox[lfsr[0] ^ ~lfsr[3]];
                            end
                        endcase

                        // Authentication accumulator update
                        case (state)
                            2'b11: begin  // AUTH mode: accumulate key stream XOR data
                                accum <= accum + {key_stream ^ data_in, 8'h00};
                            end
                            2'b10: begin  // ENCRYPT mode: accumulate plaintext
                                accum <= accum + {data_in, 8'h00};
                            end
                            default: accum <= accum;
                        endcase
                    end

                    default: begin
                        // Reset accumulator when idle
                        case (mode)
                            2'b00: accum <= 16'h0000;
                            default: accum <= accum;
                        endcase
                    end
                endcase
            end
        endcase
    end


    //-------------------------------------------------------------------------
    // Block 4: Combinational - Output logic and key stream generation (pure case)
    //-------------------------------------------------------------------------
    always_comb begin
        // Default assignments
        key_stream = 8'h00;
        data_out   = 8'h00;
        ready      = 1'b0;
        valid      = 1'b0;
        auth_tag   = 16'h0000;

        case (state)
            2'b00: begin  // IDLE state
                ready = 1'b1;
                case (mode)
                    2'b01: valid = 1'b1;  // Ready for key loading
                    default: valid = 1'b0;
                endcase
            end

            2'b01: begin  // INIT state: key loading
                ready = 1'b0;
                case (byte_cnt)
                    4'b1111: begin
                        valid = 1'b1;
                        ready = 1'b1;  // Key setup complete
                    end
                    default: valid = 1'b0;
                endcase
            end

            2'b10: begin  // ENCRYPT mode
                ready = 1'b0;
                // Generate key stream from LFSR and S-Box
                case (byte_cnt[1:0])
                    2'b00: key_stream = sbox[lfsr[0] ^ lfsr[1]];
                    2'b01: key_stream = sbox[lfsr[1] ^ lfsr[2]];
                    2'b10: key_stream = sbox[lfsr[2] ^ lfsr[3]];
                    2'b11: key_stream = sbox[lfsr[3] ^ lfsr[0]];
                endcase

                // Encrypt/decrypt data
                data_out = data_in ^ key_stream;

                case (start)
                    1'b0: begin  // Operation complete
                        valid = 1'b1;
                        ready = 1'b1;
                        auth_tag = accum;  // Output auth tag at end
                    end
                    default: valid = 1'b1;
                endcase
            end

            2'b11: begin  // AUTH mode (generate authentication tag only)
                ready = 1'b0;
                // Generate key stream for authentication
                case (byte_cnt[1:0])
                    2'b00: key_stream = sbox[lfsr[0] ^ ~lfsr[3]];
                    2'b01: key_stream = sbox[lfsr[1] ^ {lfsr[0][3:0], lfsr[0][7:4]}];
                    2'b10: key_stream = sbox[lfsr[2] ^ lfsr[1]];
                    2'b11: key_stream = sbox[lfsr[3] ^ lfsr[2]];
                endcase

                data_out = data_in;  // Passthrough for auth mode

                case (start)
                    1'b0: begin
                        valid = 1'b1;
                        ready = 1'b1;
                        auth_tag = accum;  // Final authentication tag
                    end
                    default: valid = 1'b1;
                endcase
            end

            default: begin
                ready = 1'b0;
                valid = 1'b0;
            end
        endcase
    end

endmodule

// Satellite Telemetry Command Decoder
// Uses only case statements - no if/else, no loops
// Handles command parsing, error detection, execution, and telemetry formatting

module satellite_cmd_decoder (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [7:0]  rx_data,        // Received data byte
    input  logic        rx_valid,       // Valid data strobe
    output logic [15:0] tm_data,        // Telemetry data output
    output logic        tm_valid,       // Telemetry valid strobe
    output logic        cmd_error,      // Command error flag
    output logic        busy            // Decoder busy flag
);

    //-----------------------------------------------------------------
    // State encoding for sequential blocks
    //-----------------------------------------------------------------
    typedef enum logic [2:0] {
        IDLE,
        CMD_BYTE,
        ARG_HIGH,
        ARG_LOW,
        EXECUTE,
        TM_RESPONSE
    } state_t;

    state_t current_state, next_state;

    //-----------------------------------------------------------------
    // Command opcodes (8-bit)
    //-----------------------------------------------------------------
    typedef enum logic [7:0] {
        CMD_NOP          = 8'h00,
        CMD_GET_STATUS   = 8'h01,
        CMD_SET_MODE     = 8'h02,
        CMD_GET_TEMP     = 8'h03,
        CMD_SET_POWER    = 8'h04,
        CMD_GET_VOLTAGE  = 8'h05,
        CMD_SET_BEACON   = 8'h06,
        CMD_GET_ORBIT    = 8'h07,
        CMD_RESET        = 8'hFF
    } cmd_opcode_t;

    //-----------------------------------------------------------------
    // Satellite operational modes
    //-----------------------------------------------------------------
    typedef enum logic [1:0] {
        MODE_SAFE    = 2'b00,
        MODE_NORMAL  = 2'b01,
        MODE_PAYLOAD = 2'b10,
        MODE_EMERG   = 2'b11
    } satellite_mode_t;

    //-----------------------------------------------------------------
    // Internal registers
    //-----------------------------------------------------------------
    logic [7:0]  cmd_register;          // Stores command byte
    logic [7:0]  arg_high_register;     // High byte of argument
    logic [7:0]  arg_low_register;      // Low byte of argument
    logic [15:0] telemetry_register;    // Telemetry data to output
    logic [15:0] status_word;           // Satellite status word

    satellite_mode_t current_mode;
    logic [7:0]    temperature;
    logic [11:0]   bus_voltage;
    logic [7:0]    beacon_rate;
    logic [31:0]   orbit_counter;

    //-----------------------------------------------------------------
    // Block 1: Sequential state machine - State update (case only)
    //-----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case ({rst_n, 1'b1})  // Using concatenation to create case expression
            2'b00: begin  // rst_n is 0 (active low reset)
                current_state <= IDLE;
            end
            2'b01: begin  // rst_n is 1 (normal operation)
                current_state <= next_state;
            end
            default: begin
                current_state <= IDLE;
            end
        endcase
    end

    //-----------------------------------------------------------------
    // Block 2: Combinational next state logic (case only)
    //-----------------------------------------------------------------
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case (rx_valid)
                    1'b1: next_state = CMD_BYTE;
                    default: next_state = IDLE;
                endcase
            end

            CMD_BYTE: begin
                case (cmd_register)
                    CMD_NOP, CMD_RESET: next_state = EXECUTE;
                    CMD_GET_STATUS, CMD_GET_TEMP,
                    CMD_GET_VOLTAGE, CMD_GET_ORBIT: next_state = EXECUTE;
                    CMD_SET_MODE, CMD_SET_POWER, CMD_SET_BEACON: next_state = ARG_HIGH;
                    default: next_state = IDLE;
                endcase
            end

            ARG_HIGH: next_state = ARG_LOW;
            ARG_LOW:  next_state = EXECUTE;
            EXECUTE:  next_state = TM_RESPONSE;
            TM_RESPONSE: begin
                case (tm_valid)
                    1'b1: next_state = IDLE;
                    default: next_state = TM_RESPONSE;
                endcase
            end
            default: next_state = IDLE;
        endcase
    end

    //-----------------------------------------------------------------
    // Block 3: Sequential register updates (case only - no if/else)
    //-----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        // Reset handling using case statement
        case ({rst_n, 1'b1})
            2'b00: begin  // Reset condition
                cmd_register     <= 8'h00;
                arg_high_register <= 8'h00;
                arg_low_register  <= 8'h00;
                status_word      <= 16'h0001;
                current_mode     <= MODE_SAFE;
                temperature      <= 8'h20;
                bus_voltage      <= 12'h500;
                beacon_rate      <= 8'h0A;
                orbit_counter    <= 32'h00000000;
            end

            2'b01: begin  // Normal operation (rst_n = 1)
                case (current_state)
                    IDLE: begin
                        case (rx_valid)
                            1'b1: cmd_register <= rx_data;
                            1'b0: cmd_register <= cmd_register;
                            default: cmd_register <= cmd_register;
                        endcase

                        // Other registers hold their values
                        arg_high_register <= arg_high_register;
                        arg_low_register  <= arg_low_register;
                        status_word       <= status_word;
                        current_mode      <= current_mode;
                        temperature       <= temperature;
                        bus_voltage       <= bus_voltage;
                        beacon_rate       <= beacon_rate;
                        orbit_counter     <= orbit_counter;
                    end

                    CMD_BYTE: begin
                        // Hold all registers
                        cmd_register     <= cmd_register;
                        arg_high_register <= arg_high_register;
                        arg_low_register  <= arg_low_register;
                        status_word       <= status_word;
                        current_mode      <= current_mode;
                        temperature       <= temperature;
                        bus_voltage       <= bus_voltage;
                        beacon_rate       <= beacon_rate;
                        orbit_counter     <= orbit_counter;
                    end

                    ARG_HIGH: begin
                        arg_high_register <= rx_data;
                        // Hold other registers
                        cmd_register     <= cmd_register;
                        arg_low_register  <= arg_low_register;
                        status_word       <= status_word;
                        current_mode      <= current_mode;
                        temperature       <= temperature;
                        bus_voltage       <= bus_voltage;
                        beacon_rate       <= beacon_rate;
                        orbit_counter     <= orbit_counter;
                    end

                    ARG_LOW: begin
                        arg_low_register <= rx_data;
                        // Hold other registers
                        cmd_register     <= cmd_register;
                        arg_high_register <= arg_high_register;
                        status_word       <= status_word;
                        current_mode      <= current_mode;
                        temperature       <= temperature;
                        bus_voltage       <= bus_voltage;
                        beacon_rate       <= beacon_rate;
                        orbit_counter     <= orbit_counter;
                    end

                    EXECUTE: begin
                        case (cmd_register)
                            CMD_NOP: begin
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_GET_STATUS: begin
                                status_word[15:8] <= {2'b00, current_mode, 4'b0000};
                                status_word[7:0]  <= 8'hA5;
                                // Hold other registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_SET_MODE: begin
                                case (arg_high_register[1:0])
                                    2'b00: current_mode <= MODE_SAFE;
                                    2'b01: current_mode <= MODE_NORMAL;
                                    2'b10: current_mode <= MODE_PAYLOAD;
                                    2'b11: current_mode <= MODE_EMERG;
                                    default: current_mode <= MODE_SAFE;
                                endcase
                                // Hold other registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_GET_TEMP: begin
                                temperature <= temperature + 8'h01;
                                // Hold other registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_SET_POWER: begin
                                case (arg_high_register[0])
                                    1'b0: bus_voltage <= 12'h000;
                                    1'b1: bus_voltage <= 12'h500;
                                    default: bus_voltage <= bus_voltage;
                                endcase
                                // Hold other registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_GET_VOLTAGE: begin
                                // Voltage reading is already in bus_voltage
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_SET_BEACON: begin
                                beacon_rate <= arg_high_register;
                                // Hold other registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                orbit_counter     <= orbit_counter;
                            end

                            CMD_GET_ORBIT: begin
                                orbit_counter <= orbit_counter + 32'h00000001;
                                // Hold other registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                            end

                            CMD_RESET: begin
                                status_word   <= 16'h0001;
                                current_mode  <= MODE_SAFE;
                                temperature   <= 8'h20;
                                bus_voltage   <= 12'h500;
                                beacon_rate   <= 8'h0A;
                                orbit_counter <= 32'h00000000;
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                            end

                            default: begin
                                // Invalid command - hold all registers
                                cmd_register     <= cmd_register;
                                arg_high_register <= arg_high_register;
                                arg_low_register  <= arg_low_register;
                                status_word       <= status_word;
                                current_mode      <= current_mode;
                                temperature       <= temperature;
                                bus_voltage       <= bus_voltage;
                                beacon_rate       <= beacon_rate;
                                orbit_counter     <= orbit_counter;
                            end
                        endcase
                    end

                    TM_RESPONSE: begin
                        // Hold all registers during TM response
                        cmd_register     <= cmd_register;
                        arg_high_register <= arg_high_register;
                        arg_low_register  <= arg_low_register;
                        status_word       <= status_word;
                        current_mode      <= current_mode;
                        temperature       <= temperature;
                        bus_voltage       <= bus_voltage;
                        beacon_rate       <= beacon_rate;
                        orbit_counter     <= orbit_counter;
                    end

                    default: begin
                        // Default hold for all registers
                        cmd_register     <= cmd_register;
                        arg_high_register <= arg_high_register;
                        arg_low_register  <= arg_low_register;
                        status_word       <= status_word;
                        current_mode      <= current_mode;
                        temperature       <= temperature;
                        bus_voltage       <= bus_voltage;
                        beacon_rate       <= beacon_rate;
                        orbit_counter     <= orbit_counter;
                    end
                endcase
            end

            default: begin
                // Default reset condition
                cmd_register     <= 8'h00;
                arg_high_register <= 8'h00;
                arg_low_register  <= 8'h00;
                status_word      <= 16'h0001;
                current_mode     <= MODE_SAFE;
                temperature      <= 8'h20;
                bus_voltage      <= 12'h500;
                beacon_rate      <= 8'h0A;
                orbit_counter    <= 32'h00000000;
            end
        endcase
    end

    //-----------------------------------------------------------------
    // Block 4: Combinational output and telemetry formatting (case only)
    //-----------------------------------------------------------------
    always_comb begin
        // Default assignments
        telemetry_register = 16'h0000;
        tm_valid = 1'b0;
        cmd_error = 1'b0;
        busy = (current_state != IDLE);

        case (current_state)
            IDLE: begin
                cmd_error = 1'b0;
            end

            CMD_BYTE: begin
                case (cmd_register)
                    CMD_NOP, CMD_GET_STATUS, CMD_GET_TEMP,
                    CMD_GET_VOLTAGE, CMD_GET_ORBIT, CMD_RESET: begin
                        cmd_error = 1'b0;
                    end
                    CMD_SET_MODE, CMD_SET_POWER, CMD_SET_BEACON: begin
                        cmd_error = 1'b0;
                    end
                    default: begin
                        cmd_error = 1'b1;  // Unknown command
                    end
                endcase
            end

            ARG_HIGH, ARG_LOW: begin
                // Argument reception in progress
            end

            EXECUTE: begin
                case (cmd_register)
                    CMD_GET_STATUS: begin
                        telemetry_register = status_word;
                    end

                    CMD_GET_TEMP: begin
                        telemetry_register = {8'h00, temperature};
                    end

                    CMD_GET_VOLTAGE: begin
                        telemetry_register = {4'h0, bus_voltage};
                    end

                    CMD_GET_ORBIT: begin
                        telemetry_register = orbit_counter[15:0];
                    end

                    CMD_SET_MODE, CMD_SET_POWER, CMD_SET_BEACON: begin
                        telemetry_register = 16'hACCE;  // Command accepted
                    end

                    CMD_NOP: begin
                        telemetry_register = 16'hDEAD;
                    end

                    CMD_RESET: begin
                        telemetry_register = 16'hBEEF;  // Reset acknowledged
                    end

                    default: begin
                        telemetry_register = 16'hFFFF;  // Error response
                    end
                endcase
            end

            TM_RESPONSE: begin
                tm_valid = 1'b1;
                telemetry_register = telemetry_register;  // Hold value
            end

            default: begin
                telemetry_register = 16'h0000;
            end
        endcase
    end

    //-----------------------------------------------------------------
    // Block 5: Output assignment (combinational)
    //-----------------------------------------------------------------
    assign tm_data = telemetry_register;

endmodule

// Power Management Controller (PMC)
// Implements: State machine, Clock gating, Voltage scaling, Interrupt handling
// Protocol: Simple power management with sleep, deep-sleep, active, and performance modes
// Constraints: No if/else, no loops, only case statements

module pmc (
    input  logic        clk,           // System clock
    input  logic        rst_n,         // Active-low asynchronous reset
    input  logic        wake_req,      // Wake request from peripheral
    input  logic [1:0]  perf_req,      // Performance level request: 0=low, 1=medium, 2=high, 3=ultra
    input  logic [2:0]  sleep_timeout, // Timeout cycles for sleep entry
    input  logic [1:0]  ext_status,    // External power status (e.g., PMIC ready)

    output logic        clk_cpu_en,    // CPU clock enable
    output logic        clk_periph_en, // Peripheral clock enable
    output logic [1:0]  vdd_level,     // Voltage scaling: 0=0.8V, 1=1.0V, 2=1.2V, 3=1.35V
    output logic        sleep_ack,     // Acknowledge sleep entry
    output logic        wake_ack,      // Acknowledge wakeup
    output logic [1:0]  pmc_status,    // Status output: 0=active, 1=sleep, 2=deep-sleep, 3=performance
    output logic        power_good     // Indicates power rails stable
);

    // State encoding
    typedef enum logic [1:0] {
        ACTIVE      = 2'b00,
        SLEEP       = 2'b01,
        DEEP_SLEEP  = 2'b10,
        PERFORMANCE = 2'b11
    } state_t;

    state_t current_state, next_state;

    // Counters and registers
    logic [2:0]  sleep_cnt;       // Sleep entry counter
    logic [1:0]  vdd_req;         // Requested voltage level
    logic        wake_pending;     // Wake request pending
    logic        clk_switching;    // Clock switching in progress
    logic [1:0]  perf_level;       // Current performance level

    // -----------------------------------------------------------------
    // Block 1: Synchronous State Register (Sequential)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= ACTIVE;
            1'b1: current_state <= next_state;
            default: current_state <= ACTIVE;
        endcase
    end

    // -----------------------------------------------------------------
    // Block 2: Next State Logic (Combinational)
    // Uses nested case statements for state transitions
    // -----------------------------------------------------------------
    always_comb begin
        next_state = current_state;  // Default to stay in current state

        case (current_state)
            ACTIVE: begin
                case (wake_pending)
                    1'b0: begin
                        case (sleep_timeout)
                            3'b000: next_state = SLEEP;      // Timeout expired
                            default: next_state = ACTIVE;     // No timeout, stay active
                        endcase
                    end
                    1'b1: next_state = ACTIVE;  // Wake pending during active
                endcase

                // Performance mode request override
                case (perf_req)
                    2'b11: next_state = PERFORMANCE;
                    default: ;  // Keep previously computed state
                endcase
            end

            SLEEP: begin
                case ({wake_req, wake_pending})
                    2'b00: begin
                        case (sleep_timeout[2])  // Extended sleep check
                            1'b1: next_state = DEEP_SLEEP;
                            default: next_state = SLEEP;
                        endcase
                    end
                    default: next_state = ACTIVE;  // Wake requested
                endcase
            end

            DEEP_SLEEP: begin
                case (wake_req)
                    1'b1: next_state = ACTIVE;
                    default: next_state = DEEP_SLEEP;
                endcase
            end

            PERFORMANCE: begin
                case (perf_req)
                    2'b00: next_state = ACTIVE;
                    2'b01, 2'b10, 2'b11: next_state = PERFORMANCE;
                    default: next_state = ACTIVE;
                endcase
            end

            default: next_state = ACTIVE;
        endcase
    end

    // -----------------------------------------------------------------
    // Block 3: Output and Control Logic (Combinational)
    // Generates all output signals based on current state and inputs
    // -----------------------------------------------------------------
    always_comb begin
        // Default values to avoid latches
        clk_cpu_en     = 1'b0;
        clk_periph_en  = 1'b0;
        vdd_level      = 2'b00;
        sleep_ack      = 1'b0;
        wake_ack       = 1'b0;
        pmc_status     = 2'b00;
        power_good     = 1'b0;
        vdd_req        = 2'b00;

        case (current_state)
            ACTIVE: begin
                clk_cpu_en    = 1'b1;
                clk_periph_en = 1'b1;
                vdd_req       = 2'b01;  // 1.0V
                pmc_status    = 2'b00;
                sleep_ack     = 1'b0;
                wake_ack      = 1'b0;

                case (ext_status)
                    2'b11: power_good = 1'b1;  // External PMIC ready
                    default: power_good = 1'b0;
                endcase

                // Voltage adjustment based on performance request
                case (perf_req)
                    2'b11: vdd_req = 2'b11;  // 1.35V for ultra
                    2'b10: vdd_req = 2'b10;  // 1.2V for high
                    default: vdd_req = 2'b01; // 1.0V for normal
                endcase
            end

            SLEEP: begin
                clk_cpu_en    = 1'b0;
                clk_periph_en = 1'b1;   // Keep peripherals awake for wake detection
                vdd_req       = 2'b00;  // 0.8V
                pmc_status    = 2'b01;
                sleep_ack     = 1'b1;
                wake_ack      = 1'b0;

                case (ext_status[1])
                    1'b1: power_good = 1'b1;
                    default: power_good = 1'b0;
                endcase
            end

            DEEP_SLEEP: begin
                clk_cpu_en    = 1'b0;
                clk_periph_en = 1'b0;
                vdd_req       = 2'b00;  // 0.8V
                pmc_status    = 2'b10;
                sleep_ack     = 1'b1;
                wake_ack      = 1'b0;
                power_good    = 1'b1;   // Power maintained in deep sleep
            end

            PERFORMANCE: begin
                clk_cpu_en    = 1'b1;
                clk_periph_en = 1'b1;
                pmc_status    = 2'b11;
                sleep_ack     = 1'b0;
                wake_ack      = 1'b0;
                power_good    = 1'b1;

                case (perf_level)
                    2'b11: vdd_req = 2'b11;  // Ultra: 1.35V
                    2'b10: vdd_req = 2'b10;  // High: 1.2V
                    2'b01: vdd_req = 2'b01;  // Medium: 1.0V
                    default: vdd_req = 2'b00; // Low: 0.8V
                endcase
            end

            default: ;
        endcase

        // Final voltage assignment (simulate PMIC settling time)
        case (clk_switching)
            1'b1: vdd_level = vdd_req;  // Apply new voltage after switching
            default: vdd_level = 2'b00;
        endcase
    end

    // -----------------------------------------------------------------
    // Block 4: Auxiliary Sequential Logic (Wake/Performance Management)
    // Handles wake pending and performance level tracking
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        // Reset handling using case on rst_n
        case (rst_n)
            1'b0: begin
                wake_pending <= 1'b0;
                clk_switching <= 1'b0;
                perf_level <= 2'b00;
                sleep_cnt <= 3'b000;
            end
            1'b1: begin
                // Wake pending management
                case ({wake_req, wake_ack})
                    2'b10: wake_pending <= 1'b1;
                    2'b01: wake_pending <= 1'b0;
                    default: wake_pending <= wake_pending;
                endcase

                // Clock switching flag
                case (current_state)
                    ACTIVE: begin
                        case (perf_req)
                            2'b11: clk_switching <= 1'b1;
                            default: clk_switching <= 1'b0;
                        endcase
                    end
                    default: clk_switching <= 1'b0;
                endcase

                // Performance level tracking
                case (current_state)
                    PERFORMANCE: begin
                        case (perf_req)
                            2'b00: perf_level <= 2'b00;
                            2'b01: perf_level <= 2'b01;
                            2'b10: perf_level <= 2'b10;
                            2'b11: perf_level <= 2'b11;
                            default: perf_level <= perf_level;
                        endcase
                    end
                    default: perf_level <= 2'b00;
                endcase

                // Sleep counter (increment in sleep states)
                case (current_state)
                    SLEEP: begin
                        case (sleep_cnt)
                            3'b111: sleep_cnt <= 3'b111;
                            default: sleep_cnt <= sleep_cnt + 1'b1;
                        endcase
                    end
                    default: sleep_cnt <= 3'b000;
                endcase
            end
            default: begin
                wake_pending <= 1'b0;
                clk_switching <= 1'b0;
                perf_level <= 2'b00;
                sleep_cnt <= 3'b000;
            end
        endcase
    end

endmodule

module mealy_door_lock (
    input  logic clk,
    input  logic rst_n,
    input  logic [1:0] code_input,
    input  logic enter_btn,
    output logic unlock,
    output logic error
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE,       // Waiting for first digit
        DIGIT1,     // First digit entered
        DIGIT2      // Second digit entered
    } state_t;

    state_t current_state, next_state;

    // Sequential block: state update
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // Combinational block: next state logic
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                if (enter_btn)
                    next_state = DIGIT1;
            end

            DIGIT1: begin
                if (enter_btn)
                    next_state = DIGIT2;
            end

            DIGIT2: begin
                if (enter_btn)
                    next_state = IDLE;  // Reset after attempt
            end
        endcase
    end

    // Combinational block: Mealy outputs
    always_comb begin
        unlock = 1'b0;
        error = 1'b0;

        case (current_state)
            DIGIT2: begin
                if (enter_btn) begin
                    // Correct code is 2'b10 (binary 2)
                    if (code_input == 2'b10)
                        unlock = 1'b1;   // Mealy: unlock on correct code
                    else
                        error = 1'b1;    // Mealy: error on wrong code
                end
            end

            default: begin
                unlock = 1'b0;
                error = 1'b0;
            end
        endcase
    end

endmodule

module debouncer_mealy (
    input logic clk,
    input logic rst_n,
    input logic noisy_in,
    input logic [15:0] debounce_time,
    output logic debounced_out
);

typedef enum logic [1:0] {STABLE0, COUNT0, STABLE1, COUNT1} state_t;
state_t state, next_state;
logic [15:0] counter;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= STABLE0;
        counter <= 16'b0;
    end else begin
        state <= next_state;
        if (state == COUNT0 || state == COUNT1)
            counter <= counter + 1;
        else
            counter <= 16'b0;
    end
end

always_comb begin
    next_state = state;
    debounced_out = 1'b0;

    case (state)
        STABLE0: begin
            debounced_out = 1'b0;
            if (noisy_in)
                next_state = COUNT0;
        end

        COUNT0: begin
            debounced_out = 1'b0;
            if (!noisy_in)
                next_state = STABLE0;  // Glitch, go back
            else if (counter == debounce_time - 1) begin
                next_state = STABLE1;
                debounced_out = 1'b1;  // Output high immediately
            end
        end

        STABLE1: begin
            debounced_out = 1'b1;
            if (!noisy_in)
                next_state = COUNT1;
        end

        COUNT1: begin
            debounced_out = 1'b1;
            if (noisy_in)
                next_state = STABLE1;  // Glitch, go back
            else if (counter == debounce_time - 1) begin
                next_state = STABLE0;
                debounced_out = 1'b0;  // Output low immediately
            end
        end
    endcase
end

endmodule

// AHB-Lite Slave Controller with Burst Support
// Implements: IDLE, SETUP, ACCESS states with burst (SINGLE, INCR, WRAP4)
// No if/else statements - only case statements for all control and data paths
// Total lines: ~140

module ahb_slave_burst_ctrl (
    // Clock and Reset
    input  logic        HCLK,
    input  logic        HRESETn,

    // AHB-Lite Interface
    input  logic        HSEL,           // Slave select
    input  logic [31:0] HADDR,
    input  logic        HWRITE,
    input  logic [ 2:0] HSIZE,
    input  logic [ 2:0] HBURST,
    input  logic [ 1:0] HTRANS,
    input  logic [31:0] HWDATA,
    output logic [31:0] HRDATA,
    output logic        HREADY,         // Slave ready
    output logic [ 1:0] HRESP,          // Response (0=OKAY, 1=ERROR)

    // Internal memory interface (simulated RAM)
    input  logic [31:0] mem_read_data,
    output logic [31:0] mem_write_data,
    output logic [31:0] mem_address,
    output logic        mem_write_en,
    output logic        mem_read_en
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE    = 2'b00,
        SETUP   = 2'b01,
        ACCESS  = 2'b10
    } state_t;

    state_t current_state, next_state;

    // Burst control registers
    logic [31:0] base_addr;
    logic [31:0] current_addr;
    logic [ 2:0] burst_type;
    logic [ 2:0] burst_size;
    logic [ 1:0] burst_count;
    logic [ 1:0] burst_index;
    logic        burst_active;
    logic        last_beat;
    logic        write_pending;

    // Internal signals
    logic [31:0] next_addr_calc;
    logic        addr_align_error;
    logic        hready_next;
    logic [ 1:0] hresp_next;
    logic [31:0] mem_addr_next;
    logic        mem_we_next;
    logic        mem_re_next;
    logic [31:0] mem_wdata_next;

    // -----------------------------------------------------------------
    // Block 1: Sequential State Register (case-only)
    // -----------------------------------------------------------------
    always_ff @(posedge HCLK or negedge HRESETn) begin
        case (HRESETn)
            1'b0: current_state <= IDLE;
            default: current_state <= next_state;
        endcase
    end

    // -----------------------------------------------------------------
    // Block 2: Sequential Burst Control Registers (case-only)
    // -----------------------------------------------------------------
    always_ff @(posedge HCLK or negedge HRESETn) begin
        case (HRESETn)
            1'b0: begin
                base_addr     <= 32'd0;
                current_addr  <= 32'd0;
                burst_type    <= 3'd0;
                burst_size    <= 3'd0;
                burst_count   <= 2'd0;
                burst_index   <= 2'd0;
                burst_active  <= 1'b0;
                last_beat     <= 1'b0;
                write_pending <= 1'b0;
            end
            default: begin
                case (next_state)
                    IDLE: begin
                        case ({HSEL, HTRANS[1]})
                            2'b11: begin
                                base_addr    <= HADDR;
                                current_addr <= HADDR;
                                burst_type   <= HBURST;
                                burst_size   <= HSIZE;
                                burst_index  <= 2'd0;
                                write_pending <= HWRITE;

                                // Calculate burst active and count using nested case
                                case (HBURST)
                                    3'b000: begin
                                        burst_active <= 1'b0;
                                        burst_count <= 2'd0;
                                    end
                                    3'b001, 3'b010, 3'b011: begin
                                        burst_active <= 1'b1;
                                        // Calculate burst count for WRAP4 and INCR4
                                        case (HBURST)
                                            3'b010, 3'b001, 3'b011: burst_count <= 2'd3;
                                            default: burst_count <= 2'd0;
                                        endcase
                                    end
                                    default: begin
                                        burst_active <= 1'b0;
                                        burst_count <= 2'd0;
                                    end
                                endcase
                            end
                            default: begin
                                burst_active <= 1'b0;
                                write_pending <= 1'b0;
                                // Preserve other registers
                                base_addr    <= base_addr;
                                current_addr <= current_addr;
                                burst_type   <= burst_type;
                                burst_size   <= burst_size;
                                burst_count  <= burst_count;
                                burst_index  <= burst_index;
                                last_beat    <= last_beat;
                            end
                        endcase
                    end

                    SETUP: begin
                        case (HREADY)
                            1'b1: begin
                                current_addr <= next_addr_calc;
                                case (burst_active)
                                    1'b1: begin
                                        burst_index <= burst_index + 2'd1;
                                        case (burst_index == burst_count)
                                            1'b1: last_beat <= 1'b1;
                                            default: last_beat <= 1'b0;
                                        endcase
                                    end
                                    default: last_beat <= 1'b1;
                                endcase
                                // Preserve other registers during SETUP
                                base_addr    <= base_addr;
                                burst_type   <= burst_type;
                                burst_size   <= burst_size;
                                burst_count  <= burst_count;
                                burst_active <= burst_active;
                                write_pending <= write_pending;
                            end
                            default: begin
                                // Hold all values when HREADY is low
                                base_addr    <= base_addr;
                                current_addr <= current_addr;
                                burst_type   <= burst_type;
                                burst_size   <= burst_size;
                                burst_count  <= burst_count;
                                burst_index  <= burst_index;
                                burst_active <= burst_active;
                                last_beat    <= last_beat;
                                write_pending <= write_pending;
                            end
                        endcase
                    end

                    ACCESS: begin
                        // Maintain all values during ACCESS
                        base_addr    <= base_addr;
                        current_addr <= current_addr;
                        burst_type   <= burst_type;
                        burst_size   <= burst_size;
                        burst_count  <= burst_count;
                        burst_index  <= burst_index;
                        burst_active <= burst_active;
                        last_beat    <= last_beat;
                        write_pending <= write_pending;
                    end

                    default: begin
                        // Default hold
                        base_addr    <= base_addr;
                        current_addr <= current_addr;
                        burst_type   <= burst_type;
                        burst_size   <= burst_size;
                        burst_count  <= burst_count;
                        burst_index  <= burst_index;
                        burst_active <= burst_active;
                        last_beat    <= last_beat;
                        write_pending <= write_pending;
                    end
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // Block 3: Combinational Next State Logic (case-only)
    // -----------------------------------------------------------------
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case ({HSEL, HTRANS[1]})
                    2'b11: next_state = SETUP;   // Valid non-IDLE transfer
                    default: next_state = IDLE;
                endcase
            end

            SETUP: begin
                case (HREADY)
                    1'b1: next_state = ACCESS;
                    default: next_state = SETUP;
                endcase
            end

            ACCESS: begin
                case ({HREADY, last_beat})
                    2'b11: next_state = IDLE;      // Done with burst
                    2'b10: next_state = SETUP;     // More beats in burst
                    default: next_state = ACCESS;
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // Block 4: Combinational Output & Address Calculation (case-only)
    // -----------------------------------------------------------------
    always_comb begin
        // Default values
        hready_next     = 1'b1;
        hresp_next      = 2'b00;
        mem_addr_next   = current_addr;
        mem_we_next     = 1'b0;
        mem_re_next     = 1'b0;
        mem_wdata_next  = HWDATA;
        next_addr_calc  = current_addr;
        addr_align_error = 1'b0;

        // Address alignment check based on HSIZE
        case (burst_size)
            3'b000: addr_align_error = |current_addr[1:0];  // Byte
            3'b001: addr_align_error = current_addr[0];     // Halfword
            3'b010: addr_align_error = |current_addr[1:0];  // Word
            default: addr_align_error = 1'b0;
        endcase

        // Next address calculation based on burst type
        case (burst_type)
            3'b000: begin  // SINGLE
                next_addr_calc = current_addr + (32'd1 << burst_size);
            end

            3'b001, 3'b011: begin  // INCR4, INCR (treated as INCR4 for simplicity)
                next_addr_calc = current_addr + (32'd1 << burst_size);
            end

            3'b010: begin  // WRAP4
                case (burst_size)
                    3'b010: begin  // Word wrapping
                        case (burst_index)
                            2'd0: next_addr_calc = {current_addr[31:4], current_addr[3:0] + 4'd4};
                            2'd1: next_addr_calc = {current_addr[31:4], current_addr[3:0] + 4'd8};
                            2'd2: next_addr_calc = {current_addr[31:4], current_addr[3:0] + 4'd12};
                            default: next_addr_calc = {current_addr[31:4], 4'd0};
                        endcase
                    end
                    default: next_addr_calc = current_addr + (32'd1 << burst_size);
                endcase
            end

            default: begin
                next_addr_calc = current_addr;
            end
        endcase

        // Main output control based on state and burst conditions
        case (current_state)
            IDLE: begin
                case ({HSEL, HTRANS[1]})
                    2'b11: begin
                        hready_next = 1'b0;  // Wait state for first access
                        case (HWRITE)
                            1'b1: mem_we_next = 1'b1;
                            1'b0: mem_re_next = 1'b1;
                        endcase
                    end
                    default: begin
                        hready_next = 1'b1;
                    end
                endcase
            end

            SETUP: begin
                case (addr_align_error)
                    1'b1: begin
                        hresp_next = 2'b01;  // ERROR response
                        hready_next = 1'b1;
                    end
                    default: begin
                        case (write_pending)
                            1'b1: mem_we_next = 1'b1;
                            1'b0: mem_re_next = 1'b1;
                        endcase
                        hready_next = 1'b0;  // Stall until memory ready
                    end
                endcase
            end

            ACCESS: begin
                case (HREADY)
                    1'b1: begin
                        hready_next = 1'b1;
                        hresp_next = 2'b00;  // OKAY response
                        // Prepare for next burst beat if needed
                        case (last_beat)
                            1'b0: begin
                                case (write_pending)
                                    1'b1: mem_we_next = 1'b1;
                                    1'b0: mem_re_next = 1'b1;
                                endcase
                            end
                        endcase
                    end
                    default: begin
                        hready_next = 1'b0;
                    end
                endcase
            end
        endcase

        // Error override for misaligned access
        case (addr_align_error)
            1'b1: begin
                case (current_state)
                    SETUP: begin
                        mem_we_next = 1'b0;
                        mem_re_next = 1'b0;
                    end
                endcase
            end
        endcase
    end

    // Connect outputs
    assign HREADY   = hready_next;
    assign HRESP    = hresp_next;
    assign HRDATA   = mem_read_data;
    assign mem_address = mem_addr_next;
    assign mem_write_en = mem_we_next;
    assign mem_read_en  = mem_re_next;
    assign mem_write_data = mem_wdata_next;

endmodule

//------------------------------------------------------------------------------
// Multi-Port Memory Arbiter with Write Priority
//
// A memory controller that arbitrates between 4 requesters (0-3) for a
// single memory bank. Features:
// - Write operations have absolute priority over reads
// - Round-robin arbitration among writers, and among readers when no writes
// - Sequential logic for state, combinational logic for grant/selection
// - No if/else statements - only case/casez/case inside
// - No loops
//------------------------------------------------------------------------------

module memory_arbiter (
    input  logic        clk,
    input  logic        rst_n,

    // Requester 0 interface
    input  logic        req0_wr,        // Write request
    input  logic        req0_rd,        // Read request
    input  logic [31:0] req0_addr,
    input  logic [31:0] req0_wdata,
    output logic        grant0_wr,      // Write grant
    output logic        grant0_rd,      // Read grant
    output logic [31:0] resp0_rdata,

    // Requester 1 interface
    input  logic        req1_wr,
    input  logic        req1_rd,
    input  logic [31:0] req1_addr,
    input  logic [31:0] req1_wdata,
    output logic        grant1_wr,
    output logic        grant1_rd,
    output logic [31:0] resp1_rdata,

    // Requester 2 interface
    input  logic        req2_wr,
    input  logic        req2_rd,
    input  logic [31:0] req2_addr,
    input  logic [31:0] req2_wdata,
    output logic        grant2_wr,
    output logic        grant2_rd,
    output logic [31:0] resp2_rdata,

    // Requester 3 interface
    input  logic        req3_wr,
    input  logic        req3_rd,
    input  logic [31:0] req3_addr,
    input  logic [31:0] req3_wdata,
    output logic        grant3_wr,
    output logic        grant3_rd,
    output logic [31:0] resp3_rdata,

    // Memory interface (single-ported)
    output logic        mem_wr_en,
    output logic [31:0] mem_addr,
    output logic [31:0] mem_wdata,
    input  logic [31:0] mem_rdata
);

    //--------------------------------------------------------------------------
    // Internal signals
    //--------------------------------------------------------------------------
    typedef enum logic [3:0] {  // Use 4 bits for 9 states (0-8)
        STATE_IDLE    = 4'b0000,
        STATE_WRITE0  = 4'b0001,
        STATE_WRITE1  = 4'b0010,
        STATE_WRITE2  = 4'b0011,
        STATE_WRITE3  = 4'b0100,
        STATE_READ0   = 4'b0101,
        STATE_READ1   = 4'b0110,
        STATE_READ2   = 4'b0111,
        STATE_READ3   = 4'b1000
    } state_t;

    state_t curr_state, next_state;

    // Arbitration priority tracking
    logic [1:0] last_wr_served;    // Last writer served (for round-robin)
    logic [1:0] last_rd_served;    // Last reader served (for round-robin)

    // Combined request vectors
    logic [3:0] wr_req_vec;         // Write requests from all requesters
    logic [3:0] rd_req_vec;         // Read requests from all requesters

    // Selected requester ID and operation
    logic [1:0] selected_id;
    logic       selected_is_write;

    // Grant signals (combinatorial)
    logic [3:0] grant_wr_vec;
    logic [3:0] grant_rd_vec;
    logic [31:0] rdata_vec [3:0];   // Read data per requester

    //--------------------------------------------------------------------------
    // Block 1: COMBINATIONAL - Build request vectors and priority selection
    // Uses case statements to implement priority encoder with round-robin
    //--------------------------------------------------------------------------
    always_comb begin
        // Build request vectors
        wr_req_vec = {req3_wr, req2_wr, req1_wr, req0_wr};
        rd_req_vec = {req3_rd, req2_rd, req1_rd, req0_rd};

        // Default assignments
        selected_id = 2'b00;
        selected_is_write = 1'b0;

        // Priority arbitration: Write requests have absolute priority
        // Use casez to find highest priority pending write with round-robin
        casez ({wr_req_vec, last_wr_served})
            // Round-robin starting point based on last_wr_served
            6'b???1_00: begin selected_id = 2'b00; selected_is_write = 1'b1; end  // req0_wr
            6'b??1?_01: begin selected_id = 2'b01; selected_is_write = 1'b1; end  // req1_wr
            6'b?1??_10: begin selected_id = 2'b10; selected_is_write = 1'b1; end  // req2_wr
            6'b1???_11: begin selected_id = 2'b11; selected_is_write = 1'b1; end  // req3_wr
            // Wrap-around cases (if starting point has no request)
            6'b???1_11: begin selected_id = 2'b00; selected_is_write = 1'b1; end
            6'b??1?_00: begin selected_id = 2'b01; selected_is_write = 1'b1; end
            6'b?1??_01: begin selected_id = 2'b10; selected_is_write = 1'b1; end
            6'b1???_10: begin selected_id = 2'b11; selected_is_write = 1'b1; end
            default: begin
                // No writes - handle reads with round-robin
                casez ({rd_req_vec, last_rd_served})
                    6'b???1_00: begin selected_id = 2'b00; selected_is_write = 1'b0; end
                    6'b??1?_01: begin selected_id = 2'b01; selected_is_write = 1'b0; end
                    6'b?1??_10: begin selected_id = 2'b10; selected_is_write = 1'b0; end
                    6'b1???_11: begin selected_id = 2'b11; selected_is_write = 1'b0; end
                    6'b???1_11: begin selected_id = 2'b00; selected_is_write = 1'b0; end
                    6'b??1?_00: begin selected_id = 2'b01; selected_is_write = 1'b0; end
                    6'b?1??_01: begin selected_id = 2'b10; selected_is_write = 1'b0; end
                    6'b1???_10: begin selected_id = 2'b11; selected_is_write = 1'b0; end
                    default: begin
                        selected_id = 2'b00;
                        selected_is_write = 1'b0;
                    end
                endcase
            end
        endcase
    end

    //--------------------------------------------------------------------------
    // Block 2: COMBINATIONAL - Generate per-requester grant signals and data
    // Uses case statements to decode selected_id into individual grants
    //--------------------------------------------------------------------------
    always_comb begin
        // Default: all grants deasserted
        grant_wr_vec = 4'b0000;
        grant_rd_vec = 4'b0000;

        // Set read data for each requester based on memory output
        rdata_vec[0] = mem_rdata;
        rdata_vec[1] = mem_rdata;
        rdata_vec[2] = mem_rdata;
        rdata_vec[3] = mem_rdata;

        // Decode selected requester and operation type
        case ({selected_is_write, selected_id})
            {1'b1, 2'b00}: grant_wr_vec[0] = 1'b1;
            {1'b1, 2'b01}: grant_wr_vec[1] = 1'b1;
            {1'b1, 2'b10}: grant_wr_vec[2] = 1'b1;
            {1'b1, 2'b11}: grant_wr_vec[3] = 1'b1;
            {1'b0, 2'b00}: grant_rd_vec[0] = 1'b1;
            {1'b0, 2'b01}: grant_rd_vec[1] = 1'b1;
            {1'b0, 2'b10}: grant_rd_vec[2] = 1'b1;
            {1'b0, 2'b11}: grant_rd_vec[3] = 1'b1;
            default: begin
                grant_wr_vec = 4'b0000;
                grant_rd_vec = 4'b0000;
            end
        endcase

        // Memory control signals based on selected operation
        case (selected_is_write)
            1'b1: begin
                mem_wr_en = 1'b1;
                // Select write data based on requester
                case (selected_id)
                    2'b00: mem_wdata = req0_wdata;
                    2'b01: mem_wdata = req1_wdata;
                    2'b10: mem_wdata = req2_wdata;
                    2'b11: mem_wdata = req3_wdata;
                    default: mem_wdata = 32'b0;
                endcase
                // Select address based on requester
                case (selected_id)
                    2'b00: mem_addr = req0_addr;
                    2'b01: mem_addr = req1_addr;
                    2'b10: mem_addr = req2_addr;
                    2'b11: mem_addr = req3_addr;
                    default: mem_addr = 32'b0;
                endcase
            end
            1'b0: begin
                mem_wr_en = 1'b0;
                mem_wdata = 32'b0;
                // Select address based on requester
                case (selected_id)
                    2'b00: mem_addr = req0_addr;
                    2'b01: mem_addr = req1_addr;
                    2'b10: mem_addr = req2_addr;
                    2'b11: mem_addr = req3_addr;
                    default: mem_addr = 32'b0;
                endcase
            end
            default: begin
                mem_wr_en = 1'b0;
                mem_addr = 32'b0;
                mem_wdata = 32'b0;
            end
        endcase
    end

    //--------------------------------------------------------------------------
    // Block 3: COMBINATIONAL - Next state logic for FSM
    // Uses case statements to determine next state based on current state and
    // the selected operation from the arbitration logic
    //--------------------------------------------------------------------------
    always_comb begin
        next_state = curr_state;

        case (curr_state)
            STATE_IDLE: begin
                case ({selected_is_write, |wr_req_vec, |rd_req_vec})
                    3'b1_1_x: begin  // Write exists
                        case (selected_id)
                            2'b00: next_state = STATE_WRITE0;
                            2'b01: next_state = STATE_WRITE1;
                            2'b10: next_state = STATE_WRITE2;
                            2'b11: next_state = STATE_WRITE3;
                            default: next_state = STATE_IDLE;
                        endcase
                    end
                    3'b0_0_1: begin  // Only reads exist
                        case (selected_id)
                            2'b00: next_state = STATE_READ0;
                            2'b01: next_state = STATE_READ1;
                            2'b10: next_state = STATE_READ2;
                            2'b11: next_state = STATE_READ3;
                            default: next_state = STATE_IDLE;
                        endcase
                    end
                    default: next_state = STATE_IDLE;
                endcase
            end

            STATE_WRITE0: next_state = STATE_IDLE;
            STATE_WRITE1: next_state = STATE_IDLE;
            STATE_WRITE2: next_state = STATE_IDLE;
            STATE_WRITE3: next_state = STATE_IDLE;

            STATE_READ0:  next_state = STATE_IDLE;
            STATE_READ1:  next_state = STATE_IDLE;
            STATE_READ2:  next_state = STATE_IDLE;
            STATE_READ3:  next_state = STATE_IDLE;

            default: next_state = STATE_IDLE;
        endcase
    end

    //--------------------------------------------------------------------------
    // Block 4: SEQUENTIAL - State register and priority tracking
    // Updates FSM state and maintains last-served IDs for round-robin
    //--------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                curr_state <= STATE_IDLE;
                last_wr_served <= 2'b00;
                last_rd_served <= 2'b00;
            end
            1'b1: begin
                curr_state <= next_state;

                // Update priority tracking based on completed operation
                case (curr_state)
                    STATE_WRITE0: last_wr_served <= 2'b00;
                    STATE_WRITE1: last_wr_served <= 2'b01;
                    STATE_WRITE2: last_wr_served <= 2'b10;
                    STATE_WRITE3: last_wr_served <= 2'b11;
                    STATE_READ0:  last_rd_served <= 2'b00;
                    STATE_READ1:  last_rd_served <= 2'b01;
                    STATE_READ2:  last_rd_served <= 2'b10;
                    STATE_READ3:  last_rd_served <= 2'b11;
                    default: begin
                        // No change on idle or other states
                        last_wr_served <= last_wr_served;
                        last_rd_served <= last_rd_served;
                    end
                endcase
            end
            default: begin
                curr_state <= STATE_IDLE;
                last_wr_served <= 2'b00;
                last_rd_served <= 2'b00;
            end
        endcase
    end

    //--------------------------------------------------------------------------
    // Output assignments (connect grant vectors to module ports)
    //--------------------------------------------------------------------------
    assign grant0_wr = grant_wr_vec[0];
    assign grant1_wr = grant_wr_vec[1];
    assign grant2_wr = grant_wr_vec[2];
    assign grant3_wr = grant_wr_vec[3];

    assign grant0_rd = grant_rd_vec[0];
    assign grant1_rd = grant_rd_vec[1];
    assign grant2_rd = grant_rd_vec[2];
    assign grant3_rd = grant_rd_vec[3];

    assign resp0_rdata = rdata_vec[0];
    assign resp1_rdata = rdata_vec[1];
    assign resp2_rdata = rdata_vec[2];
    assign resp3_rdata = rdata_vec[3];

endmodule

module edge_detector_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic rising_edge
);

typedef enum logic {IDLE, HIGH} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= IDLE;
    else
        state <= next_state;
end

// Next state and output logic (Mealy)
always_comb begin
    next_state = state;
    rising_edge = 1'b0;

    case (state)
        IDLE: if (din) begin
            next_state = HIGH;
            rising_edge = 1'b1;  // Output depends on input
        end

        HIGH: if (!din)
            next_state = IDLE;
    endcase
end

endmodule

module mipi_csi2_receiver (
    input logic clk,
    input logic rst_n,

    // MIPI D-PHY interface
    input logic [3:0] data_lane_p [0:3],      // 4 data lanes
    input logic [3:0] data_lane_n [0:3],
    input logic clk_lane_p,
    input logic clk_lane_n,
    input logic lp_mode,                       // Low power mode indicator

    // Protocol decoding
    output logic [15:0] pixel_data [0:3][0:255], // 4 lanes of pixel data
    output logic [7:0] line_length,
    output logic [15:0] frame_width,
    output logic [15:0] frame_height,
    output logic [3:0] data_type,               // RAW8, RAW10, RGB565, YUV422, etc.
    output logic [1:0] virtual_channel,
    output logic frame_start,
    output logic frame_end,
    output logic line_valid,
    output logic data_valid,

    // Error detection
    output logic ecc_error,
    output logic crc_error,
    output logic sync_error,

    // Statistics
    output logic [31:0] frame_count,
    output logic [31:0] line_count,
    output logic [31:0] byte_count
);

typedef enum logic [4:0] {
    IDLE,
    LP_STATE,
    HS_START,
    SYNC_PATTERN,
    ECC_CHECK,
    PH_HEADER,
    PH_DATA_TYPE,
    PH_WORD_COUNT,
    PH_ECC,
    PAYLOAD_DATA,
    CRC_CHECK,
    LINE_END,
    FRAME_START,
    FRAME_END,
    ERROR_RECOVERY,
    WAIT_HS_TRAIL,
    LP_11_STATE
} state_t;

state_t state, next_state;
logic [31:0] word_count;
logic [15:0] pixel_count [0:3];
logic [7:0] lane_data [0:3];
logic [3:0] lane_align;
logic [5:0] ecc_calc;
logic [5:0] ecc_recv;
logic [15:0] crc_calc;
logic [15:0] crc_recv;
logic [31:0] packet_data [0:255];
logic [2:0] lane_index;
logic sync_detected;
logic [7:0] sync_pattern;

// CSI-2 sync codes
parameter SYNC_CODE = 8'hB8;
parameter BLANKING_CODE = 8'h00;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        word_count <= 32'b0;
        lane_index <= 3'b0;
        pixel_count[0] <= 16'b0;
        pixel_count[1] <= 16'b0;
        pixel_count[2] <= 16'b0;
        pixel_count[3] <= 16'b0;
        frame_count <= 32'b0;
        line_count <= 32'b0;
        byte_count <= 32'b0;
        crc_calc <= 16'hFFFF;

        for (int i = 0; i < 4; i++)
            for (int j = 0; j < 256; j++)
                pixel_data[i][j] <= 16'b0;
    end else begin
        state <= next_state;

        case (state)
            HS_START: begin
                // Deserialize lane data
                for (int i = 0; i < 4; i++) begin
                    lane_data[i] <= {data_lane_p[i], data_lane_n[i]};
                end
            end

            SYNC_PATTERN: begin
                sync_pattern <= lane_data[0];
                sync_detected <= (lane_data[0] == SYNC_CODE);
            end

            PH_HEADER: begin
                packet_data[word_count] <= {lane_data[3], lane_data[2],
                                           lane_data[1], lane_data[0]};
                word_count <= word_count + 1;
            end

            PH_DATA_TYPE: begin
                data_type <= lane_data[0][3:0];
                virtual_channel <= lane_data[0][5:4];
            end

            PH_WORD_COUNT: begin
                word_count <= {lane_data[1], lane_data[0]};
            end

            PH_ECC: begin
                // Calculate ECC (simplified Hamming code)
                ecc_calc <= 6'b0;
                for (int i = 0; i < 24; i++) begin
                    // ECC calculation logic
                end
                ecc_recv <= lane_data[0][5:0];

                if (ecc_calc != ecc_recv)
                    ecc_error <= 1'b1;
            end

            PAYLOAD_DATA: begin
                if (word_count > 0) begin
                    // Distribute data across lanes
                    for (int lane = 0; lane < 4; lane++) begin
                        case (data_type)
                            4'b0010: begin  // RAW10
                                pixel_data[lane][pixel_count[lane]] <=
                                    {lane_data[lane][7:0], 2'b0};
                                pixel_count[lane] <= pixel_count[lane] + 1;
                            end

                            4'b0111: begin  // RGB565
                                pixel_data[lane][pixel_count[lane]] <=
                                    {lane_data[lane*2 +: 16]};
                                pixel_count[lane] <= pixel_count[lane] + 1;
                                lane_index <= lane_index + 1;
                            end

                            4'b1010: begin  // YUV422 8-bit
                                pixel_data[lane][pixel_count[lane]] <=
                                    {lane_data[lane][7:0], lane_data[lane][7:0]};
                                pixel_count[lane] <= pixel_count[lane] + 1;
                            end
                        endcase
                    end

                    word_count <= word_count - 1;
                    byte_count <= byte_count + 4;

                    // Update CRC
                    crc_calc <= crc_calc ^ {lane_data[3], lane_data[2],
                                           lane_data[1], lane_data[0]};
                end
            end

            CRC_CHECK: begin
                crc_recv <= {lane_data[1], lane_data[0]};
                if (crc_calc != crc_recv)
                    crc_error <= 1'b1;
            end

            LINE_END: begin
                line_valid <= 1'b1;
                line_length <= pixel_count[0][7:0];
                line_count <= line_count + 1;

                for (int i = 0; i < 4; i++)
                    pixel_count[i] <= 16'b0;
            end

            FRAME_START: begin
                frame_start <= 1'b1;
                frame_count <= frame_count + 1;
                line_count <= 32'b0;
            end

            FRAME_END: begin
                frame_end <= 1'b1;
                frame_height <= line_count[15:0];
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    data_valid = (state == PAYLOAD_DATA);

    case (state)
        IDLE: begin
            if (!lp_mode) begin
                next_state = LP_STATE;
            end
        end

        LP_STATE: begin
            if (clk_lane_p && !clk_lane_n)  // Clock rising
                next_state = HS_START;
        end

        HS_START: begin
            next_state = SYNC_PATTERN;
        end

        SYNC_PATTERN: begin
            if (sync_detected) begin
                next_state = PH_HEADER;
            end else if (lane_data[0] == BLANKING_CODE) begin
                next_state = LINE_END;
            end else begin
                sync_error <= 1'b1;
                next_state = ERROR_RECOVERY;
            end
        end

        PH_HEADER: begin
            next_state = PH_DATA_TYPE;
        end

        PH_DATA_TYPE: begin
            next_state = PH_WORD_COUNT;
        end

        PH_WORD_COUNT: begin
            next_state = PH_ECC;
        end

        PH_ECC: begin
            if (ecc_error)
                next_state = ERROR_RECOVERY;
            else begin
                case (data_type)
                    4'b0000: next_state = FRAME_START;  // Frame start code
                    4'b0001: next_state = FRAME_END;    // Frame end code
                    4'b0010, 4'b0111, 4'b1010: next_state = PAYLOAD_DATA;
                    default: next_state = WAIT_HS_TRAIL;
                endcase
            end
        end

        PAYLOAD_DATA: begin
            if (word_count == 0)
                next_state = CRC_CHECK;
        end

        CRC_CHECK: begin
            next_state = WAIT_HS_TRAIL;
        end

        LINE_END: begin
            next_state = WAIT_HS_TRAIL;
        end

        FRAME_START: begin
            frame_start <= 1'b0;
            next_state = WAIT_HS_TRAIL;
        end

        FRAME_END: begin
            frame_end <= 1'b0;
            next_state = WAIT_HS_TRAIL;
        end

        WAIT_HS_TRAIL: begin
            if (lp_mode)
                next_state = LP_11_STATE;
        end

        LP_11_STATE: begin
            if (!lp_mode)
                next_state = HS_START;
            else
                next_state = IDLE;
        end

        ERROR_RECOVERY: begin
            if (lp_mode)
                next_state = IDLE;
        end
    endcase
end

endmodule

module pcie_tlp_processor (
    input logic clk,
    input logic rst_n,
    input logic [63:0] tlp_header [0:3],     // 4 DW TLP header
    input logic [31:0] payload_data [0:255], // Payload data
    input logic [7:0] payload_length,
    input logic tlp_valid,
    input logic [11:0] credits_available,     // Flow control credits
    input logic [2:0] traffic_class,
    output logic [63:0] processed_header [0:3],
    output logic tlp_forward,
    output logic [1:0] tlp_type,               // 00:MRd,01:MWr,10:Cpl,11:CplD
    output logic [9:0] requester_id,
    output logic [7:0] tag,
    output logic [3:0] first_be,               // First DW byte enable
    output logic [3:0] last_be,                // Last DW byte enable
    output logic credit_consumed,
    output logic [11:0] credits_remaining
);

typedef enum logic [3:0] {
    IDLE,
    PARSE_HEADER,
    CHECK_CREDITS,
    MEMORY_READ,
    MEMORY_WRITE,
    COMPLETION,
    COMPLETION_DATA,
    CHECK_ADDRESS_ALIGN,
    PROCESS_PAYLOAD,
    UPDATE_CREDITS,
    FORWARD_PACKET,
    REJECT_PACKET,
    WAIT_CREDITS
} state_t;

state_t state, next_state;
logic [63:0] header [0:3];
logic [31:0] address;
logic [9:0] req_id;
logic [7:0] packet_tag;
logic [6:0] dw_count;
logic [11:0] required_credits;
logic [1:0] fmt_type;
logic [4:0] tlp_length;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        for (int i = 0; i < 4; i++)
            header[i] <= 64'b0;
        req_id <= 10'b0;
        packet_tag <= 8'b0;
        dw_count <= 7'b0;
        required_credits <= 12'b0;
    end else begin
        state <= next_state;

        case (state)
            IDLE: begin
                if (tlp_valid) begin
                    for (int i = 0; i < 4; i++)
                        header[i] <= tlp_header[i];
                end
            end

            PARSE_HEADER: begin
                // Parse TLP header fields
                fmt_type <= header[0][63:56];  // Fmt and Type fields
                tlp_length <= header[0][54:48]; // Length field (in DW)
                req_id <= header[1][31:22];     // Requester ID
                packet_tag <= header[1][21:16];  // Tag

                // Calculate required credits (1 credit = 4 DW)
                required_credits <= (tlp_length + 3) >> 2;
            end

            PROCESS_PAYLOAD: begin
                if (dw_count < tlp_length) begin
                    // Process payload data
                    dw_count <= dw_count + 1;
                end
            end

            UPDATE_CREDITS: begin
                credits_remaining <= credits_available - required_credits;
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    tlp_forward = 1'b0;
    credit_consumed = 1'b0;
    credits_remaining = credits_available;
    processed_header = header;
    tlp_type = 2'b00;
    requester_id = req_id;
    tag = packet_tag;

    case (state)
        IDLE: begin
            if (tlp_valid) begin
                next_state = PARSE_HEADER;
            end
        end

        PARSE_HEADER: begin
            case (fmt_type[6:5])  // Fmt field
                2'b00: begin  // 3 DW header, no data
                    next_state = CHECK_CREDITS;
                end
                2'b01: begin  // 4 DW header, no data
                    next_state = CHECK_CREDITS;
                end
                2'b10: begin  // 3 DW header, with data
                    next_state = PROCESS_PAYLOAD;
                end
                2'b11: begin  // 4 DW header, with data
                    next_state = PROCESS_PAYLOAD;
                end
            endcase
        end

        CHECK_CREDITS: begin
            if (required_credits <= credits_available) begin
                case (fmt_type[4:0])  // Type field
                    5'b00000: begin  // Memory Read
                        next_state = MEMORY_READ;
                    end
                    5'b00001: begin  // Memory Write
                        next_state = MEMORY_WRITE;
                    end
                    5'b01010: begin  // Completion
                        next_state = COMPLETION;
                    end
                    5'b01011: begin  // Completion with Data
                        next_state = COMPLETION_DATA;
                    end
                    default: begin
                        next_state = REJECT_PACKET;
                    end
                endcase
            end else begin
                next_state = WAIT_CREDITS;
            end
        end

        MEMORY_READ: begin
            tlp_type = 2'b00;
            address = {header[2][31:0], header[3][31:0]};
            first_be = header[1][15:12];
            last_be = header[1][11:8];
            next_state = UPDATE_CREDITS;
        end

        MEMORY_WRITE: begin
            tlp_type = 2'b01;
            address = {header[2][31:0], header[3][31:0]};
            first_be = header[1][15:12];
            last_be = header[1][11:8];
            next_state = PROCESS_PAYLOAD;
        end

        COMPLETION: begin
            tlp_type = 2'b10;
            next_state = UPDATE_CREDITS;
        end

        COMPLETION_DATA: begin
            tlp_type = 2'b11;
            next_state = PROCESS_PAYLOAD;
        end

        PROCESS_PAYLOAD: begin
            if (dw_count >= tlp_length - 1) begin
                case (tlp_type)
                    2'b00, 2'b10: next_state = UPDATE_CREDITS;
                    2'b01, 2'b11: next_state = FORWARD_PACKET;
                endcase
            end
        end

        UPDATE_CREDITS: begin
            credit_consumed = 1'b1;
            next_state = FORWARD_PACKET;
        end

        FORWARD_PACKET: begin
            tlp_forward = 1'b1;
            next_state = IDLE;
        end

        WAIT_CREDITS: begin
            // Wait for credits to become available
            if (required_credits <= credits_available)
                next_state = MEMORY_READ;
        end

        REJECT_PACKET: begin
            // Reject unsupported TLP types
            next_state = IDLE;
        end
    endcase
end

endmodule

// DDR3 Memory Controller Command Scheduler
// Uses ONLY case statements - no if/else, no loops
// Manages command priority, bank state machine, and timing constraints

module ddr3_cmd_scheduler (
    input  logic        clk,
    input  logic        rst_n,

    // Command interface from controller
    input  logic [2:0]  cmd_type,      // 0:ACT, 1:RD, 2:WR, 3:PRE, 4:REF, 5:ZQ
    input  logic [2:0]  bank_addr,
    input  logic [14:0] row_addr,
    input  logic        cmd_valid,
    output logic        cmd_ready,

    // Command output to PHY
    output logic [2:0]  phy_cmd_type,
    output logic [2:0]  phy_bank_addr,
    output logic [14:0] phy_row_addr,
    output logic        phy_cmd_valid,
    input  logic        phy_cmd_accept,

    // Bank status
    input  logic [7:0]  bank_active_row [7:0],  // Current open row per bank
    input  logic [7:0]  bank_state      [7:0],  // 0:idle, 1:active, 2:precharging
    input  logic [7:0]  bank_timer      [7:0]   // Timing constraint counters
);

    //=========================================================================
    // Local parameters
    //=========================================================================
    localparam CMD_ACT = 3'd0;
    localparam CMD_RD  = 3'd1;
    localparam CMD_WR  = 3'd2;
    localparam CMD_PRE = 3'd3;
    localparam CMD_REF = 3'd4;
    localparam CMD_ZQ  = 3'd5;

    localparam BANK_IDLE       = 3'd0;
    localparam BANK_ACTIVE     = 3'd1;
    localparam BANK_PRECHARGING = 3'd2;

    localparam SCHED_IDLE      = 2'd0;
    localparam SCHED_CHECK     = 2'd1;
    localparam SCHED_ISSUE     = 2'd2;
    localparam SCHED_WAIT      = 2'd3;

    //=========================================================================
    // Internal signals
    //=========================================================================
    logic [1:0]  sched_state;
    logic [2:0]  selected_bank;
    logic [2:0]  pending_cmd_type;
    logic [2:0]  pending_bank;
    logic [14:0] pending_row;
    logic        pending_valid;

    logic [2:0]  arbitration_result;
    logic        bank_match;
    logic        row_match;
    logic        bank_ready;
    logic [7:0]  bank_active_row_local;
    logic [7:0]  bank_state_local;
    logic [7:0]  bank_timer_local;

    //=========================================================================
    // Block 1: Combinational - Command Arbitration
    // Selects highest priority command from pending queue
    // Uses case statement for priority encoding
    //=========================================================================
    always_comb begin
        // Default values
        arbitration_result = 3'd0;

        // Priority encoder using nested case statements
        // Priority: REF > ZQ > ACT > PRE > WR > RD
        case (cmd_valid)
            1'b1: begin
                case (cmd_type)
                    CMD_REF: arbitration_result = CMD_REF;
                    CMD_ZQ:  arbitration_result = CMD_ZQ;
                    CMD_ACT: arbitration_result = CMD_ACT;
                    CMD_PRE: arbitration_result = CMD_PRE;
                    CMD_WR:  arbitration_result = CMD_WR;
                    CMD_RD:  arbitration_result = CMD_RD;
                    default: arbitration_result = CMD_RD;
                endcase
            end
            default: arbitration_result = 3'b111;  // No command
        endcase
    end

    //=========================================================================
    // Block 2: Combinational - Bank Status Evaluation
    // Determines if selected bank can accept the command
    // Uses case statements for bank state and timing checks
    //=========================================================================
    always_comb begin
        // Extract bank-specific signals
        case (pending_bank)
            3'd0: begin
                bank_active_row_local = bank_active_row[0];
                bank_state_local = bank_state[0];
                bank_timer_local = bank_timer[0];
            end
            3'd1: begin
                bank_active_row_local = bank_active_row[1];
                bank_state_local = bank_state[1];
                bank_timer_local = bank_timer[1];
            end
            3'd2: begin
                bank_active_row_local = bank_active_row[2];
                bank_state_local = bank_state[2];
                bank_timer_local = bank_timer[2];
            end
            3'd3: begin
                bank_active_row_local = bank_active_row[3];
                bank_state_local = bank_state[3];
                bank_timer_local = bank_timer[3];
            end
            3'd4: begin
                bank_active_row_local = bank_active_row[4];
                bank_state_local = bank_state[4];
                bank_timer_local = bank_timer[4];
            end
            3'd5: begin
                bank_active_row_local = bank_active_row[5];
                bank_state_local = bank_state[5];
                bank_timer_local = bank_timer[5];
            end
            3'd6: begin
                bank_active_row_local = bank_active_row[6];
                bank_state_local = bank_state[6];
                bank_timer_local = bank_timer[6];
            end
            default: begin
                bank_active_row_local = bank_active_row[7];
                bank_state_local = bank_state[7];
                bank_timer_local = bank_timer[7];
            end
        endcase

        // Check if row matches open row
        row_match = (bank_active_row_local == pending_row);

        // Check if bank is ready based on state and timer
        case (bank_state_local)
            BANK_IDLE: begin
                case (pending_cmd_type)
                    CMD_ACT: bank_ready = (bank_timer_local == 8'd0);  // tRRD check
                    CMD_REF: bank_ready = (bank_timer_local == 8'd0);  // tRC check
                    default: bank_ready = 1'b0;  // Can't do RD/WR on idle bank
                endcase
            end
            BANK_ACTIVE: begin
                case (pending_cmd_type)
                    CMD_RD, CMD_WR: begin
                        case (row_match)
                            1'b1: bank_ready = (bank_timer_local == 8'd0);  // tRCD satisfied
                            1'b0: bank_ready = 1'b0;  // Need PRE first
                        endcase
                    end
                    CMD_PRE: bank_ready = (bank_timer_local == 8'd0);  // tRAS satisfied
                    default: bank_ready = 1'b0;
                endcase
            end
            BANK_PRECHARGING: begin
                case (pending_cmd_type)
                    CMD_ACT: bank_ready = (bank_timer_local == 8'd0);  // tRP satisfied
                    default: bank_ready = 1'b0;
                endcase
            end
            default: bank_ready = 1'b0;
        endcase
    end

	//=========================================================================
    // Block 3: Sequential - Command Pending Register
    // Latches incoming command when accepted
    // Uses case for state-based latching
    //=========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pending_cmd_type <= 3'd0;
            pending_bank     <= 3'd0;
            pending_row      <= 15'd0;
            pending_valid    <= 1'b0;
            cmd_ready        <= 1'b1;
        end else begin
            case (sched_state)
                SCHED_IDLE: begin
                    // Accept new command when scheduler idle
                    case (cmd_valid)
                        1'b1: begin
                            pending_cmd_type <= arbitration_result;
                            pending_bank     <= bank_addr;
                            pending_row      <= row_addr;
                            pending_valid    <= 1'b1;
                            cmd_ready        <= 1'b0;
                        end
                        default: begin
                            pending_valid <= 1'b0;
                            cmd_ready     <= 1'b1;
                        end
                    endcase
                end
                SCHED_ISSUE: begin
                    // Command issued, clear pending
                    case (phy_cmd_accept)
                        1'b1: begin
                            pending_valid <= 1'b0;
                            cmd_ready     <= 1'b1;
                        end
                        default: begin
                            pending_valid <= pending_valid;
                            cmd_ready     <= 1'b0;
                        end
                    endcase
                end
                default: begin
                    // Keep pending during check/wait states
                    pending_valid <= pending_valid;
                    cmd_ready     <= 1'b0;
                end
            endcase
        end
    end

    //=========================================================================
    // Block 4: Sequential - Scheduler FSM
    // Manages command issuance flow using case statements
    //=========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sched_state   <= SCHED_IDLE;
            phy_cmd_type  <= 3'd0;
            phy_bank_addr <= 3'd0;
            phy_row_addr  <= 15'd0;
            phy_cmd_valid <= 1'b0;
        end else begin
            case (sched_state)
                SCHED_IDLE: begin
                    phy_cmd_valid <= 1'b0;
                    case (pending_valid)
                        1'b1: sched_state <= SCHED_CHECK;
                        default: sched_state <= SCHED_IDLE;
                    endcase
                end

                SCHED_CHECK: begin
                    phy_cmd_valid <= 1'b0;
                    // Evaluate if command can be issued based on bank status
                    case (bank_ready)
                        1'b1: sched_state <= SCHED_ISSUE;
                        1'b0: begin
                            // Need to insert auto-precharge if row mismatch
                            case ({pending_cmd_type, bank_state_local, row_match})
                                {CMD_RD, BANK_ACTIVE, 1'b0},
                                {CMD_WR, BANK_ACTIVE, 1'b0}: begin
                                    // Auto-generate precharge command
                                    phy_cmd_type  <= CMD_PRE;
                                    phy_bank_addr <= pending_bank;
                                    phy_row_addr  <= 15'd0;
                                    phy_cmd_valid <= 1'b1;
                                    sched_state   <= SCHED_WAIT;
                                end
                                default: sched_state <= SCHED_WAIT;
                            endcase
                        end
                    endcase
                end

                SCHED_ISSUE: begin
                    // Issue the pending command
                    case (pending_valid)
                        1'b1: begin
                            phy_cmd_type  <= pending_cmd_type;
                            phy_bank_addr <= pending_bank;
                            phy_row_addr  <= pending_row;
                            phy_cmd_valid <= 1'b1;

                            case (phy_cmd_accept)
                                1'b1: sched_state <= SCHED_IDLE;
                                default: sched_state <= SCHED_ISSUE;
                            endcase
                        end
                        default: sched_state <= SCHED_IDLE;
                    endcase
                end

                SCHED_WAIT: begin
                    // Wait for timing constraints
                    case (phy_cmd_accept)
                        1'b1: begin
                            phy_cmd_valid <= 1'b0;
                            sched_state   <= SCHED_IDLE;
                        end
                        default: begin
                            phy_cmd_valid <= phy_cmd_valid;
                            sched_state   <= SCHED_WAIT;
                        end
                    endcase
                end

                default: sched_state <= SCHED_IDLE;
            endcase
        end
    end

endmodule

module image_signal_processor (
    input logic clk,
    input logic rst_n,

    // Bayer pattern input (RAW sensor data)
    input logic [9:0] bayer_pixel,
    input logic [15:0] frame_width,
    input logic [15:0] frame_height,
    input logic hsync,
    input logic vsync,
    input logic pixel_valid,

    // Configuration registers
    input logic [15:0] white_balance_r,
    input logic [15:0] white_balance_g,
    input logic [15:0] white_balance_b,
    input logic [7:0] gamma_lut [0:255],
    input logic [2:0] bayer_pattern,  // 0: RGGB, 1: GRBG, 2: GBRG, 3: BGGR

    // RGB output (24-bit)
    output logic [7:0] rgb_r,
    output logic [7:0] rgb_g,
    output logic [7:0] rgb_b,
    output logic rgb_valid,
    output logic frame_sync,
    output logic line_sync
);

//-------------------------------------------------------------------------
// Pipeline Stage 1: Bayer Demosaic
//-------------------------------------------------------------------------
typedef struct {
    logic [9:0] pixels [0:2][0:2];  // 3x3 window
    logic [15:0] x_count;
    logic [15:0] y_count;
    logic hsync_d1;
    logic vsync_d1;
    logic valid_d1;
} stage1_t;

stage1_t stage1_reg, stage1_next;
logic [9:0] line_buffer [0:2047][0:1];  // 2-line buffer for 3x3 window

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage1_reg.x_count <= 16'b0;
        stage1_reg.y_count <= 16'b0;
        stage1_reg.hsync_d1 <= 1'b0;
        stage1_reg.vsync_d1 <= 1'b0;
        stage1_reg.valid_d1 <= 1'b0;

        for (int i = 0; i < 2048; i++)
            for (int j = 0; j < 2; j++)
                line_buffer[i][j] <= 10'b0;
    end else begin
        stage1_reg <= stage1_next;

        // Update line buffer
        if (pixel_valid) begin
            line_buffer[stage1_reg.x_count][0] <= bayer_pixel;
            line_buffer[stage1_reg.x_count][1] <= line_buffer[stage1_reg.x_count][0];
        end
    end
end

always_comb begin
    stage1_next = stage1_reg;
    stage1_next.hsync_d1 = hsync;
    stage1_next.vsync_d1 = vsync;
    stage1_next.valid_d1 = pixel_valid;

    if (pixel_valid) begin
        stage1_next.x_count = stage1_reg.x_count + 1;

        // Update 3x3 window
        stage1_next.pixels[0][0] = stage1_reg.pixels[0][1];
        stage1_next.pixels[0][1] = stage1_reg.pixels[0][2];
        stage1_next.pixels[0][2] = line_buffer[stage1_reg.x_count][1];

        stage1_next.pixels[1][0] = stage1_reg.pixels[1][1];
        stage1_next.pixels[1][1] = stage1_reg.pixels[1][2];
        stage1_next.pixels[1][2] = line_buffer[stage1_reg.x_count][0];

        stage1_next.pixels[2][0] = stage1_reg.pixels[2][1];
        stage1_next.pixels[2][1] = stage1_reg.pixels[2][2];
        stage1_next.pixels[2][2] = bayer_pixel;

        if (stage1_reg.x_count == frame_width - 1) begin
            stage1_next.x_count = 16'b0;
            stage1_next.y_count = stage1_reg.y_count + 1;
        end
    end
end

//-------------------------------------------------------------------------
// Stage 1 Output: Demosaic Interpolation
//-------------------------------------------------------------------------
logic [15:0] r_interp, g_interp, b_interp;
logic stage1_valid;

always_comb begin
    stage1_valid = stage1_reg.valid_d1 &&
                   stage1_reg.x_count > 0 &&
                   stage1_reg.x_count < frame_width - 1 &&
                   stage1_reg.y_count > 0 &&
                   stage1_reg.y_count < frame_height - 1;

    if (stage1_valid) begin
        case (bayer_pattern)
            3'b000: begin  // RGGB
                r_interp = (stage1_reg.pixels[0][0] + stage1_reg.pixels[0][2] +
                           stage1_reg.pixels[2][0] + stage1_reg.pixels[2][2]) >> 2;
                g_interp = (stage1_reg.pixels[0][1] + stage1_reg.pixels[1][0] +
                           stage1_reg.pixels[1][2] + stage1_reg.pixels[2][1]) >> 2;
                b_interp = stage1_reg.pixels[1][1];
            end

            3'b001: begin  // GRBG
                g_interp = (stage1_reg.pixels[0][0] + stage1_reg.pixels[0][2] +
                           stage1_reg.pixels[2][0] + stage1_reg.pixels[2][2]) >> 2;
                r_interp = (stage1_reg.pixels[0][1] + stage1_reg.pixels[1][0] +
                           stage1_reg.pixels[1][2] + stage1_reg.pixels[2][1]) >> 2;
                b_interp = stage1_reg.pixels[1][1];
            end

            3'b010: begin  // GBRG
                g_interp = (stage1_reg.pixels[0][0] + stage1_reg.pixels[0][2] +
                           stage1_reg.pixels[2][0] + stage1_reg.pixels[2][2]) >> 2;
                b_interp = (stage1_reg.pixels[0][1] + stage1_reg.pixels[1][0] +
                           stage1_reg.pixels[1][2] + stage1_reg.pixels[2][1]) >> 2;
                r_interp = stage1_reg.pixels[1][1];
            end

            3'b011: begin  // BGGR
                b_interp = (stage1_reg.pixels[0][0] + stage1_reg.pixels[0][2] +
                           stage1_reg.pixels[2][0] + stage1_reg.pixels[2][2]) >> 2;
                g_interp = (stage1_reg.pixels[0][1] + stage1_reg.pixels[1][0] +
                           stage1_reg.pixels[1][2] + stage1_reg.pixels[2][1]) >> 2;
                r_interp = stage1_reg.pixels[1][1];
            end
        endcase
    end else begin
        r_interp = 16'b0;
        g_interp = 16'b0;
        b_interp = 16'b0;
    end
end

//-------------------------------------------------------------------------
// Pipeline Stage 2: White Balance
//-------------------------------------------------------------------------
typedef struct {
    logic [23:0] rgb_data;  // 8-bit per channel after white balance
    logic hsync_d2;
    logic vsync_d2;
    logic valid_d2;
} stage2_t;

stage2_t stage2_reg, stage2_next;
logic [23:0] wb_r, wb_g, wb_b;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage2_reg.valid_d2 <= 1'b0;
        stage2_reg.hsync_d2 <= 1'b0;
        stage2_reg.vsync_d2 <= 1'b0;
        stage2_reg.rgb_data <= 24'b0;
    end else begin
        stage2_reg <= stage2_next;
    end
end

always_comb begin
    stage2_next = stage2_reg;
    stage2_next.hsync_d2 = stage1_reg.hsync_d1;
    stage2_next.vsync_d2 = stage1_reg.vsync_d1;
    stage2_next.valid_d2 = stage1_valid;

    // Apply white balance gains
    wb_r = (r_interp * white_balance_r) >> 8;
    wb_g = (g_interp * white_balance_g) >> 8;
    wb_b = (b_interp * white_balance_b) >> 8;

    // Clip to 8-bit
    stage2_next.rgb_data[23:16] = (wb_r[15:0] > 16'hFF00) ? 8'hFF : wb_r[15:8];
    stage2_next.rgb_data[15:8]  = (wb_g[15:0] > 16'hFF00) ? 8'hFF : wb_g[15:8];
    stage2_next.rgb_data[7:0]   = (wb_b[15:0] > 16'hFF00) ? 8'hFF : wb_b[15:8];
end

//-------------------------------------------------------------------------
// Pipeline Stage 3: Gamma Correction
//-------------------------------------------------------------------------
typedef struct {
    logic [7:0] r_gamma;
    logic [7:0] g_gamma;
    logic [7:0] b_gamma;
    logic hsync_d3;
    logic vsync_d3;
    logic valid_d3;
} stage3_t;

stage3_t stage3_reg, stage3_next;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage3_reg.valid_d3 <= 1'b0;
        stage3_reg.hsync_d3 <= 1'b0;
        stage3_reg.vsync_d3 <= 1'b0;
        stage3_reg.r_gamma <= 8'b0;
        stage3_reg.g_gamma <= 8'b0;
        stage3_reg.b_gamma <= 8'b0;
    end else begin
        stage3_reg <= stage3_next;
    end
end

always_comb begin
    stage3_next = stage3_reg;
    stage3_next.hsync_d3 = stage2_reg.hsync_d2;
    stage3_next.vsync_d3 = stage2_reg.vsync_d2;
    stage3_next.valid_d3 = stage2_reg.valid_d2;

    // Apply gamma correction using LUT
    stage3_next.r_gamma = gamma_lut[stage2_reg.rgb_data[23:16]];
    stage3_next.g_gamma = gamma_lut[stage2_reg.rgb_data[15:8]];
    stage3_next.b_gamma = gamma_lut[stage2_reg.rgb_data[7:0]];
end

//-------------------------------------------------------------------------
// Output Stage
//-------------------------------------------------------------------------
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rgb_r <= 8'b0;
        rgb_g <= 8'b0;
        rgb_b <= 8'b0;
        rgb_valid <= 1'b0;
        frame_sync <= 1'b0;
        line_sync <= 1'b0;
    end else begin
        rgb_r <= stage3_reg.r_gamma;
        rgb_g <= stage3_reg.g_gamma;
        rgb_b <= stage3_reg.b_gamma;
        rgb_valid <= stage3_reg.valid_d3;
        frame_sync <= stage3_reg.vsync_d3;
        line_sync <= stage3_reg.hsync_d3;
    end
end

endmodule

module ethernet_crc32_pipelined (
    input logic clk,
    input logic rst_n,
    input logic [7:0] data_in,
    input logic data_valid,
    input logic start_frame,
    input logic end_frame,
    output logic [31:0] crc_out,
    output logic crc_valid,
    output logic crc_error
);

//-------------------------------------------------------------------------
// State enumeration
//-------------------------------------------------------------------------
typedef enum logic [1:0] {
    IDLE,
    CALC,
    FINALIZE,
    CHECK
} state_t;

//-------------------------------------------------------------------------
// CRC32 Constants (Ethernet polynomial: 0x04C11DB7)
//-------------------------------------------------------------------------
parameter CRC32_POLY = 32'h04C11DB7;
parameter CRC32_INIT = 32'hFFFFFFFF;
parameter CRC32_RESIDUE = 32'hDEBB20E3;

//-------------------------------------------------------------------------
// Sequential logic: State and pipeline registers
//-------------------------------------------------------------------------
state_t state_reg, state_next;
logic [31:0] crc_reg, crc_next;
logic [31:0] crc_pipe1, crc_pipe2;
logic [7:0] data_pipe1, data_pipe2;
logic valid_pipe1, valid_pipe2;
logic start_pipe1, start_pipe2;
logic end_pipe1, end_pipe2;
logic [2:0] byte_count_reg, byte_count_next;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state_reg <= IDLE;
        crc_reg <= CRC32_INIT;
        crc_pipe1 <= 32'b0;
        crc_pipe2 <= 32'b0;
        data_pipe1 <= 8'b0;
        data_pipe2 <= 8'b0;
        valid_pipe1 <= 1'b0;
        valid_pipe2 <= 1'b0;
        start_pipe1 <= 1'b0;
        start_pipe2 <= 1'b0;
        end_pipe1 <= 1'b0;
        end_pipe2 <= 1'b0;
        byte_count_reg <= 3'b0;
    end else begin
        state_reg <= state_next;
        crc_reg <= crc_next;
        byte_count_reg <= byte_count_next;

        // Pipeline stage 1
        crc_pipe1 <= crc_reg;
        data_pipe1 <= data_in;
        valid_pipe1 <= data_valid;
        start_pipe1 <= start_frame;
        end_pipe1 <= end_frame;

        // Pipeline stage 2
        crc_pipe2 <= crc_pipe1;
        data_pipe2 <= data_pipe1;
        valid_pipe2 <= valid_pipe1;
        start_pipe2 <= start_pipe1;
        end_pipe2 <= end_pipe1;
    end
end

//-------------------------------------------------------------------------
// CRC32 calculation function (combinational)
//-------------------------------------------------------------------------
function automatic [31:0] crc32_byte;
    input [31:0] crc;
    input [7:0] data;
    logic [31:0] new_crc;
    logic [31:0] poly;
begin
    new_crc = crc ^ {24'b0, data};
    poly = CRC32_POLY;

    for (int i = 0; i < 8; i++) begin
        if (new_crc[0])
            new_crc = (new_crc >> 1) ^ poly;
        else
            new_crc = (new_crc >> 1);
    end

    crc32_byte = new_crc;
end
endfunction

//-------------------------------------------------------------------------
// Pipeline stage 1 combinational logic
//-------------------------------------------------------------------------
logic [31:0] crc_stage1_out;
logic [31:0] crc_stage1_init;
logic stage1_valid;

always_comb begin
    // Stage 1 CRC calculation
    if (start_pipe1)
        crc_stage1_init = CRC32_INIT;
    else
        crc_stage1_init = crc_pipe1;

    if (valid_pipe1)
        crc_stage1_out = crc32_byte(crc_stage1_init, data_in);
    else
        crc_stage1_out = crc_stage1_init;

    stage1_valid = valid_pipe1;
end

//-------------------------------------------------------------------------
// Pipeline stage 2 combinational logic
//-------------------------------------------------------------------------
logic [31:0] crc_stage2_out;
logic [31:0] crc_stage2_final;
logic stage2_start, stage2_end;

always_comb begin
    // Stage 2 CRC calculation
    if (start_pipe2)
        crc_stage2_out = crc32_byte(CRC32_INIT, data_pipe2);
    else if (valid_pipe2)
        crc_stage2_out = crc32_byte(crc_pipe2, data_pipe2);
    else
        crc_stage2_out = crc_pipe2;

    // Final XOR
    crc_stage2_final = ~crc_stage2_out;

    stage2_start = start_pipe2;
    stage2_end = end_pipe2;
end

//-------------------------------------------------------------------------
// Main FSM combinational logic
//-------------------------------------------------------------------------
always_comb begin
    state_next = state_reg;
    crc_next = crc_reg;
    byte_count_next = byte_count_reg;
    crc_out = 32'b0;
    crc_valid = 1'b0;
    crc_error = 1'b0;

    case (state_reg)
        IDLE: begin
            if (start_frame) begin
                state_next = CALC;
                crc_next = CRC32_INIT;
                byte_count_next = 3'b0;
            end
        end

        CALC: begin
            // Update CRC with pipelined output
            crc_next = crc_stage2_out;

            if (valid_pipe2)
                byte_count_next = byte_count_reg + 1;

            if (end_pipe2) begin
                state_next = FINALIZE;
                crc_next = crc_stage2_final;
            end
        end

        FINALIZE: begin
            crc_out = crc_reg;
            crc_valid = 1'b1;
            state_next = CHECK;
        end

        CHECK: begin
            // Check against expected residue
            if (crc_reg == CRC32_RESIDUE)
                crc_error = 1'b0;
            else
                crc_error = 1'b1;

            if (!data_valid)
                state_next = IDLE;
        end
    endcase
end

endmodule

module usb3_protocol_layer (
    input logic clk,
    input logic rst_n,
    input logic [31:0] packet_data [0:15],   // Packet data (max 16 DW)
    input logic [4:0] packet_length,
    input logic packet_valid,
    input logic [3:0] endpoint,
    input logic [2:0] device_address,
    input logic direction,                     // 0: OUT, 1: IN
    input logic setup_stage,

    // Link Management
    input logic [1:0] link_status,             // From PHY
    input logic link_up,
    output logic [1:0] link_command,

    // Protocol outputs
    output logic [31:0] rx_data [0:15],
    output logic [4:0] rx_length,
    output logic rx_valid,
    output logic [3:0] rx_endpoint,
    output logic [2:0] rx_device,
    output logic [1:0] transaction_type,       // 00:SETUP,01:DATA,10:STATUS,11:PING
    output logic [2:0] sequence_number,
    output logic data_xfer_complete,
    output logic link_power_state               // 0:L0,1:L1,2:L2
);

typedef enum logic [5:0] {
    // Link states
    LINK_RESET,
    LINK_POLLING,
    LINK_U0,              // Active
    LINK_U1,              // Sleep
    LINK_U2,              // Deep sleep
    LINK_U3,              // Suspend
    LINK_RECOVERY,
    LINK_HOT_RESET,

    // Protocol states
    PROTOCOL_IDLE,
    PROTOCOL_SETUP,
    PROTOCOL_DATA_OUT,
    PROTOCOL_DATA_IN,
    PROTOCOL_STATUS,
    PROTOCOL_PING,
    PROTOCOL_NYET,
    PROTOCOL_ERDY,

    // Packet handling
    PACKET_HEADER,
    PACKET_DATA,
    PACKET_CRC,
    PACKET_ACK,
    PACKET_NACK,
    PACKET_STALL,
    PACKET_NOTIFY,

    // Flow control
    FLOW_CREDIT_UPDATE,
    FLOW_WAIT,
    FLOW_TIMEOUT,

    // Error handling
    ERROR_RETRY,
    ERROR_RECOVERY,
    ERROR_TIMEOUT
} state_t;

state_t link_state, protocol_state, next_state;
logic [2:0] seq_num;
logic [3:0] credit_count [0:15];  // Credits per endpoint
logic [15:0] retry_counter;
logic [31:0] timeout_counter;
logic [4:0] data_phase;
logic burst_mode;
logic [2:0] retry_count;

// Packet type encoding
typedef enum logic [4:0] {
    PTYPE_SETUP     = 5'b00001,
    PTYPE_DATA      = 5'b00010,
    PTYPE_ACK       = 5'b00100,
    PTYPE_NACK      = 5'b01000,
    PTYPE_STALL     = 5'b10000,
    PTYPE_ERDY      = 5'b11000,
    PTYPE_PING      = 5'b10100,
    PTYPE_NOTIFY    = 5'b10010
} packet_type_t;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        link_state <= LINK_RESET;
        protocol_state <= PROTOCOL_IDLE;
        seq_num <= 3'b0;
        data_phase <= 5'b0;
        retry_count <= 3'b0;
        retry_counter <= 16'b0;
        timeout_counter <= 32'b0;

        for (int i = 0; i < 16; i++)
            credit_count[i] <= 4'b1111;  // Initial credits
    end else begin
        link_state <= next_state;
        protocol_state <= next_state;

        case (link_state)
            LINK_U0: begin
                // Update sequence number
                case (protocol_state)
                    PACKET_ACK: seq_num <= seq_num + 1;
                    PACKET_NACK: retry_count <= retry_count + 1;
                endcase
            end

            LINK_U1, LINK_U2: begin
                // Power saving states
                if (timeout_counter < 32'hFFFFFFFF)
                    timeout_counter <= timeout_counter + 1;
            end

            LINK_RECOVERY: begin
                retry_counter <= retry_counter + 1;
            end
        endcase

        case (protocol_state)
            FLOW_CREDIT_UPDATE: begin
                credit_count[endpoint] <= credit_count[endpoint] - 1;
            end

            ERROR_TIMEOUT: begin
                timeout_counter <= timeout_counter + 1;
            end
        endcase
    end
end

always_comb begin
    next_state = protocol_state;
    link_command = 2'b00;
    rx_valid = 1'b0;
    data_xfer_complete = 1'b0;
    link_power_state = 2'b00;
    transaction_type = 2'b00;
    sequence_number = seq_num;

    // Link state machine
    case (link_state)
        LINK_RESET: begin
            link_command = 2'b01;  // Reset
            if (link_up)
                next_state = LINK_POLLING;
        end

        LINK_POLLING: begin
            link_command = 2'b10;  // Polling
            if (link_status == 2'b11)
                next_state = LINK_U0;
        end

        LINK_U0: begin
            link_power_state = 2'b00;
            // Protocol handling in U0 state
            case (protocol_state)
                PROTOCOL_IDLE: begin
                    if (packet_valid) begin
                        case ({setup_stage, direction})
                            2'b10: next_state = PROTOCOL_SETUP;
                            2'b00: next_state = PROTOCOL_DATA_OUT;
                            2'b01: next_state = PROTOCOL_DATA_IN;
                        endcase
                    end

                    // Power management
                    if (timeout_counter > 10000)  // Idle timeout
                        next_state = LINK_U1;
                end

                PROTOCOL_SETUP: begin
                    transaction_type = 2'b00;
                    next_state = PACKET_HEADER;
                end

                PROTOCOL_DATA_OUT: begin
                    transaction_type = 2'b01;
                    if (credit_count[endpoint] > 0)
                        next_state = PACKET_HEADER;
                    else
                        next_state = FLOW_WAIT;
                end

                PROTOCOL_DATA_IN: begin
                    transaction_type = 2'b01;
                    next_state = PACKET_HEADER;
                end

                PROTOCOL_STATUS: begin
                    transaction_type = 2'b10;
                    next_state = PACKET_HEADER;
                end

                PROTOCOL_PING: begin
                    transaction_type = 2'b11;
                    next_state = PACKET_HEADER;
                end

                PACKET_HEADER: begin
                    // Send packet header
                    case (transaction_type)
                        2'b00: rx_data[0] = {PTYPE_SETUP, device_address, endpoint, seq_num};
                        2'b01: rx_data[0] = {PTYPE_DATA, device_address, endpoint, seq_num};
                        2'b10: rx_data[0] = {PTYPE_ERDY, device_address, endpoint, seq_num};
                        2'b11: rx_data[0] = {PTYPE_PING, device_address, endpoint, seq_num};
                    endcase

                    if (packet_length > 0)
                        next_state = PACKET_DATA;
                    else
                        next_state = PACKET_CRC;
                end

                PACKET_DATA: begin
                    // Transfer data payload
                    for (int i = 0; i < packet_length; i++)
                        rx_data[i+1] = packet_data[i];

                    data_phase <= data_phase + 1;
                    if (data_phase >= packet_length - 1)
                        next_state = PACKET_CRC;
                end

                PACKET_CRC: begin
                    // CRC generation and check
                    next_state = PACKET_ACK;
                end

                PACKET_ACK: begin
                    rx_valid = 1'b1;
                    rx_length = packet_length;
                    rx_endpoint = endpoint;
                    rx_device = device_address;

                    case (transaction_type)
                        2'b00: next_state = PROTOCOL_STATUS;
                        2'b01: begin
                            if (data_phase == 5'b11111)  // Max burst
                                next_state = PROTOCOL_STATUS;
                            else if (direction)
                                next_state = PROTOCOL_DATA_IN;
                            else
                                next_state = PROTOCOL_DATA_OUT;
                        end
                        2'b10: begin
                            data_xfer_complete = 1'b1;
                            next_state = PROTOCOL_IDLE;
                        end
                    endcase
                end

                PACKET_NACK: begin
                    if (retry_count < 3)
                        next_state = PACKET_HEADER;
                    else
                        next_state = ERROR_RETRY;
                end

                PACKET_STALL: begin
                    next_state = PROTOCOL_IDLE;
                end

                FLOW_WAIT: begin
                    if (credit_count[endpoint] > 0)
                        next_state = PROTOCOL_DATA_OUT;
                    else if (timeout_counter > 1000)
                        next_state = PROTOCOL_PING;
                end

                FLOW_CREDIT_UPDATE: begin
                    next_state = PROTOCOL_DATA_OUT;
                end

                ERROR_RETRY: begin
                    if (retry_counter < 100)
                        next_state = PACKET_HEADER;
                    else
                        next_state = ERROR_RECOVERY;
                end

                ERROR_RECOVERY: begin
                    link_command = 2'b11;  // Recovery
                    next_state = LINK_RECOVERY;
                end

                ERROR_TIMEOUT: begin
                    if (timeout_counter > 10000)
                        next_state = LINK_RECOVERY;
                end
            endcase
        end

        LINK_U1: begin
            link_power_state = 2'b01;
            link_command = 2'b01;  // Sleep
            if (packet_valid)
                next_state = LINK_RECOVERY;
        end

        LINK_U2: begin
            link_power_state = 2'b10;
            if (packet_valid)
                next_state = LINK_RECOVERY;
        end

        LINK_U3: begin
            link_power_state = 2'b11;
            // Wake on activity
        end

        LINK_RECOVERY: begin
            if (link_status == 2'b11)
                next_state = LINK_U0;
            else if (retry_counter > 1000)
                next_state = LINK_HOT_RESET;
        end

        LINK_HOT_RESET: begin
            link_command = 2'b00;  // Reset
            next_state = LINK_RESET;
        end
    endcase
end

endmodule

//=============================================================================
// ATM Transaction Controller
//
// Industry Theme: Financial Transaction State Machine
// - Uses only 'case' and 'casez' statements (no if/else)
// - 4 procedural blocks: 2 always_ff (sequential), 2 always_comb (combinational)
// - Implements card insertion, PIN verification, withdrawal, and balance inquiry
//=============================================================================

module atm_controller (
    // Clock and reset
    input  logic clk,
    input  logic rst_n,

    // Card interface
    input  logic card_inserted,
    input  logic [3:0] card_type,      // 4'b0001: debit, 4'b0010: credit, 4'b0100: prepaid

    // PIN pad interface
    input  logic [3:0] pin_entered,
    input  logic pin_enter_valid,

    // User selection (from touchscreen)
    input  logic [1:0] menu_select,    // 00: withdraw, 01: balance, 10: deposit, 11: exit

    // Amount entry
    input  logic [7:0] withdraw_amount,
    input  logic amount_valid,

    // Backend banking system interface
    input  logic [15:0] account_balance,
    input  logic pin_verified,
    input  logic transaction_approved,

    // Outputs
    output logic [7:0]  dispense_amount,
    output logic [15:0] new_balance,
    output logic [3:0]  transaction_status,  // 4-bit encoded status
    output logic        dispense_enable,
    output logic        card_eject,
    output logic        receipt_print
);

    //=========================================================================
    // State and Register Declarations
    //=========================================================================
    typedef enum logic [2:0] {
        IDLE,
        VERIFY_PIN,
        SELECT_TRANSACTION,
        PROCESS_WITHDRAWAL,
        PROCESS_BALANCE,
        COMPLETE,
        ERROR
    } state_t;

    state_t current_state, next_state;

    // Internal registers for transaction data
    logic [7:0]  pending_withdraw;
    logic [15:0] updated_balance;
    logic [3:0]  transaction_code;
    logic        card_valid;

    //=========================================================================
    // Block 1: Sequential State Register (always_ff with case)
    //=========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= IDLE;
            1'b1: current_state <= next_state;
        endcase
    end

    //=========================================================================
    // Block 2: Combinational Next State Logic (always_comb with casez)
    //=========================================================================
    always_comb begin
        next_state = current_state;  // Default to current

        casez (current_state)
            IDLE: begin
                casez ({card_inserted, card_type})
                    5'b1_0001: next_state = VERIFY_PIN;  // Debit card
                    5'b1_0010: next_state = VERIFY_PIN;  // Credit card
                    5'b1_0100: next_state = ERROR;       // Prepaid card not accepted
                    5'b0_????: next_state = IDLE;
                    default:   next_state = ERROR;
                endcase
            end

            VERIFY_PIN: begin
                casez ({pin_enter_valid, pin_verified})
                    2'b11: next_state = SELECT_TRANSACTION;
                    2'b10: next_state = ERROR;
                    2'b0?: next_state = VERIFY_PIN;
                    default: next_state = ERROR;
                endcase
            end

            SELECT_TRANSACTION: begin
                casez (menu_select)
                    2'b00: next_state = PROCESS_WITHDRAWAL;
                    2'b01: next_state = PROCESS_BALANCE;
                    2'b10: next_state = ERROR;      // Deposit not supported in this ATM
                    2'b11: next_state = COMPLETE;
                    default: next_state = SELECT_TRANSACTION;
                endcase
            end

            PROCESS_WITHDRAWAL: begin
                casez ({amount_valid, transaction_approved})
                    2'b11: next_state = COMPLETE;
                    2'b10: next_state = ERROR;
                    2'b0?: next_state = PROCESS_WITHDRAWAL;
                    default: next_state = ERROR;
                endcase
            end

            PROCESS_BALANCE: begin
                casez (transaction_approved)
                    1'b1: next_state = COMPLETE;
                    1'b0: next_state = ERROR;
                    default: next_state = PROCESS_BALANCE;
                endcase
            end

            COMPLETE: begin
                casez (card_inserted)
                    1'b1: next_state = COMPLETE;  // Wait for card removal
                    1'b0: next_state = IDLE;
                    default: next_state = COMPLETE;
                endcase
            end

            ERROR: begin
                casez (card_inserted)
                    1'b1: next_state = ERROR;     // Wait for card removal in error state
                    1'b0: next_state = IDLE;
                    default: next_state = ERROR;
                endcase
            end

            default: next_state = IDLE;
        endcase
    end
        //=========================================================================
    // Block 3: Sequential Transaction Processing (always_ff with case)
    //=========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                pending_withdraw <= 8'd0;
                updated_balance <= 16'd0;
                transaction_code <= 4'd0;
                card_valid <= 1'b0;
            end
            1'b1: begin
                case (current_state)
                    IDLE: begin
                        case (card_inserted)
                            1'b1: card_valid <= 1'b1;
                            1'b0: card_valid <= 1'b0;
                        endcase
                    end

                    VERIFY_PIN: begin
                        transaction_code <= 4'd1;  // PIN verification transaction
                    end

                    SELECT_TRANSACTION: begin
                        case (menu_select)
                            2'b00: transaction_code <= 4'd2;  // Withdrawal
                            2'b01: transaction_code <= 4'd3;  // Balance inquiry
                            2'b10: transaction_code <= 4'd4;  // Deposit (error case)
                            2'b11: transaction_code <= 4'd5;  // Exit
                        endcase
                    end

                    PROCESS_WITHDRAWAL: begin
                        case (amount_valid)
                            1'b1: pending_withdraw <= withdraw_amount;
                            default: ;
                        endcase

                        case (transaction_approved)
                            1'b1: updated_balance <= account_balance - pending_withdraw;
                            default: updated_balance <= account_balance;
                        endcase
                    end

                    PROCESS_BALANCE: begin
                        updated_balance <= account_balance;
                    end

                    COMPLETE: begin
                        case (menu_select)
                            2'b00: pending_withdraw <= 8'd0;  // Clear after completion
                            default: ;
                        endcase
                    end

                    ERROR: begin
                        transaction_code <= 4'd15;  // Error code
                        pending_withdraw <= 8'd0;
                    end
                endcase
            end
        endcase
    end

    //=========================================================================
    // Block 4: Combinational Output Logic (always_comb with case)
    //=========================================================================
    always_comb begin
        // Default assignments
        dispense_amount = 8'd0;
        new_balance = account_balance;
        transaction_status = 4'd0;
        dispense_enable = 1'b0;
        card_eject = 1'b0;
        receipt_print = 1'b0;

        case (current_state)
            IDLE: begin
                transaction_status = 4'd0;  // Ready
                card_eject = 1'b0;
            end

            VERIFY_PIN: begin
                transaction_status = 4'd1;  // Verifying
            end

            SELECT_TRANSACTION: begin
                transaction_status = 4'd2;  // Awaiting selection
            end

            PROCESS_WITHDRAWAL: begin
                case (transaction_approved)
                    1'b1: begin
                        transaction_status = 4'd3;  // Processing
                        dispense_amount = pending_withdraw;
                        new_balance = updated_balance;
                    end
                    default: transaction_status = 4'd4;  // Pending approval
                endcase
            end

            PROCESS_BALANCE: begin
                transaction_status = 4'd5;  // Retrieving balance
                new_balance = updated_balance;
            end

            COMPLETE: begin
                case (menu_select)
                    2'b00: begin  // Withdrawal completed
                        dispense_enable = 1'b1;
                        receipt_print = 1'b1;
                        transaction_status = 4'd6;  // Success - dispense
                        new_balance = updated_balance;
                    end
                    2'b01: begin  // Balance inquiry completed
                        receipt_print = 1'b1;
                        transaction_status = 4'd7;  // Success - balance shown
                        new_balance = updated_balance;
                    end
                    2'b11: begin  // Exit
                        card_eject = 1'b1;
                        transaction_status = 4'd8;  // Complete - card ejected
                    end
                    default: begin
                        transaction_status = 4'd9;  // Complete - other
                        card_eject = 1'b1;
                    end
                endcase
            end

            ERROR: begin
                case (transaction_code)
                    4'd1: transaction_status = 4'd10;  // PIN error
                    4'd2: transaction_status = 4'd11;  // Withdrawal error
                    4'd3: transaction_status = 4'd12;  // Balance error
                    4'd4: transaction_status = 4'd13;  // Deposit error
                    4'd15: transaction_status = 4'd14; // General error
                    default: transaction_status = 4'd15; // Unknown error
                endcase
                card_eject = 1'b1;
                dispense_amount = 8'd0;
            end
        endcase

        // Override for card removal during error or complete
        casez ({current_state, card_inserted})
            {ERROR, 1'b0}: card_eject = 1'b0;
            {COMPLETE, 1'b0}: card_eject = 1'b0;
            default: ;
        endcase
    end

endmodule

module memory_controller #(
    parameter ADDR_WIDTH = 16,
    parameter DATA_WIDTH = 32,
    parameter ECC_WIDTH = 7,  // Hamming code for 32-bit data
    parameter NUM_MASTERS = 4
) (
    // Clock and reset
    input  logic clk,
    input  logic rst_n,

    // Master interfaces
    input  logic [NUM_MASTERS-1:0]        master_req,
    input  logic [NUM_MASTERS-1:0][ADDR_WIDTH-1:0] master_addr,
    input  logic [NUM_MASTERS-1:0]        master_rw,  // 1=write, 0=read
    input  logic [NUM_MASTERS-1:0][DATA_WIDTH-1:0] master_wdata,
    output logic [NUM_MASTERS-1:0]        master_grant,
    output logic [NUM_MASTERS-1:0][DATA_WIDTH-1:0] master_rdata,
    output logic [NUM_MASTERS-1:0]        master_ack,

    // Memory interface
    output logic                          mem_cs,
    output logic                          mem_we,
    output logic [ADDR_WIDTH-1:0]         mem_addr,
    output logic [DATA_WIDTH+ECC_WIDTH-1:0] mem_wdata,
    input  logic [DATA_WIDTH+ECC_WIDTH-1:0] mem_rdata,
    input  logic                          mem_rdy
);

    // Internal state
    typedef enum logic [2:0] {
        IDLE,
        ARB_WAIT,
        CMD_SEND,
        DATA_WAIT,
        DATA_CAPTURE,
        ECC_CHECK,
        RESPONSE
    } state_t;

    state_t current_state, next_state;

    // Arbitration and request tracking
    logic [NUM_MASTERS-1:0] req_latched;
    logic [NUM_MASTERS-1:0] req_priority;
    logic [NUM_MASTERS-1:0] grant_current;
    logic [ADDR_WIDTH-1:0]  active_addr;
    logic                   active_rw;
    logic [DATA_WIDTH-1:0]  active_wdata;
    logic [NUM_MASTERS-1:0] active_master;
    logic [DATA_WIDTH+ECC_WIDTH-1:0] ecc_encoded_data;
    logic [DATA_WIDTH+ECC_WIDTH-1:0] ecc_decoded_data;
    logic [ECC_WIDTH-1:0]   ecc_syndrome;
    logic                   ecc_error;
    logic                   ecc_corrected;

    // Counter for timing
    logic [2:0] wait_counter;
    logic [2:0] wait_target;

    // Pipeline registers
    logic [DATA_WIDTH-1:0] response_data;
    logic [NUM_MASTERS-1:0] response_master;
    logic response_valid;

    //------------------------------------------------------------------------
    // Combinational: Priority encoder for arbitration (using case statements)
    //------------------------------------------------------------------------
    always_comb begin
        req_priority = '0;

        // Fixed priority: Master 0 > Master 1 > Master 2 > Master 3
        // Using nested case statements for priority encoding
        casez (req_latched)
            4'b???1: req_priority = 4'b0001;
            4'b??10: req_priority = 4'b0010;
            4'b?100: req_priority = 4'b0100;
            4'b1000: req_priority = 4'b1000;
            default: req_priority = 4'b0000;
        endcase
    end

    //------------------------------------------------------------------------
    // Combinational: Next state logic
    //------------------------------------------------------------------------
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                if (|req_latched) begin
                    next_state = ARB_WAIT;
                end
            end

            ARB_WAIT: begin
                if (req_priority != '0) begin
                    next_state = CMD_SEND;
                end
            end

            CMD_SEND: begin
                if (mem_rdy) begin
                    next_state = (active_rw) ? DATA_WAIT : DATA_CAPTURE;
                end
            end

            DATA_WAIT: begin
                if (wait_counter == wait_target) begin
                    next_state = DATA_CAPTURE;
                end
            end

            DATA_CAPTURE: begin
                if (mem_rdy) begin
                    next_state = (active_rw) ? RESPONSE : ECC_CHECK;
                end
            end

            ECC_CHECK: begin
                next_state = RESPONSE;
            end

            RESPONSE: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    //------------------------------------------------------------------------
    // Sequential: Main state machine (positive edge)
    //------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            req_latched <= '0;
            active_master <= '0;
            active_addr <= '0;
            active_rw <= 1'b0;
            active_wdata <= '0;
            wait_counter <= '0;
            wait_target <= '0;
            response_data <= '0;
            response_master <= '0;
            response_valid <= 1'b0;
            grant_current <= '0;
        end
        else begin
            current_state <= next_state;

            case (current_state)
                IDLE: begin
                    // Latch all requests
                    req_latched <= master_req;
                    grant_current <= '0;
                    response_valid <= 1'b0;
                    wait_counter <= '0;
                end

                ARB_WAIT: begin
                    // Nothing to do, waiting for priority resolution
                end

                CMD_SEND: begin
                    if (mem_rdy) begin
                        // Clear granted request
                        req_latched <= req_latched & ~grant_current;
                        wait_counter <= '0;

                        // Set timing based on operation type
                        case (active_rw)
                            1'b1: wait_target <= 3'd3;  // Write latency
                            1'b0: wait_target <= 3'd2;  // Read latency
                        endcase
                    end
                end

                DATA_WAIT: begin
                    wait_counter <= wait_counter + 1'b1;
                end

                DATA_CAPTURE: begin
                    if (mem_rdy) begin
                        if (!active_rw) begin
                            // Store read data for ECC check
                            response_data <= ecc_decoded_data[DATA_WIDTH-1:0];
                            response_master <= active_master;
                            response_valid <= 1'b1;
                        end
                    end
                end

                ECC_CHECK: begin
                    // ECC check is combinational, just state transition
                end

                RESPONSE: begin
                    // Generate response signals
                    case (grant_current)
                        4'b0001: master_ack = 4'b0001;
                        4'b0010: master_ack = 4'b0010;
                        4'b0100: master_ack = 4'b0100;
                        4'b1000: master_ack = 4'b1000;
                        default: master_ack = 4'b0000;
                    endcase
                end
            endcase
        end
    end

    //------------------------------------------------------------------------
    // Sequential: Grant generation and active request tracking (positive edge)
    //------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant_current <= '0;
            active_master <= '0;
            active_addr <= '0;
            active_rw <= 1'b0;
            active_wdata <= '0;
        end
        else begin
            case (current_state)
                IDLE: begin
                    grant_current <= '0;
                end

                ARB_WAIT: begin
                    if (req_priority != '0) begin
                        grant_current <= req_priority;

                        // Capture active request details using case
                        case (req_priority)
                            4'b0001: begin
                                active_master <= 4'b0001;
                                active_addr <= master_addr[0];
                                active_rw <= master_rw[0];
                                active_wdata <= master_wdata[0];
                            end
                            4'b0010: begin
                                active_master <= 4'b0010;
                                active_addr <= master_addr[1];
                                active_rw <= master_rw[1];
                                active_wdata <= master_wdata[1];
                            end
                            4'b0100: begin
                                active_master <= 4'b0100;
                                active_addr <= master_addr[2];
                                active_rw <= master_rw[2];
                                active_wdata <= master_wdata[2];
                            end
                            4'b1000: begin
                                active_master <= 4'b1000;
                                active_addr <= master_addr[3];
                                active_rw <= master_rw[3];
                                active_wdata <= master_wdata[3];
                            end
                            default: begin
                                active_master <= '0;
                                active_addr <= '0;
                                active_rw <= 1'b0;
                                active_wdata <= '0;
                            end
                        endcase
                    end
                end

                default: begin
                    // Hold values during operation
                end
            endcase
        end
    end

    //------------------------------------------------------------------------
    // Sequential: ECC encoding for write data (falling edge for pipelining)
    //------------------------------------------------------------------------
    always_ff @(negedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ecc_encoded_data <= '0;
        end
        else begin
            case (current_state)
                CMD_SEND: begin
                    if (active_rw) begin
                        // Generate Hamming code for 32-bit data
                        ecc_encoded_data[DATA_WIDTH-1:0] <= active_wdata;
                        ecc_encoded_data[DATA_WIDTH +: ECC_WIDTH] <= {
                            ^(active_wdata & 32'hAAAAAAAA),  // Even parity for bit0
                            ^(active_wdata & 32'hCCCCCCCC),  // Even parity for bit1
                            ^(active_wdata & 32'hF0F0F0F0),  // Even parity for bit2
                            ^(active_wdata & 32'hFF00FF00),  // Even parity for bit3
                            ^(active_wdata & 32'hFFFF0000),  // Even parity for bit4
                            ^(active_wdata & 32'hFFFFFFFF),  // Overall parity
                            ^(active_wdata & 32'hF0F0F0F0) ^ ^(active_wdata & 32'h0F0F0F0F)
                        };
                    end
                end
                default: begin
                    // Hold
                end
            endcase
        end
    end

    //------------------------------------------------------------------------
    // Combinational: ECC decoding and error detection
    //------------------------------------------------------------------------
    always_comb begin
        ecc_syndrome = '0;
        ecc_error = 1'b0;
        ecc_corrected = 1'b0;
        ecc_decoded_data = mem_rdata;

        // Calculate syndrome using case for each bit
        casez (mem_rdata)
            default: begin
                ecc_syndrome[0] = ^mem_rdata[31:0] ^ mem_rdata[32];
                ecc_syndrome[1] = ^(mem_rdata[31:0] & 32'hAAAAAAAA) ^ mem_rdata[33];
                ecc_syndrome[2] = ^(mem_rdata[31:0] & 32'hCCCCCCCC) ^ mem_rdata[34];
                ecc_syndrome[3] = ^(mem_rdata[31:0] & 32'hF0F0F0F0) ^ mem_rdata[35];
                ecc_syndrome[4] = ^(mem_rdata[31:0] & 32'hFF00FF00) ^ mem_rdata[36];
                ecc_syndrome[5] = ^(mem_rdata[31:0] & 32'hFFFF0000) ^ mem_rdata[37];
                ecc_syndrome[6] = ^mem_rdata ^ mem_rdata[38];
            end
        endcase

        // Error detection and correction
        if (ecc_syndrome != '0) begin
            ecc_error = 1'b1;
            case (ecc_syndrome)
                7'b0000001: begin
                    ecc_corrected = 1'b1;
                    ecc_decoded_data[0] = ~mem_rdata[0];
                end
                7'b0000010: begin
                    ecc_corrected = 1'b1;
                    ecc_decoded_data[1] = ~mem_rdata[1];
                end
                7'b0000100: begin
                    ecc_corrected = 1'b1;
                    ecc_decoded_data[2] = ~mem_rdata[2];
                end
                // Additional cases would cover all 32 data bits and ECC bits
                default: begin
                    // Multi-bit error, cannot correct
                    ecc_corrected = 1'b0;
                end
            endcase
        end
    end

    //------------------------------------------------------------------------
    // Combinational: Output assignments
    //------------------------------------------------------------------------
    always_comb begin
        // Default assignments
        master_grant = '0;
        mem_cs = 1'b0;
        mem_we = 1'b0;
        mem_addr = '0;
        mem_wdata = '0;

        case (current_state)
            IDLE: begin
                // No memory activity
            end

            ARB_WAIT: begin
                // Grant signals to masters
                master_grant = req_priority;
            end

            CMD_SEND: begin
                if (mem_rdy) begin
                    mem_cs = 1'b1;
                    mem_we = active_rw;
                    mem_addr = active_addr;
                    if (active_rw) begin
                        mem_wdata = ecc_encoded_data;
                    end
                end
            end

            DATA_CAPTURE: begin
                if (mem_rdy) begin
                    mem_cs = 1'b1;
                    mem_we = active_rw;
                    mem_addr = active_addr;
                end
            end

            RESPONSE: begin
                // Return data to requesting master
                case (response_master)
                    4'b0001: master_rdata[0] = response_data;
                    4'b0010: master_rdata[1] = response_data;
                    4'b0100: master_rdata[2] = response_data;
                    4'b1000: master_rdata[3] = response_data;
                    default: master_rdata = '0;
                endcase
                master_ack = response_valid ? response_master : '0;
            end

            default: begin
                // Default values
            end
        endcase
    end

endmodule

// Parameterized FIFO with threshold flags
// Demonstrates: separated logic blocks, case statements, no loops
module fifo #(
    parameter DEPTH = 16,           // Number of entries
    parameter DATA_WIDTH = 8,       // Width of data
    parameter ALMOST_THRESHOLD = 4  // Almost full/empty margin
) (
    input logic clk,
    input logic rst_n,
    input logic wr_en,
    input logic rd_en,
    input logic [DATA_WIDTH-1:0] wr_data,
    output logic [DATA_WIDTH-1:0] rd_data,
    output logic full,
    output logic empty,
    output logic almost_full,
    output logic almost_empty
);

    // Local parameters for pointer widths
    localparam PTR_WIDTH = $clog2(DEPTH);
    localparam PTR_MAX   = DEPTH - 1;

    // ------------------------------------------------------------
    // 1. Sequential Block: Pointer Logic
    // ------------------------------------------------------------
    logic [PTR_WIDTH-1:0] wr_ptr, rd_ptr;
    logic [PTR_WIDTH-1:0] wr_ptr_next, rd_ptr_next;
    logic                  wr_ptr_en, rd_ptr_en;
    logic                  wr_ptr_reset, rd_ptr_reset;

    // Write pointer sequential logic
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= '0;
        end else if (wr_ptr_en) begin
            wr_ptr <= wr_ptr_next;
        end
    end

    // Read pointer sequential logic
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rd_ptr <= '0;
        end else if (rd_ptr_en) begin
            rd_ptr <= rd_ptr_next;
        end
    end

    // ------------------------------------------------------------
    // 2. Combinational Block: Status Calculation
    // ------------------------------------------------------------
    logic [PTR_WIDTH:0]  count;           // Current fill level (1 extra bit)
    logic [PTR_WIDTH-1:0] wr_ptr_comb, rd_ptr_comb;
    logic                 full_comb, empty_comb;
    logic                 almost_full_comb, almost_empty_comb;
    logic                 wr_enable, rd_enable;

    // Calculate current fill level using difference between pointers
    // Uses case statement to handle wrap-around without loops
    always_comb begin
        // Default assignments
        wr_ptr_comb = wr_ptr;
        rd_ptr_comb = rd_ptr;
        count = '0;

        // Determine count based on pointer relationship
        // Use casez to handle wrap-around scenarios efficiently
        casez ({wr_ptr, rd_ptr})
            default: begin
                // No wrap: count = wr_ptr - rd_ptr
                count = wr_ptr - rd_ptr;
            end
        endcase

        // Special case: pointers are equal (empty or full)
        if (wr_ptr == rd_ptr) begin
            count = '0;
        end

        // Handle wrap-around case using pointer comparison
        // This is combinational logic without loops
        if (wr_ptr < rd_ptr) begin
            // Wrap occurred: count = (DEPTH - rd_ptr) + wr_ptr
            count = (PTR_MAX - rd_ptr) + wr_ptr + 1;
        end

        // Generate status flags
        empty_comb      = (count == 0);
        full_comb       = (count == DEPTH);
        almost_empty_comb = (count <= ALMOST_THRESHOLD) && (count != 0);
        almost_full_comb  = (count >= (DEPTH - ALMOST_THRESHOLD)) && (count != DEPTH);

        // Generate enable signals with case statement
        // Case for write enable logic
        case ({wr_en, full_comb})
            2'b10: wr_enable = 1'b1;  // Write when enabled and not full
            default: wr_enable = 1'b0;
        endcase

        // Case for read enable logic
        case ({rd_en, empty_comb})
            2'b10: rd_enable = 1'b1;  // Read when enabled and not empty
            default: rd_enable = 1'b0;
        endcase
    end

    // Assign pointer enables
    assign wr_ptr_en = wr_enable;
    assign rd_ptr_en = rd_enable;

    // Assign status outputs
    assign empty = empty_comb;
    assign full = full_comb;
    assign almost_empty = almost_empty_comb;
    assign almost_full = almost_full_comb;

    // ------------------------------------------------------------
    // 3. Combinational Block: Next Pointer Calculation
    // ------------------------------------------------------------
    always_comb begin
        // Default: stay at current value
        wr_ptr_next = wr_ptr;
        rd_ptr_next = rd_ptr;

        // Write pointer next state using case
        case (wr_ptr_en)
            1'b1: begin
                if (wr_ptr == PTR_MAX)
                    wr_ptr_next = '0;
                else
                    wr_ptr_next = wr_ptr + 1;
            end
        endcase

        // Read pointer next state using case
        case (rd_ptr_en)
            1'b1: begin
                if (rd_ptr == PTR_MAX)
                    rd_ptr_next = '0;
                else
                    rd_ptr_next = rd_ptr + 1;
            end
        endcase
    end

    // ------------------------------------------------------------
    // 4. Sequential Block: Memory Array
    // ------------------------------------------------------------
    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    // Write operation
    always_ff @(posedge clk) begin
        if (wr_enable) begin
            mem[wr_ptr] <= wr_data;
        end
    end

    // ------------------------------------------------------------
    // 5. Output Logic: Read Data Mux
    // ------------------------------------------------------------
    // Combinational read with case to select output
    always_comb begin
        // Default value
        rd_data = '0;

        // Use case to select output based on read pointer
        // This synthesizes to a mux without loops
        case (rd_ptr)
            // Note: For large DEPTH, synthesis tool will optimize
            // This demonstrates case usage but in practice would use
            // mem[rd_ptr] directly. Keeping for educational purposes.
            default: rd_data = mem[rd_ptr];
        endcase
    end

    // Alternative: Direct array access (more efficient)
    // assign rd_data = mem[rd_ptr];

endmodule

//------------------------------------------------------------------------------
// AXI4-Lite to APB Bridge Module
// Converts AXI4-Lite transactions to APB protocol.
// Supports configurable data width (32/64-bit) and up to 16 address slaves.
//------------------------------------------------------------------------------
module axi_lite_to_apb #(
    parameter DATA_WIDTH = 32,
    parameter ADDR_WIDTH = 32,
    parameter NUM_SLAVES = 4,
    // APB timing parameters
    parameter P_SETUP_CYCLES = 1,   // Setup cycles in PSELx to PENABLE
    parameter P_ENABLE_CYCLES = 1   // Cycles PENABLE stays high
) (
    // AXI4-Lite Interface
    input  logic                     ACLK,
    input  logic                     ARESETn,
    // AXI Write Address Channel
    input  logic [ADDR_WIDTH-1:0]    AWADDR,
    input  logic [2:0]               AWPROT,
    input  logic                     AWVALID,
    output logic                     AWREADY,
    // AXI Write Data Channel
    input  logic [DATA_WIDTH-1:0]    WDATA,
    input  logic [DATA_WIDTH/8-1:0]  WSTRB,
    input  logic                     WVALID,
    output logic                     WREADY,
    // AXI Write Response Channel
    output logic [1:0]               BRESP,
    output logic                     BVALID,
    input  logic                     BREADY,
    // AXI Read Address Channel
    input  logic [ADDR_WIDTH-1:0]    ARADDR,
    input  logic [2:0]               ARPROT,
    input  logic                     ARVALID,
    output logic                     ARREADY,
    // AXI Read Data Channel
    output logic [DATA_WIDTH-1:0]    RDATA,
    output logic [1:0]               RRESP,
    output logic                     RVALID,
    input  logic                     RREADY,

    // APB Interface
    output logic [ADDR_WIDTH-1:0]    PADDR,
    output logic                     PSELx,
    output logic                     PENABLE,
    output logic                     PWRITE,
    output logic [DATA_WIDTH-1:0]    PWDATA,
    output logic [DATA_WIDTH/8-1:0]  PSTRB,
    input  logic [DATA_WIDTH-1:0]    PRDATA,
    input  logic                     PREADY,
    input  logic                     PSLVERR
);

    // State machine encoding
    typedef enum logic [2:0] {
        IDLE        = 3'b000,
        WR_SETUP    = 3'b001,
        WR_ENABLE   = 3'b010,
        WR_RESPONSE = 3'b011,
        RD_SETUP    = 3'b100,
        RD_ENABLE   = 3'b101,
        RD_RESPONSE = 3'b110
    } state_t;

    state_t state, next_state;

    // Address decoding for slave select
    logic [NUM_SLAVES-1:0] addr_decode;
    logic [ADDR_WIDTH-1:0] apb_addr_reg;
    logic [DATA_WIDTH-1:0] write_data_reg;
    logic [DATA_WIDTH/8-1:0] write_strb_reg;
    logic write_op_pending, read_op_pending;
    logic [1:0] write_resp, read_resp;

    // APB timing counters
    logic [7:0] setup_cnt, enable_cnt;

    //--------------------------------------------------------------------------
    // Address decoding logic
    //--------------------------------------------------------------------------
    always_comb begin
        addr_decode = '0;
        // Simple address decoding based on top bits (assumes equally sized regions)
        for (int i = 0; i < NUM_SLAVES; i++) begin
            if (apb_addr_reg[ADDR_WIDTH-1:ADDR_WIDTH-$clog2(NUM_SLAVES)] == i)
                addr_decode[i] = 1'b1;
        end
    end

    //--------------------------------------------------------------------------
    // State machine sequential block
    //--------------------------------------------------------------------------
    always_ff @(posedge ACLK or negedge ARESETn) begin
        if (!ARESETn) begin
            state <= IDLE;
            setup_cnt <= '0;
            enable_cnt <= '0;
            apb_addr_reg <= '0;
            write_data_reg <= '0;
            write_strb_reg <= '0;
            write_op_pending <= 1'b0;
            read_op_pending <= 1'b0;
            write_resp <= 2'b00;
            read_resp <= 2'b00;
        end else begin
            state <= next_state;

            // APB timing counters
            case (state)
                WR_SETUP, RD_SETUP: begin
                    if (setup_cnt < P_SETUP_CYCLES - 1)
                        setup_cnt <= setup_cnt + 1;
                    else
                        setup_cnt <= '0;
                end
                WR_ENABLE, RD_ENABLE: begin
                    if (enable_cnt < P_ENABLE_CYCLES - 1)
                        enable_cnt <= enable_cnt + 1;
                    else
                        enable_cnt <= '0;
                end
                default: begin
                    setup_cnt <= '0;
                    enable_cnt <= '0;
                end
            endcase

            // Register APB data/address for ongoing transaction
            if (next_state == WR_SETUP && state == IDLE) begin
                apb_addr_reg <= AWADDR;
                write_data_reg <= WDATA;
                write_strb_reg <= WSTRB;
                write_op_pending <= 1'b1;
            end else if (next_state == RD_SETUP && state == IDLE) begin
                apb_addr_reg <= ARADDR;
                read_op_pending <= 1'b1;
            end

            // Capture response from APB
            if (state == WR_ENABLE && PREADY) begin
                write_resp <= PSLVERR ? 2'b10 : 2'b00; // SLVERR -> AXI SLVERR
                write_op_pending <= 1'b0;
            end else if (state == RD_ENABLE && PREADY) begin
                read_resp <= PSLVERR ? 2'b10 : 2'b00;
                read_op_pending <= 1'b0;
            end
        end
    end

    //--------------------------------------------------------------------------
    // State machine combinational block with case statements
    //--------------------------------------------------------------------------
    always_comb begin
        next_state = state;

        case (state)
            IDLE: begin
                if (AWVALID && WVALID && !write_op_pending)
                    next_state = WR_SETUP;
                else if (ARVALID && !read_op_pending)
                    next_state = RD_SETUP;
            end

            WR_SETUP: begin
                if (setup_cnt == P_SETUP_CYCLES - 1)
                    next_state = WR_ENABLE;
            end

            WR_ENABLE: begin
                if (PREADY && (enable_cnt == P_ENABLE_CYCLES - 1))
                    next_state = WR_RESPONSE;
            end

            WR_RESPONSE: begin
                if (BREADY)
                    next_state = IDLE;
            end

            RD_SETUP: begin
                if (setup_cnt == P_SETUP_CYCLES - 1)
                    next_state = RD_ENABLE;
            end

            RD_ENABLE: begin
                if (PREADY && (enable_cnt == P_ENABLE_CYCLES - 1))
                    next_state = RD_RESPONSE;
            end

            RD_RESPONSE: begin
                if (RREADY)
                    next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    //--------------------------------------------------------------------------
    // APB control signals using case statements
    //--------------------------------------------------------------------------
    always_comb begin
        // Default values
        PSELx = 1'b0;
        PENABLE = 1'b0;
        PWRITE = 1'b0;
        PADDR = apb_addr_reg;
        PWDATA = write_data_reg;
        PSTRB = write_strb_reg;

        case (state)
            WR_SETUP: begin
                PSELx = |addr_decode;
                PENABLE = 1'b0;
                PWRITE = 1'b1;
            end
            WR_ENABLE: begin
                PSELx = |addr_decode;
                PENABLE = 1'b1;
                PWRITE = 1'b1;
            end
            RD_SETUP: begin
                PSELx = |addr_decode;
                PENABLE = 1'b0;
                PWRITE = 1'b0;
            end
            RD_ENABLE: begin
                PSELx = |addr_decode;
                PENABLE = 1'b1;
                PWRITE = 1'b0;
            end
            default: begin
                PSELx = 1'b0;
                PENABLE = 1'b0;
            end
        endcase
    end

    //--------------------------------------------------------------------------
    // AXI handshake and response logic with case statements
    //--------------------------------------------------------------------------
    always_comb begin
        // Default values
        AWREADY = 1'b0;
        WREADY = 1'b0;
        ARREADY = 1'b0;
        BVALID = 1'b0;
        RVALID = 1'b0;
        BRESP = 2'b00;
        RRESP = 2'b00;
        RDATA = '0;

        case (state)
            IDLE: begin
                AWREADY = 1'b1;
                WREADY = 1'b1;
                ARREADY = 1'b1;
            end

            WR_RESPONSE: begin
                BVALID = 1'b1;
                case (write_resp)
                    2'b00: BRESP = 2'b00; // OKAY
                    2'b10: BRESP = 2'b10; // SLVERR
                    default: BRESP = 2'b11; // DECERR
                endcase
            end

            RD_RESPONSE: begin
                RVALID = 1'b1;
                case (read_resp)
                    2'b00: RRESP = 2'b00; // OKAY
                    2'b10: RRESP = 2'b10; // SLVERR
                    default: RRESP = 2'b11; // DECERR
                endcase
                RDATA = PRDATA;
            end

            default: begin
                // No additional handshakes in other states
            end
        endcase
    end

endmodule
